(window.GIM_TS=window.GIM_TS||{})["Chagigah.0"]={"from":0,"a":[["\u0003הכל חייבין\u0004 בשלושת הרגלים \u0003ב\u0004מצוות \u0003ראייה\u0004 — להיראות ולהקריב בבית המקדש, \u0003חוץ מחרש, שוטה, וקטן, וטומטום\u0004 (מי שאין אברי המין שלו ניכרים) \u0003ואנדרוגינוס\u0004 (שיש לו סימני זכר ונקיבה), \u0003ונשים, ועבדים שאינם משוחררים, החיגר\u0004 (שרגליו פגומות), \u0003והסומא\u0004 (העיוור), \u0003והחולה, והזקן, ומי שאינו יכול לעלות ברגליו\u0004 מטעם אחר.","\u0003איזהו קטן\u0004 לענין זה שאיננו חייב בראייה — \u0003כל\u0004 תינוק \u0003שאינו יכול לרכוב על כתפיו של אביו ולעלות\u0004 כך \u0003מירושלים להר הבית,\u0004 אלו \u0003דברי בית שמאי. ובית הלל אומרים: כל שאינו יכול לאחוז בידו של אביו ולעלות\u0004 ברגל \u0003מירושלים להר הבית, שנאמר: \"שלש רגלים\"\u0004 (שמות כג, יד), משמע שהחובה היא לעלות ברגליים דווקא.","\u0003בית שמאי אומרים:\u0004 קרבן \u0003הראייה,\u0004 שהוא קרבן עולה שמביא העולה לרגל, בבואו להיראות במקדש, חייב להיות בשווי של לפחות \u0003שתי כסף, ו\u0004קרבן \u0003החגיגה\u0004 שהוא קרבן שלמים שמביאים בחג — לפחות \u0003מעה כסף. ובית הלל אומרים:\u0004 שווי עולת \u0003הראייה\u0004 צריך להיות \u0003מעה כסף\u0004 לפחות, \u0003והחגיגה שתי כסף\u0004 לפחות.","שנינו במשנה כי הכל חייבין בראייה, ושואלים: \u0003\"הכל\" לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה],\u0006 מה מוסיפים על ידי תוספת המלה \"הכל\"? ומסבירים: \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 את \u0003מי ש\u0004הוא \u0003חציו עבד וחציו בן חורין,\u0004 שכיון שחציו בן חורין חייב הוא בכל אופן בעלייה לרגל. ושואלים: \u0003ול\u0004דעת \u0003רבינא\u0004 ש\u0003אמר\u0004 כי \u0003מי שחציו עבד וחציו בן חורין פטור מן הראייה,\u0004 אם כן \u0003\"הכל\" לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 עוד? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 מי שהיה \u0003חיגר ביום\u0004 ה\u0003ראשון\u0004 של הרגל ולא יכול היה לעלות, \u0003ונתפשט\u0004 (ונתרפא) \u0003ביום\u0004 ה\u0003שני\u0004 של החג, שגם הוא חייב לעלות.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 שכל שבעת ימי החג \u0003כולן\u0004 הם \u0003תשלומין זה לזה,\u0004 וחובת העליה והראייה חלה על כל ימי החג בשוה, ולכן מי שלא יכול לעלות בראשון עולה בשני. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שהחיוב הוא בעיקרו ביום הראשון ושאר הימים \u0003כולן תשלומין\u0004 של היום ה\u0003ראשון\u0004 הם, ולכן מי שהיה פטור מלעלות ביום הראשון של החג שוב אינו צריך לעלות, אם כן \u0003\"הכל\" לאתויי מאי\u0004 \u0005[להביא את מה]?\u0006 ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003סומא\u0004 (עיוור) \u0003באחת מעיניו\u0004 שגם הוא חייב לעלות.","ומעירים: \u0003ודלא כי האי תנא\u0004 \u0005[ושלא כ\u0006שיטתו \u0005של תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יוחנן בן דהבאי אומר משום ר' יהודה: סומא באחת מעיניו פטור מן הראייה, שנאמר:\u0004 \"שלוש פעמים בשנה \u0003יראה\u0004 כל זכורך\" (שמות כג, יח), ועל פי ה\"כתיב\" בספר התורה אפשר לקרוא \u0003\"יראה\u0004 כל זכורך את פני האדון ה' \u0003\"\u0004, ואילו הקריאה לפי המסורת היא \"יראה\", ודורשים: \u0003כדרך שבא לראות כך בא ליראות, מה\u0004 כשבא \u0003לראות\u0004 דרכה של ראייה היא \u0003בשתי עיניו, אף ליראות — בשתי עיניו,\u0004 ומי שסומא באחת מהן איננו חייב לעלות ליראות ברגל.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם כדאמרי מעיקרא\u0004 \u0005[כפי שאמרו מתחילה]\u0006 שבא לרבות בחיוב עליה לרגל מי שחציו עבד וחציו בן חורין, \u0003ודקא קשיא לך הא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה לך\u0006 מ\u0005זה]\u0006 שאמר \u0003רבינא — לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 כי \u0003כאן\u0004 במשנתנו — נאמרו הדברים \u0003כ\u0004שיטת \u0003משנה ראשונה, כאן\u0004 מה שאמר רבינא — הוא \u0003כמשנה אחרונה.\u0004 וביאור הדבר — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 \u0003במשנה\u0004\u0005]:\u0006 \u0003מי שחציו עבד וחציו בן חורין — עובד את\u0004 (בשביל) \u0003רבו\u0004 (אדוניו) שהוא משועבד לו \u0003יום אחד,\u0004 ובגלל היותו חציו בן חורין הוא עובד \u0003את\u0004 (בשביל) \u0003עצמו יום אחד\u0004 לסירוגין, אלו \u0003דברי בית הלל.\u0004","\u0003אמרו להם בית שמאי:\u0004"],["\u0003תקנתם\u0004 בכך \u0003את רבו,\u0004 כלומר, מצאתם תקנה שהיא מועילה לרבו של העבד, \u0003ואת עצמו לא תקנתם.\u0004 ומדוע; \u0003לישא שפחה אינו יכול,\u0004 שכן הוא בן חורין למחצה, וישראל אסור בשפחה, וכמו כן לישא \u0003בת חורין אינו יכול,\u0004 שהוא אסור בה כיון שהוא חציו עבד,","\u0003ליבטיל\u0004 \u0005[שייבטל]\u0006 מפריה ורביה ולא ישא אשה כלל? — \u0003והלא לא נברא העולם אלא לפריה ורביה, שנאמר: \"לא תהו בראה לשבת יצרה\"\u0004 (ישעיהו מה, יח). \u0003אלא, מפני תיקון העולם\u0004 כלומר, לשם תקנתו של העבד \u0003כופין\u0004 (מכריחים) \u0003את רבו, ועושה אותו בן חורין,\u0004 כלומר, משחרר את החלק השייך לו, \u0003וכותב לו\u0004 העבד \u0003שטר\u0004 חוב \u0003על חצי דמיו\u0004 (שוויו, מחירו) ומשלם לאדון. \u0003וחזרו\u0004 לבסוף \u0003בית הלל להורות כדברי בית שמאי,\u0004 שיש לשחרר עבד כזה, ודברי רבינא הם לפי המשנה האחרונה כשיטת בית הלל לאחר חזרה, וכיון שחובה על בעליו לשחררו ועדיין אינו משוחרר לגמרי — פטור מן הראייה.","שנינו במשנה: הכל חייבין בראיה \u0003חוץ מחרש שוטה וקטן.\u0004 ומעירים: \u0003קתני\u0004 \u0005[שנה]\u0006 פה \u0003חרש דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003שוטה וקטן,\u0004 ומסמיכות זו אפשר ללמוד: \u0003מה שוטה וקטן דלאו\u0004 \u0005[שלא]\u0006 \u0003בני דעה\u0004 הם כלל, \u0003אף חרש\u0004 שמדובר בו פה — \u0003דלאו בר\u0004 \u0005[שלא בן]\u0006 \u0003דעה הוא. וקא משמע לן\u0004 \u0005[והשמיע לנו]\u0006 בכך \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]\u0006 אחרת: \u0003חרש שדיברו חכמים בכל מקום\u0004 הוא אדם \u0003שאינו שומע ואינו מדבר\u0004 ובשל כך דעתו איננה צלולה. ומכאן נדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם מי שהוא \u0003מדבר ואינו שומע,\u0004 או \u0003שומע ואינו מדבר — הריהו חייב\u0004 במצוות, ככל אדם אחר.","ומעירים: \u0003תנינא להא\u0004 \u0005[שנינו\u0006 דבר \u0005זה]\u0006 במקום אחר, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בברייתא: \u0003המדבר ואינו שומע — זהו\u0004 הקרוי \u0003חרש, שומע ואינו מדבר — זהו אלם, זה וזה,\u0004 חרש ואילם אלה, \u0003הרי הן כפקחין לכל דבריהם\u0004 (דיניהם), ומכאן שחרש שדנו בו חכמים בכל מקום הוא מי שאינו שומע ואינו מדבר.","לעצם לשון הברייתא שואלים: \u0003וממאי\u0004 \u0005[וממה,\u0006 כיצד\u0005]\u0006 יודע אתה ש\u0003מדבר ואינו שומע זהו חרש, שומע ואינו מדבר זהו אלם? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואני כחרש לא אשמע וכאלם לא יפתח פיו\"\u0004 (תהלים לח, יד), ומכאן שחרש הוא מי שאינו שומע, ואילם — שאינו מדבר. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003כדאמרי אינשי\u0004 \u0005[כפי שאומרים אנשים]\u0006 בביטוי מקובל: \u0003אישתקיל מילוליה\u0004 \u0005[ניטל דיבורו],\u0006 ו\"אילם\" הוא כקיצור, נוטריקון, של המילים \"אישתקיל מילוליה\".","שנינו שה\u0003מדבר ואינו שומע\u0004 או ה\u0003שומע ואינו מדבר חייב.\u0004 ושואלים \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מדבר ואינו שומע, שומע ואינו מדבר — פטור!\u0004","\u0003אמר רבינא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רבא: חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך\u0006 יש \u0005לשנותה]:\u0006 \u0003הכל חייבין בראייה ובשמחה,\u0004 אכילת בשר קדשים בימי החג, \u0003חוץ מחרש המדבר ואינו שומע,\u0004 או \u0003שומע ואינו מדבר, שפטור מן הראייה, ואף על פי שפטור מן הראייה חייב בשמחה. ו\u0004אולם \u0003את שאינו לא שומע ולא מדבר, ו\u0004כן \u0003שוטה וקטן — פטור אף מן השמחה, הואיל ופטורים\u0004 אלה \u0003מכל מצות האמורות בתורה\u0004 לפי שאינם בני דעת.","ומביאים לכך סיוע, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003הכל חייבין בראייה ובשמחה, חוץ מחרש המדבר ואינו שומע, שומע ואינו מדבר, שפטורין מן הראייה. ואף על פי שפטור מן הראייה\u0004 —"],["\u0003חייב בשמחה. ואת שאינו לא שומע ולא מדבר, ושוטה וקטן — פטורין אף מן השמחה, הואיל ופטורין מכל מצות האמורות בתורה.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003לענין ראיה דפטירי\u0004 \u0005[שפטורים]\u0006 ממנה החרש והאילם, \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003לענין שמחה דמחייבי\u0004 \u0005[ש\u0006הם \u0005מחוייבים]?\u0006","ומסבירים: \u0003לענין\u0004 מיעוטם מחיוב \u0003ראיה גמר\u0004 \u0005[לומד\u0006 הוא\u0005]\u0006 בגזירה שווה של המילים \u0003\"ראיה\" \"ראיה\" מ\u0004דין \u0003הקהל, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"הקהל את העם האנשים והנשים והטף\"\u0004 (דברים לא, יב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"בבוא כל ישראל לראות\"\u0004 (דברים לא, יא), ואם כן נזכרה שם לשון \"ראייה\", ומדין זה לומדים גם למצוות הראייה ברגל.","ושואלים: \u0003והתם מנלן\u0004 \u0005[ושם\u0006 בהקהל \u0005מניין לנו]\u0006 שחרש ואילם פטורים? — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במצוות הקהל: \u0003\"למען ישמעו ולמען ילמדו\"\u0004 (דברים לא, יב), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"למען ישמעו\"\u0004 — לומר שחובה זו היא \u0003פרט למדבר ואינו שומע, \"ולמען ילמדו\" — פרט לשומע ואינו מדבר,\u0004 שאינו יכול ללמוד.","ותוהים: \u0003למימרא דכי לא משתעי לא גמר\u0004 \u0005[האם לומר שכאשר איננו מדבר איננו\u0006 יכול \u0005ללמוד]?\u0006 \u0003והא הנהו תרי אילמי דהוו בשבבותיה\u0004 \u0005[והרי אותם שני אילמים שהיו בשכנותו]\u0006 של \u0003רבי,\u0004 שהיו \u0003בני ברתיה\u0004 \u0005[בתו]\u0006 של \u0003ר' יוחנן בן גודגדא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיו \u0003בני אחתיה\u0004 \u0005[אחותו]\u0006 של \u0003ר' יוחנן\u0004 בן גודגדא, \u0003דכל אימת דהוה עייל\u0004 \u0005[שבכל פעם שהיה נכנס]\u0006 \u0003רבי לבי מדרשא\u0004 \u0005[לבית המדרש]\u0006 \u0003הוו עיילי ויתבי קמייהו\u0004 \u0005[היו נכנסים ויושבים לפניהם,\u0006 לפני החכמים\u0005]\u0006 \u0003ומניידי ברישייהו ומרחשין שפוותייהו\u0004 \u0005[ו\u0006היו \u0005מנידים בראשיהם\u0006 כמבינים, \u0005ומרחשים,\u0006 מנענעים \u0005בשפתותיהם],\u0006","\u0003ובעי\u0004 \u0005[וביקש]\u0006 \u0003רבי רחמי עלייהו\u0004 \u0005[רחמים עליהם]\u0006 משמים \u0003ואיתסו\u0004 \u0005[והתרפאו],\u0006 \u0003ואשתכח דהוו גמירי\u0004 \u0005[ונמצא שהיו למודים,\u0006 יודעים\u0005]\u0006 \u0003הלכתא\u0004 \u0005[הלכה]\u0006 (משניות) \u0003וספרא\u0004 (מדרש ההלכה לספר ויקרא), \u0003וספרי\u0004 (מדרש ההלכה לספרי במדבר ודברים), \u0003וכולה תלמודא\u0004 \u0005[ו\u0006את \u0005כל התלמוד],\u0006 משמע שגם מי שאיננו יודע לדבר יכול ללמוד!","\u0003אמר מר זוטרא: קרי ביה\u0004 \u0005[קרא בו]\u0006 בפסוק זה \u0003\"למען ילמדו\",\u0004 ואילם אף שהוא עצמו יכול ללמוד, אינו יכול ללמד אחרים. \u0003רב אשי אמר: ודאי \"למען ילמדו\" הוא,\u0004 כלומר, ש\"למען ילמדו\" האמור שם בהכרח צריך להבין למען ילמדו אחרים, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר \u0003\"למען ילמדו\",\u0004 ככתוב, \u0003ו\u0004נפרש ש\u0003כיון דלא משתעי\u0004 \u0005[שאינו מדבר]\u0006 \u0003לא גמר\u0004 \u0005[אינו\u0006 יכול \u0005ללמוד],\u0006 והטעם לכך הוא ש\u0003כיון דלא שמע\u0004 \u0005[שאינו שומע]\u0006 ודאי \u0003לא גמר\u0004 \u0005[איננו לומד],\u0006","ואם כן \u0003האי\u0004 \u0005[\u0006דין \u0005זה]\u0006 \u0003מ\"למען ישמעו\" נפקא\u0004 \u0005[יוצא],\u0006 ו\"למען ילמדו\" לכאורה מיותר! \u0003אלא ודאי\u0004 שהכוונה \u0003\"למען ילמדו\" הוא,\u0004 ולכן אף שהאילם יכול ללמוד בעצמו אינו יכול ללמד, ו\"למען ישמעו\" בא להוציא חרש, \"ולמען ילמדו\" במשמעות ילמדו בא להוציא אילם.","\u0003אמר ר' תנחום: חרש\u0004 אפילו \u0003באזנו אחת — פטור מן הראיה, שנאמר \"באזניהם\"\u0004 (דברים לא, יא), ומשמע שיש לשמוע בשתי האוזניים, ומי שאיננו שומע בשתי אוזניו פטור.","ושואלים: \u0003האי\u0004 \u0005[\u0006ביטוי \u0005זה]\u0006 \u0003\"באזניהם\"\u0004 בלשון ריבוי הלא \u0003מבעי ליה\u0004 \u0005[צריך לו]\u0006 ללמדנו שידבר \u0003באזניהם דכולהו\u0004 \u0005[של כל]\u0006 \u0003ישראל!\u0004 ומשיבים: הרעיון \u0003ההוא, מ\u0004המילים \u0003\"נגד כל ישראל\"\u0004 (דברים לא, יא) \u0003נפקא\u0004 \u0005[יוצא].\u0006 ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 היה כתוב רק \u0003מ\"נגד כל ישראל\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003אף על גב דלא שמעי\u0004 \u0005[אף על פי שאינם שומעים],\u0006 ולכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"באזניהם\"\u0004 — ללמדנו \u0003והוא דשמעי\u0004 \u0005[ש\u0006הם \u0005שומעים]!\u0006","ודוחים: הרעיון \u0003ההוא\u0004 שצריך שישמעו, \u0003מ\u0004מה שנאמר \u0003\"למען ישמעו\"\u0004 (דברים לא, יב) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 שחייבים הם לשמוע, ואם כן \"באזניהם\" בא ללמד שרק השומעים בשתי אוזניים חייבים בראייה.","ו\u0003אמר ר' תנחום: חיגר ברגלו אחת\u0004 — \u0003פטור מן הראיה, שנאמר \"רגלים\"\u0004 (שמות כג, יד), ולא נאמר \"זמנים\", ללמדנו שעולים דווקא בשתי רגליים.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"רגלים\" מבעי ליה\u0004 \u0005[נחוץ לו]\u0006 ללימוד: \u0003פרט לבעלי קבין,\u0004 כלומר, בעלי רגל תותבת, אף שיכולים ללכת, כיון שאין להם רגליים פטורים מלעלות! ומשיבים: הדין \u0003ההוא מ\u0004מה שנאמר \u0003\"פעמים\"\u0004 (שמות כג, יז) \u0003נפקא\u0004 \u0005[\u0006הוא \u0005יוצא,\u0006 נלמד\u0005],\u0006 ש\"פעמים\" יש לו גם משמעות רגליים, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 במשמעות המלה \u0003\"פעמים\": אין \"פעמים\" אלא רגלים, וכן הוא אומר: \"תרמסנה רגל רגלי עני פעמי דלים\"\u0004 (ישעיהו כו, ו). \u0003ואומר: \"מה יפו פעמיך בנעלים בת נדיב\"\u0004 (שיר השירים ז, ב).","כיון שהוזכר פסוק זה לענייננו מביאים עוד מה שנאמר עליו; \u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"מה יפו פעמיך בנעלים בת נדיב\" — כמה נאין רגליהן\u0004 (\"פעמיהם\") \u0003של ישראל בשעה שעולין לרגל. \"בת נדיב\"\u0004 — זו היא \u0003בתו של אברהם אבינו שנקרא נדיב, שנאמר: \"נדיבי עמים נאספו עם אלהי אברהם\"\u0004 (תהלים מז, י) ושואלים, מפני מה נאמר: \u0003\"אלהי אברהם\" ולא \"אלהי יצחק ויעקב\"? אלא\u0004 כך יש להבין: \u0003אלהי אברהם — שהיה תחילה לגרים\u0004 ועל שמו נקראים הגרים (\"נדיבי עמים\") שנדב לבם אותם להצטרף לעם ישראל.","כיון שהביאו את דברי ר' תנחום מביאים עוד בשמו; \u0003אמר רב כהנא, דרש רב נתן בר מניומי משום\u0004 (משמו של) \u0003ר' תנחום: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 ביוסף \u0003\"והבור רק אין בו מים\"\u0004 (בראשית לז, כד), \u0003ממשמע שנאמר \"והבור רק\" איני יודע שאין בו מים? אלא\u0004 יש לראות זאת כהדגשה לענין אחר: \u0003מים אין בו, אבל נחשים ועקרבים יש בו.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בר' יוחנן בן ברוקה ור' אלעזר בן חסמא שהלכו להקביל פני ר' יהושע בפקיעין. אמר להם\u0004 ר' יהושע: \u0003מה חידוש היה בבית המדרש היום? אמרו לו: תלמידיך אנו ומימיך אנו שותין,\u0004 וכיון שכולנו תלמידיך וממך תלמודנו, כיצד אפשר לומר לך דבר שלא שמעת. \u0003אמר להם: אף על פי כן, אי אפשר לבית המדרש בלא חידוש.\u0004","\u0003שבת של מי היתה,\u0004 מי היה הדורש בשבת זו? אמרו לו: \u0003שבת של ר' אלעזר בן עזריה היתה.\u0004 שאל אותם: \u0003ובמה היתה הגדה היום? אמרו לו: בפרשת הקהל.\u0004 שאל: \u0003ומה דרש בה?\u0004","אמרו לו: נאמר \u0003\"הקהל את העם האנשים והנשים והטף\"\u0004 (דברים לא, יב), ויש לשאול: \u0003אם אנשים באים ללמוד, נשים\u0004 שלא כולן מבינות \u0003באות\u0004 לפחות \u0003לשמוע, טף למה באין?\u0004 והתשובה היא — \u0003כדי ליתן שכר למביאיהן,\u0004 שזיכה הקדוש ברוך הוא במצוה את אלה שמביאים את הטף. \u0003אמר להם\u0004 ר' יהושע לשני תלמידיו: \u0003מרגלית טובה\u0004 זו \u0003היתה בידכם, ובקשתם לאבדה ממני\u0004 ולא סיפרתם לי?","כיון שראו שהוא שמח לשמוע דברים אלה שנתחדשו בבית המדרש, אמרו לו: \u0003ועוד דרש\u0004 ר' אלעזר: נאמר \u0003\"את ה' האמרת היום\"\u0004 (דברים כו, יז) \u0003\"וה' האמירך היום\"\u0004 (דברים כו, יח),","\u0003אמר להם הקדוש ברוך הוא לישראל: אתם עשיתוני חטיבה\u0004 (דבר מיוחד) \u0003אחת בעולם\u0004 על ידי אמונתכם בי \u0003ואני אעשה אתכם חטיבה אחת בעולם\u0004 בין העמים. ופירושו: \u0003אתם עשיתוני חטיבה אחת בעולם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שמע ישראל ה' אלהינו ה' אחד\"\u0004 (דברים ו, ד), \u0003ו\u0004אף \u0003אני אעשה אתכם חטיבה אחת בעולם, שנאמר:\u0004"],["\u0003\"ומי כעמך ישראל גוי אחד בארץ\"\u0004 (דברי הימים א' יז, כא) ופירוש \"אחד\" הוא מיוחד.","ועוד הוסיפו: \u0003ואף הוא\u0004 ר' אלעזר בן עזריה \u0003פתח ודרש:\u0004 נאמר, \u0003\"דברי חכמים כדרבנות וכמסמרות נטועים בעלי אספות נתנו מרעה אחד\"\u0004 (קהלת יב, יא), \u0003למה נמשלו דברי תורה לדרבן — לומר לך: מה דרבן זה מכוון את הפרה לתלמיה\u0004 והיא חורשת וגורמת בדרך \u0003להוציא חיים\u0004 (מזון מן האדמה) \u0003לעולם — אף דברי תורה מכוונין את לומדיהן מדרכי מיתה לדרכי חיים.\u0004 אולם, \u0003אי\u0004 \u0005[או]\u0006 \u0003מה דרבן זה מטלטל\u0004 ואיננו קבוע \u0003אף דברי תורה מטלטלין\u0004 לפי הנסיבות — \u0003תלמוד לומר\u0004 בהמשך הכתוב הזה: \u0003\"מסמרות\",\u0004 שהם קבועים לעד.","ומאידך, אפשר לומר \u0003אי\u0004 \u0005[או]\u0006 \u0003מה מסמר זה חסר ולא יתר\u0004 שהוא מתכלה עם הזמן ואינו גדל \u0003אף דברי תורה חסרין ולא יתירין — תלמוד לומר: \"נטועים\"\u0004 (קהלת יב, יא), \u0003מה נטיעה זו פרה ורבה\u0004 וגדלה \u0003אף דברי תורה פרין ורבין. \"בעלי אספות\" — אלו תלמידי חכמים שיושבין אסופות אסופות\u0004 (קבוצות קבוצות) \u0003ועוסקין בתורה.\u0004 ואף שבין החכמים יש לעתים מחלוקות, \u0003הללו מטמאין והללו מטהרין, הללו אוסרין והללו מתירין, הללו פוסלין והללו מכשירין,\u0004","אם כן \u0003שמא יאמר אדם: היאך אני למד תורה מעתה\u0004 כאשר יש בה כל כך הרבה מחלוקות וחילוקי דעות — \u0003תלמוד לומר: \"כולם נתנו מרעה אחד\"\u0004 (קהלת יב, יא), לומר: \u0003אל אחד נתנן, פרנס אחד\u0004 (משה רבינו) \u0003אמרן, מפי אדון כל המעשים ברוך הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וידבר אלהים את כל הדברים האלה\"\u0004 (שמות כ, א), ולשון הריבוי בכתוב, כלומר: את כל הדברים, על כל שינוייהם ומחלוקותיהם.","\u0003אף אתה,\u0004 הלומד, \u0003עשה אזניך כאפרכסת\u0004 (הכלי שבו שופכים את גרגירי התבואה לרחיים), \u0003וקנה לך לב מבין לשמוע\u0004 גם \u0003את דברי מטמאים ו\u0004גם \u0003את דברי מטהרים, את דברי\u0004 ה\u0003אוסרין ואת דברי\u0004 ה\u0003מתירין, את דברי\u0004 ה\u0003פוסלין ואת דברי\u0004 ה\u0003מכשירין.\u0004 כששמע ר' יהושע דברים אלה, \u0003בלשון הזה אמר להם: אין דור\u0004 נחשב \u0003יתום\u0004 (בלא אב ומדריך) כאשר \u0003ר' אלעזר בן עזריה שרוי בתוכו.\u0004","ושואלים: כיון שהיו בידם דברים יפים אלה מפי ר' אלעזר בן עזריה, \u0003ולימרו ליה בהדיא\u0004 \u0005[ושיאמרו לו במישרין,\u0006 מיד\u0005]\u0006 מה שמעו בדרשה ומפני מה הססו תחילה לומר לו? ומשיבים: \u0003משום מעשה שהיה\u0004 חששו לומר זאת. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה בר' יוסי בן דורמסקית שהלך להקביל פני ר' אלעזר בלוד, אמר לו\u0004 ר' אלעזר: \u0003מה חידוש היה בבית המדרש היום?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נמנו\u0004 הצביעו ומנו את הדעות \u0003וגמרו\u0004 (החליטו) ש\u0003עמון ומואב\u0004 בעבר הירדן, מאחר שאינם חלק מארץ ישראל אין דין שמיטה ומעשרות חל עליהם, ומכל מקום כיון שסמוכים לארץ ישראל \u0003מעשרין מעשר עני ב\u0004שנת ה\u0003שביעית\u0004 (השמיטה), והיו צריכים להחליט על כך, משום שנחלקו איזה מן המעשרות צריכים הם להפריש.","\u0003אמר לו\u0004 ר' אלעזר בכעס: \u0003יוסי, פשוט ידיך וקבל עיניך,\u0004 שיצאו עיניו ממקומן ויפלו לתוך ידיו. ואכן כך אירע לו, \u0003פשט\u0004 את \u0003ידיו וקבל עיניו. בכה ר' אלעזר ואמר:\u0004 נאמר \u0003\"סוד ה' ליראיו ובריתו להודיעם\"\u0004 (תהלים כה, יד), שהם מכוונים לאמת אף בלי לדעת את הסיבות האמיתיות.","\u0003אמר לו: לך אמור להם\u0004 לחכמים בבית המדרש: \u0003אל תחושו למניינכם\u0004 שמא לא החלטתם כהלכה, שאתם סבורים שתקנתם תקנה חדשה, \u0003כך מקובלני מרבן יוחנן בן זכאי, ששמע מרבו ורבו מרבו: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003למשה מסיני\u0004 ש\u0003עמון ומואב מעשרין מעשר עני בשביעית.\u0004 ו\u0003מה טעם\u0004 — משום ש\u0003הרבה כרכים כבשום עולי מצרים\u0004 בימי יהושע \u0003ולא כבשום עולי בבל\u0004 בימי בית השני,","\u0003מפני שקדושה ראשונה\u0004 שנתקדשה ארץ ישראל עם כיבושה על ידי יהושע \u0003קדשה לשעתה\u0004 כל עוד ישבו ישראל בארצם \u0003ולא קדשה לעתיד לבא\u0004 לאחר חזרתם מן הגלות, \u0003והניחום\u0004 עולי בבל את המקומות הללו שלא כבשו \u0003כדי שיסמכו עליהן עניים\u0004 שבכל המקומות הללו מעשרים מעשר עני בשנה זו, ויש עניים שאין להם די מזון ופרנסה \u0003בשביעית\u0004 שבה אין זורעים וקוצרים.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003לאחר שנתיישבה דעתו\u0004 של ר' אלעזר מכעסו \u0003אמר: יהי רצון שיחזרו עיני יוסי למקומן, וחזרו.\u0004 וכיון שאירע מעשה זה שכעס ר' אלעזר כשאמרו לו דבר שנראה לתלמידים כחידוש, לא רצו תלמידי ר' יהושע לומר לו עד שאמר להם במפורש שהוא רוצה בכך.","\u0003תנו רבנן\u0004 שואלים: \u0003איזהו שוטה\u0004 (משוגע)? כלומר, מה הם סימניו של שוטה? ומשיבים: \u0003היוצא יחידי בלילה, והלן בבית הקברות, והמקרע את כסותו. איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר, \u0003רב הונא אמר: עד שיהו\u0004 כל הסימנים הללו \u0003כולן בבת אחת, ר' יוחנן אמר: אפילו\u0004 כשעושה \u0003אחת מהן\u0004 הוא נחשב שוטה.","ובבירור הדברים שואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005מדובר]?\u0006 \u0003אי דעביד להו\u0004 \u0005[אם ש\u0006הוא \u0005עושה אותם]\u0006 \u0003דרך שטות\u0004 (שגעון), אם כן \u0003אפילו בחדא נמי\u0004 \u0005[באחת גם כן]\u0006 די, שהרי ברור שמשוגע הוא, \u0003אי דלא עביד להו\u0004 \u0005[אם שאיננו עושה אותם]\u0006 \u0003דרך שטות\u0004 ונראה שיש לו טעם בדבר — \u0003אפילו\u0004 אם עושה את \u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 נחשיבנו כמשוגע, שבמקרה כזה אין אלה סימן לשגעון.","ומשיבים: \u0003לעולם\u0004 תפרש \u0003דקא עביד להו\u0004 \u0005[שהוא\u0006 \u0005עושה אותם]\u0006 \u0003דרך שטות,\u0004 אלא שבכל אחד לעצמו אפשר היה לתת טעם שיש בו הגיון; \u0003והלן בבית הקברות\u0004 — \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003כדי שתשרה עליו רוח טומאה הוא דקא עביד\u0004 \u0005[שעושה]\u0006 ואף מעשה זה שאיננו מן הראוי, כיון שיש בכך טעם — איננו סימן לשגעון. \u0003והיוצא יחידי בלילה\u0004 — \u0003אימור\u0004 \u0005[אמור]\u0006 שמא \u0003גנדריפס אחדיה\u0004 \u0005[קדחת אחזה אותו]\u0006 והוא רוצה לצנן עצמו, \u0003והמקרע את כסותו — אימור\u0004 \u0005[אמור]\u0006 \u0003בעל מחשבות הוא\u0004 שהוא שקוע במחשבותיו ומודאג, וקורע את בגדיו בלי משים, אולם \u0003כיון דעבדינהו לכולהו\u0004 \u0005[שעשה את כולם\u0006 יחד\u0005]\u0006 \u0003הוה להו\u0004 \u0005[הרי הם]\u0006"],["\u0003כמי\u0004 (כמו) שאומרים בדיני שור המועד, ששור \u0003שנגח שור חמור וגמל,\u0004 שכיון שעשה את הדבר שלוש פעמים בשלושה דברים שונים אנו מניחים שהוא מועד לנגוח הכל, \u0003ו\u0004על ידי כך \u0003נעשה מועד לכל.\u0004 ואף אדם שעשה שלושה דברים שונים של שטות אין אנו נותנים למעשיו טעם הגיוני, אלא רואים את כולם כמעשה שגעון. \u0003אמר רב פפא: אי שמיע ליה\u0004 \u0005[אילו היה שומע]\u0006 \u0003רב הונא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אי זהו שוטה — זה המאבד כל מה שנותנים לו, הוה הדר ביה\u0004 \u0005[היה חוזר בו]\u0006 מדעתו שאין אדם שוטה עד שיעשה שלושה מעשי שטות.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 בביאור דברי רב פפא: האם \u0003כי הוה הדר ביה\u0004 \u0005[כאשר היה חוזר בו]\u0006 רב הונא, האם רק \u0003ממקרע כסותו הוא דהוה הדר ביה דדמיא להא\u0004 \u0005[הוא שהיה חוזר בו, שהוא דומה לזה]\u0006 למאבד מה שנותנים לו, שאדם שאין לו הרגשת אחריות כלל על ממונו נחשב כשוטה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מכולהו הוה הדר\u0004 \u0005[מכולם היה חוזר\u0006 בו\u0005]?\u0006 לשאלה זו לא נמצאה תשובה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003ו\u0004עוד שנינו במשנה ש\u0003טומטום ואנדרוגינוס\u0004 פטורים מן הראייה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אילו נאמר בכתוב רק \u0003\"זכור\"\u0004 הרי נלמד מזה \u0003להוציא\u0004 (למעט) \u0003את הנשים\u0004 מחיוב ראיה, ומה שנאמר \u0003\"זכורך\"\u0004 שיש בו הדגשה, הרי זה בא להוציא כל מי שאיננו זכר מובהק, והכוונה \u0003להוציא\u0004 גם \u0003טומטום ואנדרוגינוס.\u0004 וכיון שנאמרה גם לשון ריבוי \u0003\"כל זכורך\",\u0004 הרי זה \u0003לרבות את הקטנים.\u0004","ומפרשים, \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"זכור\" — להוציא את הנשים.\u0004 ושואלים: \u0003הא\u0004 \u0005[\u0006לדבר \u0005זה]\u0006 \u0003למה לי קרא\u0004 \u0005[פסוק]?\u0006 \u0003מכדי\u0004 \u0005[הרי]\u0006 הראייה ברגל \u0003מצות עשה שהזמן גרמא הוא,\u0004 שהמצוה תלויה בזמן מסויים, \u0003ו\u0004יש לנו כלל הלכתי: \u0003כל מצות עשה שהזמן גרמא נשים פטורות\u0004 מלקיימה!","ומשיבים: \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר כאן במיוחד, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003נילף\u0004 \u0005[נלמד]\u0006 בגזירה שווה \u0003\"ראייה\" \"ראייה\" מהקהל\u0004 שאף היא מצות עשה שהזמן גרמא; \u0003מה להלן\u0004 בהקהל \u0003נשים חייבות, אף כאן\u0004 בראייה ברגל \u0003נשים חייבות,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהן פטורות.","ועוד \u0003אמר מר: \"זכורך\" — להוציא טומטום ואנדרוגינוס.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003אנדרוגינוס — אצטריך\u0004 \u0005[הוצרך]\u0006 לומר לנו שאינו בכלל זכר כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואית ליה\u0004 \u0005[ויש לו]\u0006 \u0003צד זכרות\u0004 שהרי יש לו אבר של זכר, \u0003ליחייב\u0004 \u0005[שיתחייב]\u0006 משום כך כזכר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אנחנו מחשיבים אותו כזכר במקצת, ו\u0003בריה בפני עצמו הוא\u0004 שאינה לא זכר ולא נקבה.","\u0003אלא טומטום,\u0004 כיון שאין לו סימני מין חיצוניים הלא \u0003ספיקא\u0004 \u0005[ספק]\u0006 \u0003הוא — מי אצטריך קרא למעוטי ספיקא\u0004 \u0005[האם צריך הכתוב למעט\u0006 את ה\u0005ספק]?\u0006 \u0003אמר אביי:\u0004 כאן מדובר בטומטום \u0003כשביציו מבחוץ\u0004 אלא שזכרותו איננה נראית, ומאחר שברור שזכר הוא, צריך הכתוב להודיענו שבכל זאת אינו בכלל הזכרים.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"כל זכורך\" — לרבות את הקטנים.\u0004 ותוהים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 הכל חייבים בראיה \u0003חוץ מחרש שוטה וקטן! אמר אביי: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 בברייתא שנתרבה הקטן לחיוב, הרי זה \u0003בקטן שהגיע לחינוך, כאן\u0004 במשנתנו, מדובר \u0003בקטן שלא הגיע לחינוך\u0004 שהוא פטור מן הראיה. ומקשים: הלא גם \u0003קטן שהגיע לחינוך דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003הוא\u0004 חייב, שהחיוב לחנך ילד במצוות אינו מן התורה! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך הוא גם כן\u0006 באמת\u0005]\u0006 \u0003וקרא אסמכתא בעלמא\u0004 \u0005[והפסוק\u0006 שהביאו הוא \u0005אסמכתא\u0006 בלבד\u0005]\u0006 ואינו ראיה של ממש, ולא זו כוונת המקרא.","ושואלים: \u0003ואלא קרא\u0004 \u0005[הכתוב]\u0006 \"כל זכורך\" \u0003למאי אתא\u0004 \u0005[למה,\u0006 בשביל מה הוא \u0005בא]?\u0006 ומשיבים: \u0003לכדאחרים\u0004 \u0005[לכפי\u0006 \u0005ש\u0006אמרו, לדברי \u0005אחרים],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003אחרים אומרים: המקמץ,\u0004 האוסף גללי כלבים כדי למוסרם לבורסקאים לצורך עיבוד עורות, \u0003והמצרף נחשת\u0004 שעובד בזיקוק הנחושת מן הסיגים, \u0003והבורסי\u0004 העוסק בעיבוד עורות — כל אלה \u0003פטורין מן הראייה\u0004 משום שריחם רע, ואין אנשים יכולים לשאת את ריחם, \u0003משום שנאמר \"כל זכורך\",\u0004 לומר: \u0003מי שיכול לעלות עם כל זכורך\u0004 עם כל שאר ישראל, \u0003יצאו אלו שאינן ראויין לעלות עם כל זכורך\u0004 כיון שאין אנשים רוצים לשהות במחיצתם.","שנינו במשנה: \u0003נשים ועבדים שאינן משוחררים\u0004 פטורים מן הראייה. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לגבי \u0003נשים —\u0004 הרי זה \u0003כדאמרן\u0004 \u0005[כפי שאמרנו],\u0006 שהן פטורות משום שנאמר \"זכורך\" להוציא את הנשים, \u0003אלא עבדים מנלן\u0004 \u0005[מניין לנו]\u0006 שהם פטורים? \u0003אמר רב הונא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אל פני האדון ה'\"\u0004 (שמות כג, יז) ללמד: \u0003מי שאין לו אלא אדון אחד\u0004 (\"האדון ה'\"), \u0003יצא זה\u0004 (העבד) \u0003שיש לו אדון אחר.\u0004","ושואלים: \u0003הא\u0004 \u0005[\u0006דין \u0005זה]\u0006 \u0003למה לי קרא\u0004 \u0005[פסוק]\u0006 ללמד עליו? \u0003מכדי\u0004 \u0005[הלא]\u0006 \u0003כל מצוה שהאשה חייבת בה — עבד חייב בה,\u0004 ו\u0003כל מצוה שאין האשה חייבת בה — אין העבד חייב בה, דגמר\u0004 \u0005[ש\u0006הוא \u0005לומד]\u0006 בגזירה שווה \u0003\"לה\" \"לה\" מאשה,\u0004 שנאמר בשפחה חרופה \"לה\" (ויקרא יט, כ) ונאמר בגרושה \"לה\" (דברים כד, ג), להשוות את דיני העבד והאשה, ואין איפוא צורך בלימוד מיוחד לפטור את העבדים!","ומשיבים, \u0003אמר רבינא: לא נצרכה\u0004 הלכה זו שמי שיש לו אדון אחר איננו עולה לרגל \u0003אלא למי שחציו עבד וחציו בן חורין,\u0004 שיש בו צד שאינו דומה לאשה ואינו למד מן האשה, ואף על פי כן הוא פטור. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן\u0006 כך\u0005]\u0006 מלשון המשנה \u0003דקתני\u0004 \u0005[ששנה\u0006 התנא\u0005]:\u0006 \u0003נשים ועבדים שאינן משוחררין.\u0004 ונדקדק בלשון: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות ההדגשה \u0003שאינן משוחררין? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שאינן משוחררין כלל — ליתני\u0004 \u0005[שישנה]\u0006 \u0003\"עבדים\" סתמא\u0004 \u0005[סתם]\u0006 ועבדים הלא אינם משוחררים, \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הכוונה \u0003שאינן משוחררין לגמרי, ומאי נינהו\u0004 \u0005[ומי הם]\u0006 עבדים אלה — \u0003מי שחציו עבד וחציו בן חורין.\u0004 ומסכמים, אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003ו\u0004עוד שנינו במשנה ש\u0003החיגר והסומא ו\u0004ה\u0003חולה והזקן\u0004 פטורים מן הראייה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"רגלים\"\u0004 יש במשמעותם גם רגלים, הליכה ברגל, ומכאן שחובת עלייה לרגל היא \u0003פרט לבעלי קבין,\u0004 כלומר, בעלי רגל תותבת, שאף שיכולים ללכת, כיון שאין להם רגליים פטורים מלעלות! \u0003דבר אחר: \"רגלים\" — פרט לחיגר ולחולה ולסומא ולזקן ולשאינו יכול לעלות ברגליו.\u0004 ושואלים: \u0003ושאינו יכול לעלות ברגליו לאתויי מאי\u0004 \u0005[להביא\u0006 להוסיף את \u0005מה]?\u0006 שהרי שנינו כבר גם חיגר וגם חולה! \u0003אמר רבא: לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006"],["\u0003מפנקי\u0004 \u0005[\u0006אנשים \u0005מפונקים]\u0006 שאינם יכולים ללכת אלא בנעליים, ובנעליים אסור להיכנס למקדש, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי תבאו לראות פני מי בקש זאת מידכם רמס חצרי\"\u0004 (ישעיהו א, יב), וכניסה בנעליים נקראת בפי הנביא רמיסה.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003הערל והטמא פטורין מן הראייה.\u0004 ומבררים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003טמא\u0004 פטור — משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובאת שמה\" \"והבאתם שמה\"\u0004 (דברים יב, ה-ו), שסמיכות הפסוקים באה ללמד: \u0003כל שישנו בביאה\u0004 שרשאי לבוא למקדש — \u0003ישנו\u0004 גם \u0003ב\u0004חובת \u0003הבאה\u0004 של קרבנות, \u0003וכל שאינו בביאה\u0004 שאינו רשאי לבוא למקדש — \u0003אינו ב\u0004חובת \u0003הבאה.\u0004 וכיון שלטמא אסור להיכנס למקדש, אין עליו גם לשלוח קרבנות!","\u0003אלא ערל מנלן\u0004 \u0005[מניין לנו]\u0006 שפטור? ואומרים: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]\u0006 כדעת \u0003ר' עקיבא היא, דמרבי\u0004 \u0005[ש\u0006הוא \u0005מרבה,\u0006 לומד בדרך \"ריבוי\"\u0005]\u0006 \u0003לערל\u0004 ודן אותו \u0003כטמא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' עקיבא אומר:\u0004 נאמר \u0003\"איש איש\u0004 מזרע אהרן והוא צרוע או זב בקדשים לא יאכל\" (ויקרא כב, ד), הכפילות \"איש איש\" באה \u0003לרבות את הערל\u0004 שיהא דינו כמו הטמאים המוזכרים בפסוק.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003טמא פטור מן הראייה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ובאת שמה\" \"והבאתם שמה\",\u0004 ולמדים מזה: \u0003כל שישנו בביאה\u0004 — \u0003ישנו בהבאה, וכל שאינו בביאה — אינו בהבאה.\u0004","\u0003ר' יוחנן בן דהבאי אומר משום\u0004 (בשם) \u0003ר' יהודה: סומא באחת מעיניו פטור\u0004 גם הוא \u0003מן הראייה, שנאמר: \"יראה\"\u0004 ואפשר גם לקרוא \u0003\"יראה\"\u0004 ואנו יכולים ללמוד: \u0003כדרך שבא לראות כך בא ליראות, מה בא לראות בשתי עיניו,\u0004 שזו דרך ראייה שלימה, \u0003אף\u0004 בא \u0003ליראות\u0004 אינו אלא כשרואה \u0003בשתי עיניו.\u0004","כיון שהוזכר כתוב זה מספרים כי \u0003רב הונא כי מטי להאי קרא\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לכתוב זה]\u0006 \u0003\"יראה\" \"יראה\", בכי\u0004 \u0005[\u0006היה \u0005בוכה].\u0006 \u0003אמר: עבד שרבו\u0004 (אדוניו) היה \u0003מצפה לראותו,\u0004 בסוף \u0003יתרחק\u0004 האדון \u0003ממנו\u0004 ולא ירצה בו עוד, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי תבאו לראות פני מי בקש זאת מידכם רמס חצרי\"\u0004 (ישעיה א, יב).","ובדומה לזה, \u0003רב הונא כי מטי להאי קרא, בכי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לכתוב זה,\u0006 היה \u0005בוכה],\u0006 נאמר: \u0003\"וזבחת שלמים ואכלת שם\"\u0004 (דברים כז, ז), \u0003עבד שרבו מצפה\u0004 לו \u0003לאכול על שלחנו יתרחק\u0004 האדון \u0003ממנו? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"למה לי רב זבחיכם יאמר ה'\"\u0004 (ישעיה א, יא).","ועוד מסופר: \u0003ר' אלעזר כי מטי להאי קרא, בכי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לפסוק זה,\u0006 היה \u0005בוכה]:\u0006 \u0003\"ולא יכלו אחיו לענות אתו כי נבהלו מפניו\"\u0004 (בראשית מה, ג), \u0003ומה תוכחה של בשר ודם כך,\u0004 שלא יכלו האחים לענות דבר, \u0003תוכחה של הקדוש ברוך הוא — על אחת כמה וכמה.\u0004 ועוד: \u0003ר' אלעזר כי מטי להאי קרא, בכי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לפסוק זה,\u0006 היה \u0005בוכה],\u0006 נאמר: \u0003\"ויאמר שמואל אל שאול למה הרגזתני להעלות אתי\"\u0004 (שמואל א' כח, טו), \u0003ומה שמואל הצדיק היה מתיירא מן הדין\u0004 כשהועלה באוב, משום שחשב שנקרא לדין שמים, \u0003אנו על אחת כמה וכמה\u0004 צריכים להתיירא!","ומבררים: \u0003שמואל מאי\u0004 \u0005[מה]\u0006 \u0003היא,\u0004 מה ענין זה שאומרים שהתיירא — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותאמר האשה אל שאול אלהים ראיתי עלים\u0004 מן הארץ\u0003\"\u0004 (שמואל א' כח, יג) \u0003\"עלים\"\u0004 בלשון רבים \u0003תרי\u0004 \u0005[שניים]\u0006 \u0003משמע, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 היה \u0003שמואל, ואידך\u0004 \u0005[והאחר]\u0006 מי הוא — \u0003דאזל\u0004 \u0005[שהלך]\u0006 \u0003שמואל ואתייה\u0004 \u0005[והביאו]\u0006 \u0003למשה בהדיה\u0004 \u0005[אתו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003חס ושלום לדינא מתבעינא\u0004 \u0005[לדין\u0006 שמים \u0005אני נתבע],\u0006 \u0003קום בהדאי, דליכא מילתא דכתבת באורייתא דלא קיימתיה\u0004 \u0005[עמוד אתי\u0006 והעד בי, \u0005שאין דבר שכתבת בתורה שלא קיימתיו].\u0006","ועוד: \u0003ר' אמי כי מטי להאי קרא, בכי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לפסוק זה,\u0006 היה \u0005בוכה],\u0006 שנאמר: \u0003\"יתן בעפר פיהו אולי יש תקוה\"\u0004 (איכה ג, כט), \u0003אמר: כולי האי\u0004 \u0005[כל זה]\u0006 \u0003ו\u0004בכל זאת רק \u0003אולי\u0004 יש תקוה?! \u0003ר' אמי כי מטי להאי קרא, בכי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לפסוק זה,\u0006 היה \u0005בוכה],\u0006 נאמר: \u0003\"בקשו צדק בקשו ענוה אולי תסתרו ביום אף ה'\"\u0004 (צפניה ב, ג), \u0003אמר: כולי האי\u0004 \u0005[כל זה]\u0006 \u0003ו\u0004בכל זאת רק \u0003אולי?! ר' אסי כי מטי להאי קרא, בכי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לפסוק זה,\u0006 היה \u0005בוכה],\u0006 נאמר: \u0003\"שנאו רע ואהבו טוב והציגו בשער משפט אולי יחנן ה' אלהי צבאות\"\u0004 (עמוס ב, טו), אמר: \u0003כולי האי\u0004 \u0005[כל זה]\u0006 \u0003ו\u0004בכל זאת רק \u0003אולי?!\u0004","\u0003רב יוסף כי מטי להאי קרא, בכי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לפסוק זה,\u0006 היה \u0005בוכה],\u0006 נאמר: \u0003\"ויש נספה בלא משפט\"\u0004 (משלי יג, כג), \u0003אמר: מי איכא דאזיל בלא זמניה\u0004 \u0005[האם יש\u0006 מי \u0005שהולך בלא זמנו]?\u0006 ונמצא שמת ללא סיבה! לעצם הענין משיבים: \u0003אין\u0004 \u0005[כן],\u0006 כך קורה לעיתים, \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 שהיה, ש\u0003רב ביבי בר אביי הוה שכיח גביה\u0004 \u0005[היה מצוי אצלו]\u0006 \u0003מלאך המות\u0004 והיה רב ביבי רואה כיצד מתים אנשים בידי מלאך זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 מלאך המוות \u0003לשלוחיה\u0004 \u0005[לשלוחו]:\u0006 \u0003זיל אייתי\u0004 \u0005[לך הבא]\u0006 \u0003לי,\u0004 הרוג את \u0003מרים מגדלא\u0004 \u0005[הגודלת,\u0006 קולעת\u0005]\u0006 את \u0003שיער נשייא\u0004 \u0005[הנשים].\u0006 \u0003אזל אייתי ליה\u0004 \u0005[הלך\u0006 ו\u0005הביא לו]\u0006 את \u0003מרים מגדלא דרדקי\u0004 \u0005[מגדלת התינוקות].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 מלאך המוות: \u0003אנא\u0004 \u0005[אני]\u0006 את \u0003מרים מגדלא\u0004 \u0005[גודלת]\u0006 \u0003שיער נשייא\u0004 \u0005[הנשים]\u0006 \u0003אמרי לך\u0004 \u0005[אמרתי לך]\u0006 להביא! \u0003אמר ליה\u0004 \u0005[לו]\u0006 השליח: \u0003אי הכי, אהדרה\u0004 \u0005[אם כך, אחזיר אותה]\u0006 לחיים! \u0003אמר ליה\u0004 \u0005[לו]\u0006 מלאך המוות: \u0003הואיל ואייתיתה\u0004 \u0005[ו\u0006כבר \u0005הבאת אותה] —\u0006 \u0003ליהוי למניינא\u0004 \u0005[שתהיה\u0006 כאן \u0005ל\u0006השלים את \u0005מנין]\u0006 המתים! הרי שיש דוגמה של אשה שמתה לא במשפט אלא בטעות. ושאל אותו: \u0003אלא\u0004 כיון שלא הגיע זמנה למות \u0003היכי יכלת\u0004 \u0005[איך יכולת]\u0006 \u0003לה\u0004 להמית אותה? וסיפר לו השליח שהיתה הזדמנות, \u0003הות נקיטא מתארא\u0004 \u0005[היתה מחזיקה מרדה]\u0006 \u0003בידה והות קא שגרא\u0004 \u0005[והיתה משלחת\u0006 אותו\u0005]\u0006"],["\u0003ומחריא תנורא\u0004 \u0005[ומכבדת\u0006 בו את \u0005התנור],\u0006 \u0003שקלתא ואנחתא אגבה דכרעה, קדחא ואיתרע מזלה, ואייתיתה\u0004 \u0005[לקחה\u0006 את האוד \u0005והניחה אותו על גב רגלה ונכוותה ו\u0006אז \u0005הורע מזלה,\u0006 ויכולתי לקחת אותה \u0005והבאתיה].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ביבי בר אביי\u0004 למלאך המוות: וכי \u0003אית לכו רשותא למיעבד הכי\u0004 \u0005[יש לכם רשות לעשות כך]\u0006 לקחת אדם טרם זמנו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 מלאך המוות: \u0003ו\u0004כי \u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ויש נספה בלא משפט\"\u0004 (משלי יג, כג)? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ביבי: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"דור הלך ודור בא\"\u0004 (קהלת א, ד), משמע שלכל דור יש שנים קצובות שבהן הוא הולך מן העולם!","\u0003אמר\u0004 לו מלאך המוות: \u0003דרעינא להו אנא, עד דמלו להו לדרא, והדר משלימנא ליה\u0004 \u0005[אני רועה,\u0006 מחזיק \u0005אותם, עד שימלאו להם\u0006 שנות \u0005הדור, ואחר כך מוסר אני אותם]\u0006 \u0003ל\u0004מלאך \u0003דומה\u0004 הממונה על נשמות המתים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ביבי: \u0003סוף סוף שניה מאי עבדת\u0004 \u0005[\u0006ב\u0005שנות\u0006 החיים \u0005שלה מה אתה עושה]?\u0006 \u0003אמר\u0004 לו מלאך המוות: \u0003אי איכא צורבא מרבנן דמעביר במיליה\u0004 \u0005[אם יש תלמיד חכם שמוותר\u0006 על \u0005חפציו] —\u0006 \u0003מוסיפנא להו ליה, והויא חלופיה\u0004 \u0005[מוסיף אני אותם,\u0006 את השנים הללו, \u0005לו, והרי היא חילופו].\u0006","ושוב לענין הקודם, \u0003ר' יוחנן כי מטי להאי קרא, בכי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לפסוק זה,\u0006 היה \u0005בוכה];\u0006 שאמר ה' לשטן: \u0003\"ותסיתני בו לבלעו חנם\"\u0004 (איוב ב, ג), אמר: \u0003עבד שרבו מסיתין לו\u0004 אחרים על העבד, ורבו מתחשב בהם \u0003וניסת,\u0004 וכי \u0003תקנה יש לו\u0004 לאותו עבד?! ועוד: \u0003ר' יוחנן כי מטי להאי קרא, בכי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לפסוק זה,\u0006 היה \u0005בוכה],\u0006 נאמר: \u0003\"הן בקדשו לא יאמין\"\u0004 (איוב טו, טו), אמר: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בקדושיו לא יאמין — במאן\u0004 \u0005[במי]\u0006 כן \u0003יאמין?\u0004","מסופר: \u0003יומא חד הוה קא אזיל באורחא\u0004 \u0005[יום אחד היה\u0006 ר' יוחנן \u0005הולך בדרך],\u0006 \u0003חזייה לההוא גברא דהוה מנקיט תאני\u0004 \u0005[ראה איש אחד שהיה מלקט תאנים],\u0006 \u0003שביק הנך דמטו ושקיל הנך דלא מטו\u0004 \u0005[הניח את אלה שהגיעו\u0006 לבישול \u0005ולקח את אלה שלא הגיעו\u0006 עדיין\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003לאו הני מעלן טפי\u0004 \u0005[\u0006האם \u0005לא אלה\u0006 הבשלות \u0005מעולות יותר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני לאורחא בעינן להו\u0004 \u0005[\u0006את \u0005אלה\u0006 התאנים \u0005לדרך אני צריך אותן],\u0006 \u0003הני נטרן והני לא נטרן\u0004 \u0005[אלה\u0006 שעדיין אינן בשלות \u0005נשמרות, ואלה\u0006 הבשלות \u0005אינן נשמרות].\u0006 \u0003אמר\u0004 ר' יוחנן, \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"הן בקדשו לא יאמין\",\u0004 שיש אנשים כשרים שהקדוש ברוך הוא לוקח אותם מן העולם לפני זמנם משום שהוא יודע בהם שעלולים לבוא לידי קלקול ותקלה,","ושואלים: \u0003איני\u0004 \u0005[האם כן הוא]?\u0006 \u0003והא ההוא תלמידא דהוה בשיבבותיה\u0004 \u0005[והרי תלמיד אחד שהיה בשכנותו]\u0006 של \u0003ר' אלכסנדרי ושכיב אדזוטר\u0004 \u0005[ומת בעודו צעיר],\u0006 \u0003ואמר\u0004 עליו ר' אלכסנדרי: \u0003אי בעי האי מרבנן, הוה חיי\u0004 \u0005[אם היה רוצה תלמיד חכם זה,\u0006 כלומר, הוא עצמו, \u0005היה חי],\u0006 שמעשיו הם שגרמו לו שימות בצעירותו. \u0003ואם איתא\u0004 \u0005[ואם יש]\u0006 מקום לדברי ר' יוחנן, \u0003דלמא\u0004 \u0005[שמא]\u0006 מאותם שנאמר עליהם \u0003\"הן בקדשו לא יאמין\" הוה\u0004 \u0005[היה]\u0006 אותו תלמיד, ולא חטאיו גרמו לו? ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 תלמיד\u0005]\u0006 \u0003מבעט\u0004 (מזלזל) \u0003ברבותיו הוה\u0004 \u0005[היה]\u0006 וידע ר' אלכסנדרי במעשיו שהם שגרמו לו עונש.","ומסופר עוד: \u0003ר' יוחנן כי מטי להאי קרא, בכי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לפסוק זה,\u0006 היה \u0005בוכה],\u0006 נאמר: \u0003\"וקרבתי אליכם למשפט והייתי עד ממהר במכשפים ובמנאפים ובנשבעים לשקר ובעשקי שכר שכיר\u0004 אלמנה ויתום ומטי גר ולא יראוני אמר ה'...\u0003\"\u0004 (מלאכי ג, ה), אמר: \u0003עבד שרבו מקרבו לדונו, וממהר להעידו — וכי תקנה יש לו?!\u0004","על אותו פסוק עצמו \u0003אמר ר' יוחנן בן זכאי: אוי לנו ששקל\u0004 (החשיב) \u0003עלינו הכתוב קלות כחמורות,\u0004 שהרי נמנו שם יחד גם עוונות חמורים שעונשם מיתה, כגון מכשפים ומנאפים, וגם עבירות הנראות קלות כגון עושקי שכר שכיר.","\u0003אמר ריש לקיש: כל המטה דינו של גר — כאילו מטה דינו של מעלה,\u0004 של הקדוש ברוך הוא, \u0003שנאמר\u0004 שם: \u0003\"ומטי גר\"\u0004 ואנחנו דורשים: \u0003\"ומטי\" כתיב\u0004 \u0005[נאמר],\u0006 שמטה גר כאילו מטה ועושק אותי. \u0003אמר ר' חנינא בר פפא: כל העושה דבר\u0004 של עבירה \u0003ומתחרט בו — מוחלין לו מיד, שנאמר\u0004 שם: \u0003\"ולא יראוני\",\u0004 משמע: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יראוני,\u0004 שיהיו יראים אותי ומתביישים מפני — \u0003מוחלין להם מיד.\u0004","ועוד: \u0003ר' יוחנן כי מטי להאי קרא, בכי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לפסוק זה,\u0006 היה \u0005בוכה],\u0006 נאמר: \u0003\"כי את כל מעשה האלהים יבא במשפט על כל נעלם\"\u0004 (קהלת יב, יד), אמר: \u0003עבד שרבו שוקל\u0004 (מחשיב) \u0003לו שגגות כזדונות,\u0004 שגם על דבר שנעלם מדעתו של האדם מעניש אותו ה', וכי \u0003תקנה יש לו?!\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"על כל נעלם\",\u0004 איזהו החטא הנעלם מעושהו? \u0003אמר רב: זה ההורג כינה\u0004 שהיתה עליו \u0003בפני חברו, ו\u0004חבירו \u0003נמאס בה,\u0004 שה' שופטו גם על צער זה שגרם לחבירו, בלא כוונה. \u0003ושמואל אמר\u0004 בדומה לכך: \u0003זה הרק בפני חבירו\u0004 וחבירו רואה \u0003ונמאס.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 המשך הכתוב \u0003\"אם טוב ואם רע\"?\u0004 שנראה שה' דן אדם גם על מעשה טוב שעשה! \u0003אמרי דבי\u0004 \u0005[אומרים\u0006 תלמידי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: זה הנותן צדקה לעני בפרהסיא,\u0004 שאמנם עשה מעשה טוב אך בייש בכך את העני. \u0003כי הא,\u0004 \u0005[כמו\u0006 מעשה \u0005זה],\u0006 ש\u0003ר' ינאי חזייה לההוא גברא דקא יהיב זוזא\u0004 \u0005[ראה אדם אחד שהוא נותן דינר]\u0006 \u0003לעני בפרהסיא, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מוטב\u0004 היה ש\u0003לא יהבת ליה\u0004 \u0005[היית נותן לו],\u0006 \u0003מהשתא דיהבת ליה וכספתיה\u0004 \u0005[מ\u0006אשר \u0005עכשיו שנתת לו וביישתו].\u0006","\u0003דבי\u0004 \u0005[\u0006תלמידי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא אמרי\u0004 \u0005[אומרים],\u0006 שמעשה טוב של אדם שעליו דנים אותו הוא \u0003זה הנותן צדקה לאשה בסתר\u0004 בינו לבינה, \u0003דקא מייתי לה\u0004 \u0005[שהוא מביא אותה]\u0006 בכך \u0003לידי חשדא\u0004 \u0005[חשד],\u0006 שמא אתנן נותן לה. \u0003רבא אמר: זה המשגר\u0004 \u0005[השולח]\u0006 \u0003לאשתו בשר שאינו מחותך\u0004 (שלא ניקרו ולא הוציאו ממנו עדיין את גיד הנשה) \u0003בערבי שבתות\u0004 שאז הכל ממהרים, והאשה לא תשים לב, ותבשל בשר האסור באכילה.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא\u0004 עצמו היה \u0003משגר\u0004 \u0005[שולח]\u0006 בשר כזה לאשתו בערב שבת! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 אשתו של רבא שהיתה \u0003בת רב חסדא, דקים ליה בגווה\u0004 \u0005[שמוחזק לו בה]\u0006 שהיא \u0003בקיאה\u0004 בהלכה, ויכול היה לסמוך עליה.","ועוד: \u0003ר' יוחנן כי מטי להאי קרא, בכי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע לפסוק זה,\u0006 היה \u0005בוכה]\u0006 נאמר: \u0003\"והיה כי תמצאן אתו רעות רבות וצרות\"\u0004 (דברים לא, כא), אמר: \u0003עבד שרבו ממציא לו רעות וצרות,\u0004 וכי \u0003תקנה יש לו?!\u0004","על לשון הכתוב שואלים \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"רעות\u0004 רבות \u0003וצרות\"? אמר רב: רעות שנעשות צרות\u0004 (אויבות) \u0003זו לזו,\u0004 שכל תקנה שעושים לאחת מהן — מזיקה לשניה, \u0003כגון\u0004 מי שנעקץ על ידי \u0003זיבורא ועקרבא\u0004 \u0005[צרעה ועקרב]\u0006 שהרפואה שעושים לעקיצה של זה מזיקה לעקיצה של זה.","\u0003ושמואל אמר: זה הממציא לו מעות לעני בשעת דוחקו,\u0004 שכן לאחר שהוא נחלץ בסיוע כסף זה מדוחקו — הנושה בא מיד אחר כך וגובה ממנו את הכסף. \u0003אמר רבא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים בני אדם]\u0006 בפתגם עממי: \u0003זוזא לעללא לא שכיחא\u0004 \u0005[דינר עבור תבואה איננו מצוי],\u0006 ואולם \u0003לתליתא שכיח\u0004 \u0005[עבור תליה,\u0006 כשתולים אדם ומכריחים אותו לשלם \u0005מצוי\u0006 הדינר\u0005]\u0006 (ר\"ח) ונמצא שאינו יכול ליהנות מהכסף שקיבל.","באותו ענין נאמר: \u0003\"וחרה אפי בו ביום ההוא ועזבתים והסתרתי פני מהם\u0004 והיה לאכול\u0003\"\u0004 (דברים לא, יז). \u0003אמר רב ברדלא בר טביומי אמר רב: כל\u0004 אדם \u0003שאינו ב\u0004כלל \u0003הסתר פנים\u0004 (שהוא מתפלל ואינו נענה) — \u0003אינו מהם,\u0004 מישראל, שהרי נאמר על ישראל שיסתיר ה' פניו מהם בגלל חטאם, וכן, \u0003כל שאינו ב\u0004כלל \u0003\"והיה לאכל\",\u0004 שאין הגוים גוזלים את ממונו —"],["\u0003אינו מהם,\u0004 מישראל. \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא: מר\u0004 \u0005[אדוני]\u0006 \u0003לא בהסתר פנים איתיה\u0004 \u0005[ישנו],\u0006 שכן תפילתך נשמעת, \u0003ולא ב\"והיה לאכל\" איתיה\u0004 \u0005[ישנו],\u0006 שהרי אין המלכות נוטלת ממך דבר! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מי ידעיתו\u0004 \u0005[האם יודעים אתם]\u0006 \u0003כמה\u0004 מתנות \u0003משדרנא\u0004 \u0005[אני שולח]\u0006 \u0003בצנעא בי\u0004 \u0005[לבית]\u0006 \u0003שבור מלכא\u0004 \u0005[המלך]?\u0006 כלומר, רק למראית העין אין המלכות גוזלת ממני, ובאמת אני נותן הרבה שוחד שלא ברצוני. \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003יהבו ביה רבנן עינייהו\u0004 \u0005[נתנו חכמים בו עיניהם\u0006 לרעה\u0005].\u0006 \u0003אדהכי שדור דבי\u0004 \u0005[\u0006ו\u0005בינתים שלחו מבית]\u0006 \u0003שבור מלכא\u0004 \u0005[המלך]\u0006 \u0003וגרבוהו\u0004 \u0005[ואסרו אותו],\u0006 כדי לגבות ממנו כספים. \u0003אמר\u0004 רבא: \u0003היינו דתניא\u0004 \u0005[זהו ששנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר רבן שמעון בן גמליאל: כל מקום ש\u0004אמרו ש\u0003\"נתנו חכמים עיניהם\"\u0004 באדם, סופו שהגיע לו על ידי כך \u0003או מיתה או עוני.\u0004","על אותו כתוב \u0003\"ואנכי הסתר אסתיר פני ביום ההוא\"\u0004 (דברים לא, יח) \u0003אמר רבא, אמר הקדוש ברוך הוא: אף על פי שהסתרתי פני מהם\u0004 ואין גילוי שכינה לישראל, בכל זאת \u0003בחלום אדבר בו,\u0004 שיש התגלות כלשהי, לפחות בחלום. \u0003רב יוסף אמר:\u0004 עדיין \u0003ידו נטויה\u0004 להגן \u0003עלינו, שנאמר: \"ובצל ידי כסיתיך\"\u0004 (ישעיהו נא, טז).","ועל ענין זה עצמו מספרים: \u0003ר' יהושע בן חנניה הוה קאי בי\u0004 \u0005[היה עומד בבית]\u0006 ה\u0003קיסר\u0004 ובפני הקיסר, \u0003אחוי ליה ההוא מינא\u0004 \u0005[הראה לו מין אחד]\u0006 שהיה שם, ברמז, על ידי תנועה: \u0003עמא דאהדרינהו מריה לאפיה מיניה\u0004 \u0005[העם שהחזיר אדוניו,\u0006 ה', \u0005את פניו ממנו].\u0006 \u0003אחוי ליה\u0004 \u0005[הראה לו]\u0006 גם הוא, ר' יהושע, למין ברמז, ופשט את ידו ואמר לו: \u0003ידו נטויה עלינו. אמר ליה\u0004 \u0005[לו]\u0006 ה\u0003קיסר לר' יהושע: מאי אחוי לך\u0004 \u0005[מה הראה לך],\u0006 מה רצה לרמז לך? אמר לו: רצה לרמז לי \u0003עמא דאהדרינהו מריה לאפיה מיניה\u0004 \u0005[העם שהחזיר אדוניו את פניו ממנו],\u0006 \u0003ואנא מחוינא ליה\u0004 \u0005[ואני הראיתי לו]\u0006 ש\u0003ידו נטויה עלינו.\u0004","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003לההוא מינא\u0004 \u0005[לאותו מין]:\u0006 \u0003מאי אחויית ליה\u0004 \u0005[מה הראית אתה לו]?\u0006 אמר להם: הראיתי לו \u0003עמא דאהדרינהו מריה מיניה\u0004 \u0005[העם שהחזיר אדוניו\u0006 את פניו \u0005ממנו],\u0006 ושאלוהו: \u0003ומאי אחוי לך\u0004 \u0005[ומה הראה לך]\u0006 הוא? אמר להם: \u0003לא ידענא\u0004 \u0005[אינני יודע],\u0006 לא הבנתי. \u0003אמרו: גברא דלא ידע מאי מחוו ליה, במחוג יחוי קמי מלכא\u0004 \u0005[אדם שאיננו יודע מה מראים לו, ברמז יראה\u0006 תנועות \u0005לפני המלך]?!\u0006 \u0003אפקוהו וקטלוהו\u0004 \u0005[הוציאוהו והרגוהו]\u0006.","אגב סיפור זה, שממנו רואים כיצד ניצח ר' יהושע בן חנניה בחכמתו את אויבי ישראל, מספרים: \u0003כי קא ניחא נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 לפני שנפטר\u0005]\u0006 \u0003ר' יהושע בן חנניה אמרו ליה רבנן\u0004 \u0005[לו חכמים]:\u0006 \u0003מאי תיהוי עלן ממנאי\u0004 \u0005[מה יהיה עלינו מן המינים],\u0006 כאשר אין בינינו חכם כמוך שיענה להם? \u0003אמר להם,\u0004 אמר הכתוב: \u0003\"\u0004האין עוד חכמה בתימן \u0003אבדה עצה מבנים נסרחה חכמתם\"\u0004 (ירמיהו מט, ז), וכך יש לדרשו: \u0003כיון שאבדה עצה מבנים\u0004 מבני ישראל — גם \u0003נסרחה חכמתן של אומות העולם\u0004 ולא יימצאו ביניהם עוד חכמים מופלגים.","\u0003ואי בעית אימא מהכא\u0004 \u0005[ואם תרצה אמור מכאן]\u0006 מקור אחר לאותו רעיון, שנאמר: \u0003\"ויאמר נסעה ונלכה ואלכה לנגדך\"\u0004 (בראשית לג, יב), שכשם שעולים ויורדים ישראל, כך כנגדם אומות העולם, ולעולם לא יהיה להם יתרון.","מסופר: \u0003ר' אילא הוה סליק בדרגא דבי\u0004 \u0005[היה עולה במדרגות בבית]\u0006 \u0003רבה בר שילא,\u0004 שהיה מלמד תינוקות. \u0003שמעיה לינוקא דהוה קא קרי\u0004 \u0005[שמע תינוק שהיה קורא]\u0006 פסוק זה בקול: \u0003\"כי הנה יוצר הרים וברא רוח ומגיד לאדם מה שחו\"\u0004 (עמוס ד, יג). \u0003אמר\u0004 ר' אילא: \u0003עבד שרבו מגיד לו מה שיחו\u0004 וכי \u0003תקנה יש לו?!\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מה שחו\"? אמר רב: אפילו שיחה יתירה\u0004 של קלות ראש, ואפילו זו \u0003שבין איש לאשתו מגידים לו לאדם בשעת מיתה.\u0004","ושואלים: \u0003איני\u0004 \u0005[האם כן הוא]\u0006 שאסור לאדם לשוחח כך עם אשתו? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב כהנא הוה גני תותי פורייה\u0004 \u0005[היה ישן תחת מטתו]\u0006 של \u0003רב, ושמעיה\u0004 \u0005[ושמע אותו]\u0006 שהוא \u0003סח וצחק\u0004 עם אשתו \u0003ועשה צרכיו\u0004 בתשמיש המיטה. \u0003אמר\u0004 רב כהנא בעודו תחת המיטה: \u0003דמי פומיה\u0004 \u0005[דומה פיו]\u0006 של \u0003רב כמאן דלא טעים ליה תבשילא\u0004 \u0005[כמו\u0006 אדם \u0005שלא טעם לו תבשיל],\u0006 כלומר, שהוא מתאווה ביותר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003כהנא, פוק\u0004 \u0005[צא]\u0006 מכאן! \u0003לאו אורח ארעא\u0004 \u0005[אין\u0006 זה \u0005דרך ארץ\u0006 להיות כאן\u0005].\u0006 ועל כל פנים מכאן יוצא שרב בעצמו שוחח עם אשתו לפני תשמיש!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 שמותר לשוחח מדובר באופן ש\u0003צריך לרצויה\u0004 \u0005[לרצותה,\u0006 את אשתו\u0005]\u0006 ולכן משוחח עמה, \u0003הא\u0004 \u0005[זה]\u0006 שמשמע מדברי רב שהדבר אסור, הרי זה באופן \u0003דלא\u0004 \u0005[שאינו]\u0006 \u0003צריך לרצויה\u0004 \u0005[לרצותה]\u0006 אסור להרבות בשיחה יתירה.","נאמר: \u0003\"ואם לא תשמעוה במסתרים תבכה נפשי מפני גוה\"\u0004 (ירמיהו יג, יז), \u0003אמר רב שמואל בר איניא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: מקום יש לו להקדוש ברוך הוא ומסתרים שמו,\u0004 ושם הוא בוכה. \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מפני גוה\"? אמר רב שמואל בר יצחק:\u0004 \"גוה\" משמע גאוה, כלומר, \u0003מפני גאוותן של ישראל שניטלה מהם ונתנה לגויים. ר' שמואל בר נחמני אמר: מפני גאוותה של מלכות שמים\u0004 שניטלה.","ושואלים: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 \u0003בכיה קמיה\u0004 \u0005[לפני]\u0006 \u0003הקדוש ברוך הוא? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב פפא: אין עציבות לפני הקדוש ברוך הוא, שנאמר: \"הוד והדר לפניו עז וחדוה במקמו\"\u0004 (דברי הימים א' טז, כז)! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא בבתי גואי\u0004 \u0005[זה בבתים פנימיים]\u0006 יש מסתרים של בכי, \u0003הא בבתי בראי\u0004 \u0005[\u0006ו\u0005זה בבתים חיצוניים,\u0006 ובהם לעולם אין עצבות\u0005].\u0006","ושואלים: \u0003ובבתי בראי\u0004 \u0005[ובבתים חיצוניים]\u0006 \u0003לא? והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויקרא אדני ה' צבאות ביום ההוא לבכי ולמספד ולקרחה ולחגר שק\"\u0004 (ישעיהו כב, יב)! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003חרבן בית המקדש\u0004 שעליו מדובר פה, ש\u0003אפילו מלאכי שלום בכו, שנאמר: \"הן אראלם צעקו חצה מלאכי שלום מר יבכיון\"\u0004 (ישעיהו לג, ז).","נאמר: \u0003\"ודמע תדמע ותרד עיני דמעה כי נשבה עדר ה'\"\u0004 (ירמיהו יג, יז), \u0003אמר ר' אלעזר: שלש\u0004 לשונות של \u0003דמעות\u0004 בפסוק \u0003הללו למה? אחת על מקדש ראשון, ואחת על מקדש שני, ואחת על ישראל שגלו ממקומן. ואיכא דאמרי\u0004 \u0005[ויש אומרים]:\u0006 \u0003אחת\u0004 אחרונה \u0003על ביטול תורה.\u0004","ואומרים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שהדמעה האחרונה היא \u0003על ישראל שגלו — היינו דכתיב\u0004 \u0005[זהו שנאמר\u0006 שם\u0005]\u0006 \u0003\"כי נשבה עדר ה'\", אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי דמעה זו \u0003על ביטול תורה\u0004 היא — \u0003מאי\u0004 \u0005[מה\u0006 עניינו\u0005]\u0006 של \u0003\"כי נשבה עדר ה'\"?\u0004 ומשיבים: \u0003כיון שגלו ישראל ממקומן — אין לך ביטול תורה גדול מזה\u0004 והבכיה היא איפוא על ביטול התורה שבגלות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה\u0004 סוגים של אנשים \u0003הקדוש ברוך הוא בוכה עליהן בכל יום: על\u0004 מי \u0003שאפשר\u0004 לו \u0003לעסוק בתורה ואינו עוסק, ועל\u0004 מי \u0003שאי אפשר\u0004 לו \u0003לעסוק בתורה\u0004 והוא מתאמץ ומשתדל \u0003ועוסק, ועל פרנס המתגאה על הצבור.\u0004","מספרים: \u0003רבי הוה נקיט\u0004 \u0005[היה מחזיק]\u0006 \u0003ספר קינות,\u0004 איכה, בידו \u0003וקא קרי בגויה\u0004 \u0005[והיה קורא בו],\u0006 \u0003כי מטא להאי פסוקא\u0004 \u0005[כאשר הגיע לפסוק זה]\u0006 \u0003\"השליך משמים ארץ\u0004 תפארת ישראל\u0003\"\u0004 (איכה ב, א) \u0003נפל מן ידיה\u0004 \u0005[נפל\u0006 הספר \u0005מידו\u0006 מרוב צער\u0005],\u0006 \u0003אמר: מאיגרא רם לבירא עמיקתא\u0004 \u0005[מגג גבוה לבור עמוק]\u0006 נפילה קיצונית היא, משמים לארץ.","מסופר: \u0003רבי ור' חייא הוו שקלי ואזלי באורחא\u0004 \u0005[היו מהלכים בדרך],\u0006 \u0003כי מטו לההוא מתא, אמרי\u0004 \u0005[כאשר הגיעו לעיר אחת, אמרו]:\u0006 האם \u0003איכא צורבא מרבנן הכא\u0004 \u0005[יש תלמיד חכם כאן],\u0006 \u0003נזיל וניקביל אפיה\u0004 \u0005[\u0006ש\u0005נלך ונקביל את פניו]?\u0006 \u0003אמרי\u0004 \u0005[אמרו]\u0006 בני העיר: \u0003איכא צורבא מרבנן הכא\u0004 \u0005[יש כאן תלמיד חכם]\u0006 \u0003ומאור עינים\u0004 (עיוור) \u0003הוא אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא לרבי: תיב את\u0004 \u0005[שב אתה],\u0006 ו\u0003לא תזלזל בנשיאותך\u0004 ללכת לבקר אדם קטן ממך, \u0003איזיל אנא ואקביל אפיה\u0004 \u0005[אלך אני ואקביל פניו],\u0006","\u0003תקפיה ואזל בהדיה\u0004 \u0005[החזיקו\u0006 רבי בכוח \u0005והלך אתו\u0006 בכל זאת\u0005]\u0006 וביקרו את החכם העיוור ההוא. \u0003כי הוו מיפטרי מיניה\u0004 \u0005[כאשר נפרדו ממנו],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אתם הקבלתם פנים הנראים ואינן רואין\u0004 שהרי אני עיוור — \u0003תזכו\u0004 בשל כך \u0003להקביל פנים הרואים ואינן נראין\u0004 של הקדוש ברוך הוא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי לר' חייא: \u0003איכו השתא מנעתן מהאי בירכתא\u0004 \u0005[אילו עכשיו\u0006 הייתי שומע לך ולא הייתי הולך להקביל פניו, \u0005היית מונע אותי מברכה\u0006 יפה \u0005זו].\u0006","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 רבי ור' חייא לעוור: \u0003ממאן שמיעא לך\u0004 \u0005[ממי שמעת\u0006 תוכנה של ברכה זו\u0005]?\u0006 אמר להם: \u0003מפרקיה\u0004 \u0005[מ\u0006תוך \u0005דרשתו]\u0006 של \u0003ר' יעקב שמיע לי\u0004 \u0005[שמעתי\u0006 זאת\u0005],\u0006 כי \u0003ר' יעקב איש כפר חיטייא הוה\u0004 \u0005[היה]\u0006 \u0003מקביל\u0004 את \u0003אפיה דרביה כל יומא\u0004 \u0005[פני רבו בכל יום],\u0006 \u0003כי קש\u0004 \u0005[כאשר הזדקן]\u0006 ר' יעקב \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבו: \u0003לא נצטער מר, דלא יכיל מר\u0004 \u0005[אל יצטער אדוני שאין אדוני יכול\u0006 להתאמץ\u0005],\u0006 ומוטב שלא יבקר אותי.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי זוטר מאי דכתיב בהו ברבנן\u0004 \u0005[האם קטן מה שנאמר בהם בחכמים]\u0006 \u0003\"ויחי עוד לנצח לא יראה השחת כי יראה חכמים ימותו\"\u0004 (תהלים מט, י-יא), ונלמד קל וחומר: \u0003ומה הרואה חכמים במיתתן יחיה\u0004 — הרואה אותם \u0003בחייהן על אחת כמה וכמה,\u0004 ומכאן למד העוור כמה גדולה הקבלת פני תלמידי חכמים.","מסופר: \u0003רב אידי אבוה\u0004 \u0005[אביו]\u0006 של \u0003ר' יעקב בר אידי הוה\u0004 \u0005[היה]\u0006 \u0003רגיל דהוה אזיל תלתא ירחי באורחא\u0004 \u0005[שהיה הולך שלושה חדשים בדרך]\u0006 לבית המדרש \u0003ו\u0004כדי שיספיק לחזור לביתו לחג הסוכות, לא היה אלא \u0003חד יומא בבי\u0004 \u0005[יום אחד בבית]\u0006 \u0003רב, והוו קרו ליה רבנן \"בר בי רב דחד יומא\"\u0004 \u0005[והיו קוראים לו חכמים\u0006 בלגלוג \"\u0005בן בית הרב של יום אחד\"].\u0006 \u0003חלש דעתיה\u0004 \u0005[חלשה דעתו,\u0006 נעלב\u0005],\u0006 \u0003קרי אנפשיה\u0004 \u0005[\u0006ו\u0005קרא על עצמו\u0006 פסוק זה\u0005]:\u0006 \u0003\"שחק לרעהו אהיה וגו'\"\u0004 (איוב יב, ד). \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: במטותא מינך, לא תעניש להו רבנן\u0004 \u0005[בבקשה ממך, אל תעניש את החכמים],\u0006 כלומר, אל תקפיד עליהם, כדי שלא יענשו משמים בשל עלבונך.","\u0003נפק\u0004 \u0005[יצא]\u0006 \u0003ר' יוחנן לבי מדרשא\u0004 \u0005[לבית במדרש]\u0006 \u0003ודרש,\u0004 נאמר: \u0003\"ואותי יום יום ידרשון ודעת דרכי יחפצון\"\u0004 (ישעיהו נח, ב), ויש להבין: \u0003וכי ביום דורשין אותו ובלילה אין דורשין אותו?!\u0004 ואם כן מהו הלשון \"יום יום\"? \u0003אלא לומר לך: כל העוסק בתורה אפילו יום אחד בשנה — מעלה עליו\u0004 (מחשיב לו) \u0003הכתוב כאילו עסק\u0004 בתורה \u0003כל השנה כולה.\u0004","\u0003וכן\u0004 הוא \u0003במדת פורענות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"במספר הימים אשר תרתם את הארץ...\u0004 תשאו את עונותיכם ארבעים שנה\u0003\"\u0004 (במדבר יד, לד), \u0003וכי ארבעים שנה חטאו? והלא ארבעים יום\u0004 בלבד \u0003חטאו! אלא לומר לך: כל העובר עבירה אפילו יום אחד בשנה — מעלה עליו הכתוב כאילו עבר כל השנה כולה.\u0004","עתה חוזרים לענין המסכת. שנינו במשנה: \u0003אי זהו קטן\u0004 שפטור ממצות ראיה — \u0003כל שאינו יכול לרכוב על כתפו של אביו\u0004 ולעלות מירושלים להר הבית. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא:\u0004"],["\u0003עד הכא\u0004 \u0005[עד כאן],\u0006 עד ירושלים \u0003מאן אתייה\u0004 \u0005[מי הביא אותו]?\u0006 ואם אפשר היה להביא את התינוק לירושלים, מדוע אי אפשר להביא אותו להר הבית?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: עד הכא\u0004 \u0005[כאן]\u0006 כיון \u0003דמיחייבא אימיה\u0004 \u0005[שמחוייבת\u0006 גם \u0005אמו]\u0006 \u0003בשמחה\u0004 ולכן בבואה לירושלים \u0003אייתיתיה אימיה\u0004 \u0005[הביאתו אמו],\u0006 \u0003מכאן ואילך, אם יכול לעלות ולאחוז בידו של אביו מירושלים להר הבית — חייב, ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003פטור.\u0004","ומעירים שבברייתא נאמר: \u0003השיב רבי תחת\u0004 (במקום) \u0003בית הלל: לדברי בית שמאי\u0004 במשנתנו קשה ממה שנאמר בחנה, אם שמואל: \u0003\"וחנה לא עלתה כי אמרה לאישה עד יגמל הנער והביאתיו\"\u0004 (שמואל א', א, כב), \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שמואל\u0004 ש\u0003יכול לרכוב על כתיפו של אביו הוה\u0004 \u0005[היה],\u0006 שהרי עוד טרם גמילתו (שזמנה הוא בהיותו בן עשרים וארבעה חדשים) הוא כבר גדול דיו כדי לרכב על כתפי אביו. ומכאן ראיה שרק תינוק שיכול ללכת ברגליו מרחק מסויים הוא המחוייב בראיה.","\u0003אמר ליה אבוה\u0004 \u0005[לו אביו\u0006 של רבי\u0005]:\u0006 \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מביא ראיה מכאן, \u0003תיקשי לך\u0004 \u0005[יקשה לך]\u0006 מאותו מקרא, הלא \u0003חנה גופה\u0004 \u0005[עצמה]\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא מיחייבא\u0004 \u0005[\u0006היתה \u0005מחוייבת]\u0006 \u0003בשמחה,\u0004 ומדוע לא עלתה בגלל המצוה המוטלת עליה עצמה? \u0003אלא\u0004 חייבים לומר כי \u0003חנה, מפנקותא יתירתא חזייא ביה\u0004 \u0005[פינוק,\u0006 חולשה \u0005יתירה ראתה בו]\u0006 \u0003בשמואל, וחשא ביה\u0004 \u0005[וחששה לו]\u0006 ל\u0003שמואל לחולשא דאורחא\u0004 \u0005[לחולשת הדרך]\u0006 וכיון שלא יכלה להביאו, אף היא עצמה לא באה עד שגדל, ואין מכאן ראיה כלל.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' שמעון: קטן\u0004 שהוא \u0003חיגר, לדברי בית שמאי,\u0004 שיכול לעלות על כתפי אביו אף שאינו יכול ללכת לבדו, \u0003ו\u0004כן תינוק \u0003סומא\u0004 שיכול לאחוז ביד אביו ולעלות, \u0003לדברי שניהם, מהו\u0004 דינם, האם הוא חייב בראיה?","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005מדובר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר פה בקטן שהוא \u0003חיגר שאינו יכול להתפשט\u0004 (להתרפא) \u0003וסומא שאינו יכול להתפתח,\u0004 אם כן מה השאלה? \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003גדול,\u0004 מבוגר, במצב כזה \u0003פטור, קטן מיבעיא\u0004 \u0005[נצרכה לומר]\u0006 שפטור?! \u0003לא צריכא\u0004 \u0005[נצרכה\u0006 אלא\u0005]\u0006 \u0003בחיגר שיכול להתפשט, וסומא שיכול להתפתח, מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006","\u0003אמר אביי: כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003גדול מיחייב מדאורייתא\u0004 \u0005[מחוייב מן התורה] —\u0006 \u0003קטן\u0004 באותו מצב \u0003נמי מחנכינן ליה מדרבנן\u0004 \u0005[גם כן מחנכים אותו מדברי סופרים],\u0006 ו\u0003כל היכא\u0004 \u0005[מקום]\u0006 שה\u0003גדול פטור מדאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 במצב כזה \u0003קטן נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור\u0004 לגמרי, וכאן כיון שהגדול פטור, גם קטן פטורים מלחנכו.","שנינו במשנה: \u0003בית שמאי אומרים,\u0004 עולת \u0003הראייה\u0004 צריכה שתהיה שווה \u0003שתי כסף,\u0004 ולבית הלל, החגיגה, קרבן השלמים, היא שצריכה להיות שווה שתי כסף.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003בית שמאי אומרים: הראייה שתי כסף, והחגיגה\u0004 רק \u0003מעה\u0004 אחת \u0003כסף.\u0004 והטעם שיש לדעתם להעדיף את העולה: \u0003שהראייה עולה כולה לגבוה, מה שאין כן בחגיגה,\u0004 שקרבן שלמים נאכל מקצתו לבעלים ולכהנים, \u0003ועוד\u0004 טעם שיש להעדיף יותר עולה משלמים: \u0003מצינו\u0004 (מצאנו) \u0003בעצרת\u0004 (בחג השבועות) \u0003שריבה בהן הכתוב\u0004 בקרבנות החג \u0003בעולות יותר מבשלמים\u0004 שמביאים פר אחד, שני אילים, ושבעה כבשים לעולה, ורק שני כבשים לשלמים.","\u0003ובית הלל אומרים: הראייה מעה כסף ו\u0004ה\u0003חגיגה שתי כסף.\u0004 וטעמם להעדפת קרבן זה: \u0003שחגיגה ישנה לפני הדיבור,\u0004 שהביאו קרבן שלמים עוד טרם מתן תורה, \u0003מה שאין כן בראייה. ועוד\u0004 טעם: שכן \u0003מצינו בנשיאים שריבה בהן הכתוב\u0004 בקרבנות שהביאו בימי חנוכת המשכן \u0003בשלמים יותר מבעולות,\u0004 שכן הביאו פר, איל וכבש לעולה ואילו לשלמים הביאו שני פרים, שני אילים, חמישה עתודים, וחמישה כבשים.","ושואלים: \u0003ובית הלל מאי טעמא לא אמרי\u0004 \u0005[מה טעם אינם אומרים]\u0006 \u0003כבית שמאי\u0004 וכיצד הם דוחים את ראיות בית שמאי? ומסבירים: \u0003דקא אמרת\u0004 \u0005[\u0006מה \u0005שאמרת],\u0006 שה\u0003ראייה עדיפא\u0004 משום ש\u0003עולה כולה לגבוה, אדרבא\u0004 \u0005[להיפך],\u0006 \u0003חגיגה עדיפא, דאית\u0004 \u0005[שיש]\u0006 \u0003בה שתי אכילות,\u0004 אכילה לגבוה ואכילה להדיוט. \u0003ודקא אמרת נילף\u0004 \u0005[ו\u0006מה \u0005שאמרת\u0006 ש\u0005נלמד]\u0006 \u0003מעצרת,\u0004 אף זו אינה הוכחה, כי \u0003דנין קרבן\u0004 ראייה שהוא קרבן \u0003יחיד מקרבן יחיד\u0004 של נשיאים, \u0003ואין דנין קרבן יחיד מקרבן\u0004 עצרת שהוא של \u0003צבור.\u0004","ומצד שני, \u0003ובית שמאי מאי טעמא לא אמרי\u0004 \u0005[מה טעם אינם אומרים]\u0006 \u0003כבית הלל?\u0004 ומסבירים: \u0003דקאמרת\u0004 \u0005[\u0006מה \u0005שאמרת]\u0006 \u0003חגיגה עדיפא\u0004 ש\u0003ישנה לפני הדיבור — ראייה נמי\u0004 \u0005[גם כן]\u0006 \u0003ישנה לפני הדיבור,\u0004 שלדעתם הקריבו ישראל לפני מתן תורה גם עולות,","\u0003ודקאמרת נילף\u0004 \u0005[ו\u0006מה \u0005שאמרת\u0006 ש\u0005נלמד]\u0006 \u0003מנשיאים\u0004 — אין זו הוכחה גמורה, כי \u0003דנין דבר הנוהג לדורות\u0004 קרבן ראייה שברגלים \u0003מדבר הנוהג לדורות\u0004 מקרבנות עצרת הנוהגים לדורות, \u0003ואין דנין דבר הנוהג לדורות מדבר שאינו נוהג לדורות\u0004 שהרי קרבנות הנשיאים מצוות המיוחדות לשעתן היו.","ושואלים: \u0003ו\u0004לשיטת \u0003בית הלל, מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה],\u0006 כלומר, על מה הם סומכים שהם אומרים ב\u0003חגיגה\u0004 שהיא \u0003ישנה לפני הדיבור — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויזבחו זבחים שלמים\u0004 לה' פרים\u0003\"\u0004 (שמות כד, ה), אולם \u0003ראייה נמי\u0004 \u0005[גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 באותו כתוב \u0003\"ויעלו עלת\"\u0004 (שמות כד, ה)!","ומשיבים: \u0003קסברי\u0004 \u0005[סבורים]\u0006 \u0003בית הלל: עולה\u0004 זו \u0003שהקריבו ישראל במדבר עולת תמיד הואי\u0004 \u0005[היתה]\u0006 שהוא קרבן הציבור, ולא היתה עולת יחיד במדבר, \u0003ובית שמאי סברי\u0004 \u0005[סבורים]\u0006 ש\u0003עולה\u0004 זו \u0003שהקריבו ישראל במדבר עולת ראייה הואי\u0004 \u0005[היתה]\u0006 וקרבן יחיד היתה.","\u0003אמר אביי: בית שמאי, ור' אלעזר, ור' ישמעאל, כולהו סבירא להו\u0004 \u0005[כולם סבורים הם]\u0006 ש\u0003עולה שהקריבו ישראל במדבר עולת ראייה הואי\u0004 \u0005[היתה],\u0006 \u0003ובית הלל, ור' עקיבא, ור' יוסי הגלילי, כולהו סבירא להו\u0004 \u0005[כולם סבורים הם]\u0006 ש\u0003עולה שהקריבו ישראל במדבר עולת תמיד הואי\u0004 \u0005[היתה]\u0006 ולא עולת יחיד.","ומפרטים: \u0003בית שמאי — הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 עכשיו. \u0003ר' ישמעאל — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' ישמעאל אומר: כללות נאמרו בסיני,\u0004 מה שנאמר למשה בסיני היו רק דינים כלליים (כעשרת הדברות וכיוצא בהם) ולא כל התורה כולה לפרטיה, ואף בענין הקרבנות לא נאמר לו אלא \"מזבח אדמה תעשה לי וזבחת עליו את עולותיך ואת שלמיך\" (שמות כ, כא), ולא נתפרש מתן דמיהם, הפשטם, וניתוחם של העולות והקרבת אימורי השלמים,"],["\u0003ופרטות\u0004 של דיני עשיית הקרבנות נאמרו למשה \u0003באהל מועד. ור' עקיבא אומר:\u0004 לא כן, \u0003כללות ופרטות נאמרו בסיני, ונשנו באהל מועד, ונשתלשו\u0004 על ידי משה לכל ישראל \u0003בערבות מואב\u0004 (בספר דברים). \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003עולה שהקריבו ישראל במדבר עולת תמיד הואי\u0004 \u0005[היתה]\u0006 ולא עולת יחיד,","אם כן \u0003מי איכא מידי דמעיקרא\u0004 \u0005[האם יש דבר שמתחילה]\u0006 \u0003לא בעי\u0004 \u0005[\u0006היה \u0005צריך]\u0006 \u0003הפשט וניתוח,\u0004 שהרי דין הפשט וניתוח הוא מפרטי המצווה שנאמרו בתורה, \u0003ולבסוף\u0004 נוסף דין זה בקרבן העולה כי \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003הפשט וניתוח.\u0004 אם כן מוכח מדברי ר' ישמעאל כי לא הקריבו עולת תמיד קודם לכן, ועולה שהקריבו במדבר היתה עולת ראיה.","\u0003ר' אלעזר — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 על הכתוב \u0003\"עלת תמיד העשיה בהר סיני\"\u0004 (במדבר כח, ו), \u0003ר' אלעזר אומר: מעשיה נאמרו בסיני,\u0004 כלומר, מצות עשייתה אמנם נאמרה בהר סיני \u0003והיא עצמה לא קרבה\u0004 במדבר כלל.","\u0003ר' עקיבא אומר: קרבה, ושוב לא פסקה,\u0004 כלומר, אף במדבר הקריבו עולת תמיד למן הקמת המשכן והלאה. ושואלים: \u0003אלא מה אני מקיים\u0004 כיצד מבין ר' עקיבא את הכתוב שנאמר בלשון שאלה \u0003\"הזבחים ומנחה הגשתם לי במדבר ארבעים שנה בית ישראל\"?\u0004 (עמוס ה, כה) שממנו מובן שלא הקריבו!","ועונים: \u0003שבטו של לוי שלא עבדו עבודה זרה הן הקריבו אותה,\u0004 אבל שאר העם לא הקריב. הרי בארנו דעות התנאים הסבורים שעולת התמיד לא היתה קרבה במדבר, והעולה שהקריבו היתה עולת ראיה.","והסוברים שקרבה במדבר; \u0003בית הלל — הא דאמרן\u0004 \u0005[זו שאמרנו].\u0006 \u0003ר' עקיבא\u0004 — \u0003הא נמי דאמרן\u0004 \u0005[זו גם כן שאמרנו]\u0006 במחלוקת עם ר' אליעזר. \u0003ר' יוסי הגלילי — דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר: שלש מצות נצטוו ישראל בעלותם לרגל:\u0004 עולת \u0003ראייה, ו\u0004שלמי \u0003חגיגה, ו\u0004שלמי \u0003שמחה.\u0004","\u0003יש בראייה שאין בשתיהן ויש בחגיגה שאין בשתיהן,\u0004 ו\u0003יש בשמחה שאין בשתיהן. יש בראייה שאין בשתיהן — שהראייה עולה כולה לגבוה, מה שאין כן בשתיהן\u0004 שרובן נאכל.","\u0003יש בחגיגה מה שאין בשתיהן — שהחגיגה\u0004 (כלומר, קרבן שלמים) \u0003ישנה\u0004 עוד \u0003לפני הדיבור\u0004 בהר סיני, \u0003מה שאין\u0004 כן \u0003בשתיהן.\u0004 ו\u0003יש בשמחה מה שאין בשתיהן — שהשמחה נוהגת באנשים ובנשים, מה שאין\u0004 כן \u0003בשתיהן.\u0004 הרי שהוא סבור שעולת ראייה לא קרבה במדבר והעולה שנזכרה בכתוב — ודאי עולת תמיד היתה.","ושואלים: \u0003ו\u0004ביחס ל\u0003ר' ישמעאל, מאי טעמא קא מוקמת ליה\u0004 \u0005[מה טעם,\u0006 אתה אביי, \u0005מעמיד,\u0006 מפרש, \u0005אותו]\u0006 \u0003כבית שמאי\u0004 שעולה שהקריבו במדבר עולת ראייה היא, ומה טעם אמרת כן — \u0003אי סלקא דעתך\u0004 \u0005[\u0006ש\u0005אם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003עולה שהקריבו ישראל במדבר עולת תמיד הואי\u0004 \u0005[היתה],\u0006 אם כן \u0003מי איכא מידי דמעיקרא\u0004 \u0005[האם יש דבר שמתחילה]\u0006 \u0003לא בעי\u0004 \u0005[\u0006היה \u0005צריך]\u0006 \u0003הפשט וניתוח, ולבסוף בעי\u0004 \u0005[צריך]\u0006 \u0003הפשט וניתוח,\u0004","על הוכחה זו יש לשאול: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יוסי הגלילי,\u0004 ש\u0003אמר: עולה שהקריבו ישראל במדבר עולת תמיד הואי\u0004 \u0005[היתה]\u0006 ובכל זאת הוא סבור ש\u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003לא בעי\u0004 \u0005[\u0006היה \u0005צריך]\u0006 \u0003הפשט וניתוח, ולבסוף בעי\u0004 \u0005[צריך]\u0006 \u0003הפשט וניתוח.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר: עולה שהקריבו ישראל במדבר אינה טעונה הפשט וניתוח, לפי שאין הפשט וניתוח אלא מאהל מועד ואילך!\u0004 ואומרים: אכן, אין הוכחה גמורה לענין בירור שיטת ר' ישמעאל בזה, ו\u0003סמי מכאן\u0004 \u0005[מחק מכאן]\u0006 מרשימה זו את \u0003ר' ישמעאל.\u0004","כיון שלפני כן הוזכר פסוק זה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב חסדא: האי קרא היכי כתיב\u0004 \u0005[פסוק זה איך\u0006 הוא \u0005כתוב],\u0006 כיצד יש להבין אותו? האם לומר כי \u0003\"וישלח את נערי בני ישראל ויעלו עלת\"\u0004 (שמות כד, ה), פירושו — \u0003כבשים,\u0004 והמשך הפסוק \u0003\"ויזבחו זבחים שלמים לה'\u0004 — \u0003פרים\". או דלמא\u0004 \u0005[שמא]\u0006 \u0003אידי ואידי\u0004 \u0005[אלה ואלה]\u0006 \u0003פרים הוו\u0004 \u0005[היו],\u0006 שגם העולות וגם הזבחים היו פרים, שהמלה \"פרים\" שבסוף הפסוק אומרת שכל הקרבנות שהקריבו היו פרים.","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 אם הקריבו לעולות כבשים או פרים? ועונים: \u0003מר זוטרא אמר: נפקא מינה\u0004 \u0005[יוצא מזה\u0006 הבדל לענין\u0005]\u0006 \u0003ל\u0004ענין \u0003פיסוק טעמים,\u0004 האם יש להפסיק בפסוק זה אחרי \"ויעלו עולות\", או לקרוא \"ויעלו עולות ויזבחו שלמים פרים\" כענין אחד.","\u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא אמר\u0004 שההבדל הוא: \u0003ל\u0004מי ש\u0003אומר\u0004 ונודר נדר: \u0003הרי עלי\u0004 להביא \u0003עולה כעולה שהקריבו ישראל במדבר,\u0004 שיש לברר \u0003מאי\u0004 \u0005[מה]\u0006 עליו להביא, האם \u0003פרים הוו\u0004 \u0005[היו]\u0006 ואם כן אף הוא מקריב פרים, \u0003או\u0004 שמא \u0003כבשים הוו\u0004 \u0005[היו]\u0006 ועליו להקריב כבשים\u0005?!\u0006 לשאלה זו לא נמצאה תשובה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003תנן התם\u0004 \u0005[שנינו שם,\u0006 במשנה\u0005]:\u0006 \u0003אלו דברים שאין להם שיעור,\u0004 שלא קבעה התורה שיעור מסויים למצוותם:"],["\u0003הפאה, והבכורים, והראיון, וגמילות חסדים, ותלמוד תורה.\u0004","\u0003אמר ר' יוחנן: כסבורין אנו לומר\u0004 מתחילה ש\u0003הראיון אין לו שיעור למעלה\u0004 שאפשר להוסיף ולהביא כמה שרוצים, \u0003אבל יש לו שיעור\u0004 מסויים \u0003למטה,\u0004 שמן התורה אין יוצאים ידי חובה בפחות מזה, כפי שמבואר במשנתנו, \u0003עד שבא ר' אושעיא ברבי\u0004 (הגדול, חכם בדורו) \u0003ולימד: הראיון אין לו שיעור\u0004 מן התורה \u0003לא למעלה ולא למטה, אבל חכמים\u0004 קבעו לכך שיעור, והם \u0003אומרים: הראייה — מעה כסף, והחגיגה — שתי כסף.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003הראיון\u0004 הנזכר שם? ונחלקו בכך אמוראים, \u0003ר' יוחנן אמר:\u0004 מצוות הראיון היא לענין \u0003ראיית פנים בעזרה,\u0004 שעולי הרגל יבואו למקדש, \u0003וריש לקיש אמר:\u0004 הכוונה היא ל\u0003ראיית פנים ב\u0004הבאת \u0003קרבן.\u0004","ומסבירים את שיטותיהם: \u0003בעיקר הרגל\u0004 כלומר, ביום טוב עצמו \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שמצות הראיון היא \u0003ראיית פנים בקרבן,\u0004 שודאי מצוה לעלות ולהביא קרבן עולה, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003בשאר ימות הרגל,\u0004 בימי חול המועד, האם עליו להביא עולת ראייה. ומוסיפים: \u0003כל היכא דאתא ואייתי\u0004 \u0005[כל מקום,\u0006 מקרה, \u0005שבא\u0006 למקדש \u0005והביא\u0006 קרבנות\u0005]\u0006 — \u0003כולי עלמא לא פליגי דמקבלינן מיניה\u0004 \u0005[הכל אינם חלוקים שמקבלים ממנו],\u0006 \u0003כי פליגי דאתא ולא אייתי\u0004 \u0005[כאשר נחלקו\u0006 היה זה במקרה \u0005שבא ולא הביא\u0006 קרבנות\u0005],\u0006 האם הבאת קרבן רשות היא, או שמוטלת עליו חובה להביא.","ש\u0003ר' יוחנן סבר:\u0004 מצוות \u0003ראיית פנים\u0004 היא להיות \u0003בעזרה,\u0004 ומשום כך \u0003כל אימת דאתי\u0004 \u0005[פעם שבא]\u0006 \u0003לא צריך לאתויי\u0004 \u0005[איננו צריך להביא\u0006 קרבן\u0005],\u0006 ואילו \u0003ריש לקיש אמר: ראיית פנים\u0004 היא \u0003בקרבן, דכל אימת דאתי צריך לאתויי\u0004 \u0005[שכל פעם שבא צריך להביא\u0006 קרבן\u0005].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן:\u0004 נאמר \u0003\"\u0004שלוש רגלים תחוג לי בשנה... \u0003ולא יראו פני ריקם\"\u0004 (שמות כג, יד-טו), משמע שצריך להביא קרבן כשבאים למקדש! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן בתשובה: שם מדובר \u0003בעיקר הרגל,\u0004 ביום הראשון, אבל לא בשאר הימים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ריש לקיש מברייתא, נאמר: \u0003\"ולא יראו פני ריקם\"\u0004 וכוונתו — \u0003בזבחים\u0004 (בהמות שזובחים — שוחטים אותן), לומר שצריך להביא עמו זבח. \u0003אתה אומר\u0004 שהכוונה היא \u0003בזבחים, או אינו אלא\u0004 אף \u0003ב\u0004קרבנות כגון \u0003עופות ומנחות? ודין הוא,\u0004 אפשר להבין את הדבר על ידי לימוד השוואה מכוח הסברה; \u0003נאמרה\u0004 מצוות קרבן שלמי \u0003חגיגה\u0004 שהיא \u0003ל\u0004צורך \u0003הדיוט\u0004 שנאכלת לבעלים, \u0003ונאמרה\u0004 מצוות \u0003ראייה\u0004 שהיא \u0003לגבוה, מה חגיגה האמורה להדיוט — זבחים, אף ראייה האמורה לגבוה — זבחים\u0004 ולא דבר אחר.","\u0003ומה הן זבחים\u0004 אלה — \u0003עולות\u0004 דווקא. \u0003אתה אומר\u0004 שזבחים הם \u0003עולות, או אינו אלא שלמים\u0004 שאף הם ממיני הזבחים? אף כאן \u0003ודין הוא; נאמרה חגיגה\u0004 שהיא \u0003ל\u0004צורך \u0003הדיוט,\u0004 שנאכלת לבעלים, \u0003ונאמרה ראייה\u0004 שהיא \u0003ל\u0004צורך \u0003גבוה,\u0004 עולה שכולה כליל לה'. \u0003מה חגיגה האמורה להדיוט — בראוי לו\u0004 שמביא קרבן שלמים שרובו נאכל לבעלים \u0003אף ראייה האמורה לגבוה — בראוי לו\u0004 ולכן יש להביא קרבן שכולו לגבוה — והוא קרבן עולה שכולו כליל על המזבח.","ומוסיפים: \u0003וכן בדין\u0004 (מן הסברה) מטעם אחר: \u0003שלא יהא שולחנך מלא\u0004 בבשר, \u0003ושולחן רבך\u0004 (אדונך, ה'), המזבח הקרוי \"השולחן לפני ה'\", \u0003ריקם,\u0004 ולכן צריך להביא בחג קרבן עולה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: ברייתא זו מדברת רק \u0003בעיקר הרגל,\u0004 בחג הראשון, ולא בימים אחרים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ריש לקיש, שנינו: \u0003ר' יוסי בר' יהודה אומר: שלש רגלים בשנה נצטוו ישראל לעלות ברגל: בחג המצות ובחג השבועות ובחג הסוכות. ואין נראין חצאין\u0004 כשרק חלק מן העם יבוא, \u0003משום שנאמר: \"\u0004יראה \u0003כל זכורך\"\u0004 (שמות כג, יז), \u0003ואין נראין ריקנים\u0004 בידים ריקות בלא קרבן, \u0003משום שנאמר: \"ולא יראו פני ריקם\"! אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: גם כאן מדובר \u0003בעיקר הרגל,\u0004 ולא בשאר הימים.","ולצד שני \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 מברייתא השנויה על הכתוב \"יראה כל זכורך\" שהכתיב הוא \u0003\"יראה\"\u0004 והקרי הוא \u0003\"יראה\",\u0004 ומן ההשוואה של הכתיב והקרי אנו למדים: \u0003מה אני בחנם,\u0004 שהקדוש ברוך הוא מראה פניו ואין על זה בקשת שכר, \u0003אף אתם\u0004 הבאים לראות פני — \u0003בחנם.\u0004 משמע שיש ראיית פנים בלי הבאת קרבן! ראיה זו נחשבת כמכרעת לדברי ר' יוחנן.","\u0003אלא\u0004 יש לדחות מה שאמרנו ולהסביר כך: \u0003כל היכא\u0004 \u0005[מקום]\u0006 \u0003דאתא\u0004 \u0005[שבא]\u0006 \u0003ולא אייתי\u0004 \u0005[הביא]\u0006 קרבן \u0003דכולי עלמא לא פליגי דעייל ומתחזי ונפיק\u0004 \u0005[הכל אינם חלוקים שנכנס ומראה עצמו ויוצא]\u0006 ואינו חייב בקרבן, \u0003כי פליגי דאתא ואייתי\u0004 \u0005[כאשר נחלקו\u0006 היה זה \u0005כאשר בא והביא\u0006 קרבן\u0005].\u0006","\u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 מצוות \u0003ראיית פנים\u0004 (\"ראיון\") היא להיראות \u0003בעזרה\u0004 על כן סבור הוא כי \u0003ראיית פנים\u0004 בלבד \u0003הוא\u0004 שאמרו ש\u0003אין לה שיעור, הא\u0004 \u0005[הרי]\u0006 \u0003לקרבן יש לה שיעור\u0004 ואם מביא קרבן חייב שיהיה לו שיעור מסויים. \u0003וריש לקיש אמר: ראיית פנים\u0004 (\"ראיון\") פירושה \u0003בקרבן,\u0004 ש\u0003אפילו קרבן נמי\u0004 \u0005[גם כן]\u0006 \u0003אין לו שיעור.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' יוחנן לריש לקיש: הלא נאמר \u0003\"הקר רגלך מבית רעך\u0004 פן ישבעך ושנאך\u0003\"\u0004 (משלי כה, יז), שמפרשים אותו גם כמתייחס לקדוש ברוך הוא, שהוא קרוי \"רע\" לישראל, שאין ראוי להרבות בקרבנות ובמתנות, ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003בחטאות ואשמות\u0004 שמוטב שלא ירבה את הצורך בהם, שימנע מחטא ולא יצטרך להביאם.","ו\u0003כד\u0004ברי \u0003ר' לוי.\u0004 ש\u0003ר' לוי רמי\u0004 \u0005[השליך,\u0006 הראה סתירה בין פסוקים\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב אחד: \u0003\"הקר רגלך מבית רעך\", וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק אחר: \u0003\"אבא ביתך בעולות\u0004 אשלם לך נדרי\u0003\"\u0004 (תהלים סו, יג)! ותירץ: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן בחטאות ואשמות\u0004 — מוטב שלא ירבה להביא, \u0003כאן בעולות ושלמים\u0004 מותר להרבות ולהביא.","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003\"הקר רגלך מבית רעך\" — בחטאות ואשמות הכתוב מדבר, אתה אומר בחטאות ואשמות או אינו אלא בעולות ושלמים? כשהוא אומר \"אבוא ביתך בעולות אשלם לך נדרי\" — הרי עולות ושלמים אמור\u0004 שיפה וראוי להביאם, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"הקר רגלך מבית רעך\" — בחטאות ואשמות הכתוב מדבר\u0004 שבהם אין להרבות.","שנינו בברייתא: \u0003ואין נראין חצאין. סבר רב יוסף למימר\u0004 \u0005[לומר,\u0006 לפרש\u0005]\u0006 כך את הדברים: \u0003מאן דאית ליה\u0004 \u0005[מי שיש לו]\u0006 \u0003עשרה בנים\u0004 ש\u0003לא ליסקו האידנא\u0004 \u0005[יעלו עכשיו]\u0006 לרגל \u0003חמשה ולמחר חמשה,\u0004 אלא יבואו כולם בבת אחת."],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 דבר זה \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 ואין צריך לאומרו, כי \u0003הי מינייהו משוית להו\u0004 \u0005[\u0006את \u0005אלה מהם תעשה אותם]\u0006 כ\u0003פושעים\u0004 (רשלנים), \u0003והי מינייהו משוית להו\u0004 \u0005[\u0006את \u0005אלה מהם תעשה אותם]\u0006 \u0003זריזין,\u0004 שודאי אינו ראוי שיאחרו אחדים לבוא וייראו כמתרשלים!","ושואלים: אם כן, \u0003אלא קרא למאי אתא\u0004 \u0005[פסוק\u0006 זה \"כל זכורך\" \u0005למה\u0006 הוא \u0005בא]?\u0006 ומשיבים: \u0003לכ\u0004 מו שאמרו \u0003אחרים, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אחרים אומרים: המקמץ\u0004 (אוסף צואת כלבים) \u0003והמצרף נחשת, והבורסי\u0004 (מעבד עורות) שכולם ריחם רע ביותר \u0003פטורין מן הראייה, שנאמר \"כל זכורך\" — מי שיכול לעלות עם כל זכורך, יצאו אלו שאינם יכולין לעלות עם כל זכורך\u0004 לפי שהכל מתרחקים מהם, ולכן אין עליהם חובת עלייה ברגל.","\u0003עולות\u0004 שמביאים \u0003במועד, באות מן החולין\u0004 ולא מכספים אחרים, כגון מעשר שני, \u0003והשלמים\u0004 אפשר להביא גם \u0003מן המעשר,\u0004 מכסף פדיון מעשר שני שמעלים ואוכלים בירושלים. שלמי \u0003יום טוב הראשון של פסח, בית שמאי אומרים:\u0004 מביאים \u0003מן החולין, ובית הלל אומרים:\u0004 אף \u0003מן המעשר.\u0004","ובכלל, \u0003ישראל יוצאין ידי חובתן\u0004 באכילת שלמי שמחה \u0003בנדרים ונדבות\u0004 שהתנדבו במשך כל השנה, וכשמביאים אותם לירושלים ברגל ואוכלים מהם — יוצאים בהם גם משום שמחת החג, \u0003ו\u0004כן \u0003במעשר בהמה. והכהנים\u0004 יוצאים ידי חובת שמחה \u0003ב\u0004אכילת \u0003חטאות ואשמות ובבכור,\u0004 שקרבנות אלה נאכלים לכהנים, \u0003ובחזה ושוק\u0004 שנותנים להם מן השלמים, ואף באכילתם יוצאים ידי חובת אכילת בשר שהיא משמחת החג, \u0003אבל לא\u0004 יוצאים \u0003בעופות,\u0004 חטאת העוף, \u0003ולא במנחות,\u0004 שאין משום שמחה אלא באכילת בשר בהמה.","נאמר במשנה שעולות בחול המועד באות מן החולין, ומדייקים: \u0003אלא עולות במועד\u0004 בלבד \u0003הוא\u0004 ש\u0003באות מן החולין,\u0004 ומכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ביום טוב\u0004 באות אף \u0003מן המעשר, אמאי\u0004 \u0005[מדוע]?\u0006 הלא עולה \u0003דבר שבחובה היא, ו\u0004כלל הוא ש\u0003כל דבר שבחובה,\u0004 קרבן שחובתו של אדם להביא — \u0003אינו בא אלא מן החולין\u0004 ואינו יוצא ידי חובה אלא בדבר שהוקדש לצורך זה בלבד ולא לצורך אחר.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיעה לנו\u0006 המשנה\u0005]\u0006 כשאמרה \"במועד\", שהדיוק הוא אחר: ש\u0003עולות במועד — באות, ביום טוב — אינן באות\u0004 כלל, שאין מקריבים אותן ביום טוב. ותוהים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 תעמיד את המשנה — \u0003כבית שמאי?!\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003בית שמאי אומרים: מביאין\u0004 ביום טוב \u0003שלמים, ואין סומכין עליהן,\u0004 לפי שיש צד של מלאכה בסמיכת בהמה ביום טוב, \u0003אבל לא\u0004 מביאים \u0003עולות,\u0004 שלפי שאינן נאכלות אינן איפוא צורך אדם אלא צורך גבוה, ולא הותרה שחיטה ביום טוב אלא לצורכי אדם. \u0003ובית הלל אומרים: מביאין\u0004 גם \u0003שלמים ו\u0004גם \u0003עולות, וסומכין עליהן.\u0004 ותמוה הדבר שסתם משנה תהא כדעת בית שמאי שנדחתה מן ההלכה!","ומשיבים: כדי להבין את המשנה יש לפרש כי \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך שנה\u0006 התנא\u0005],\u0006 כך צריך לומר: \u0003עולות\u0004 של \u0003נדרים ונדבות\u0004 שאינן מחובות הרגל, \u0003במועד — באות, ביום טוב — אינן באות, ועולת ראייה — באה אפילו ביום טוב. וכשהיא באה — אינה באה אלא מן החולין\u0004 שהרי חובה היא. \u0003ושלמי שמחה באין אף מן המעשר. וחגיגת\u0004 (קרבן שלמים של חג) של \u0003יום טוב הראשון של פסח, בית שמאי אומרים: מן החולין\u0004 דווקא, \u0003ובית הלל אומרים:\u0004 אף \u0003מן המעשר.\u0004","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא מפורשת \u0005גם כן כך]:\u0006 \u0003עולות נדרים ונדבות\u0004 שאינן מחובות הרגל \u0003במועד — באות, ביום טוב\u0004 — \u0003אינן באות. ועולת ראייה — באה אפילו ביום טוב. וכשהיא באה — אינה באה אלא מן החולין. ושלמי שמחה באין אף מן המעשר. וחגיגת יום טוב הראשון של פסח, בית שמאי אומרים:\u0004 אינה באה אלא \u0003מן החולין, ובית הלל אומרים:\u0004 אף \u0003מן המעשר.\u0004","בנושא האחרון שואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 במה התייחדה\u0005]\u0006 \u0003חגיגת יום טוב הראשון של פסח\u0004 מקרבן חגיגה של שאר ימים טובים? \u0003אמר רב אשי: הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 בהדגשת הדבר, כדי למעט משהו, כלומר, כי \u0003חגיגת חמשה עשר,\u0004 שלמי החגיגה הבאים ביום הראשון של החג — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003חגיגת ארבעה עשר,\u0004 שכאשר היה קרבן פסח מועט לפי מנין המנויים עליו, היו מביאים קרבן נוסף לשלמים, כדי שיהא הפסח נאכל על השובע, וקרבן זה הקרוי \"חגיגת ארבעה עשר\" — \u0003לא,\u0004 אין חיוב להביאה מן החולין דווקא, לפי שאינה חובה גמורה."],["\u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005סבור\u0006 הוא\u0005]\u0006 ש\u0003חגיגת ארבעה עשר לאו דאורייתא\u0004 \u0005[אינה מן התורה],\u0006 וכיון שאין חובה מן התורה להביאה, יכול להביאה אף מן המעשר.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא, \u0003בית הלל אומרים:\u0004 מביאים שלמי חגיגה אף \u0003מן המעשר.\u0004 ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הלא \u0003דבר שבחובה הוא, וכל דבר שבחובה אינו בא אלא מן החולין,\u0004 וכיצד יכול להביא קרבנות חובתו מן המעשר? \u0003אמר עולא:\u0004 מדובר פה \u0003בטופל\u0004 (מוסיף) כלומר, שמוסיף מן המעשר על החולין ומביאם כאחד.","בפרטי הלכה זו של טפילה נחלקו אמוראים: \u0003חזקיה אמר, טופלין בהמה לבהמה,\u0004 שאם יש בביתו אנשים רבים ולא תספיק בהמה אחת, מביא בהמה אחת לשם חגיגה מן החולין, והשאר יטפול (יוסיף) ויקנה מכספי המעשר, שכיון שיוצא ידי חובת חגיגה באחת מהם יכול להביא את האחרות ממעשר שני או מעשר בהמה, \u0003ואין טופלין מעות למעות,\u0004 שאין לצרף כספי מעשר וכספי חולין כדי לקנות בהם בהמה אחת לחגיגה. \u0003ור' יוחנן אמר\u0004 להיפך: \u0003טופלין מעות למעות, ואין טופלין בהמה לבהמה.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003חזקיה, תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן.\u0004 ומפרטים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן,\u0004 נאמר: \u0003\"מסת\u0004 נדבת ידך אשר תתן\u0003\"\u0004 (דברים טז, י) — \u0003מלמד שאדם מביא חובתו מן החולין. ומנין שאם רצה לערב מערב — תלמוד לומר: \"כאשר יברכך ה' אלהיך\"\u0004 (דברים טז, י) משמע שיכול להוסיף, ולשון \"מערב\" משמעה — עירוב כספים זה בזה.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003חזקיה: \"מסת\" — מלמד שאדם מביא חובתו מן החולין,\u0004 ונחלקו בדין זה בית שמאי ובית הלל ש\u0003בית שמאי אומרים: יום ראשון\u0004 אינו מביא אלא \u0003מן החולין, מכאן ואילך\u0004 מביא אף \u0003מן המעשר. ובית הלל אומרים: אכילה ראשונה מן החולין, מכאן ואילך מן המעשר.\u0004 ואנו מבינים ש\"אכילה ראשונה\" היא בהמה ראשונה שאוכל וזה כשיטת חזקיה.","וכל זה אמור ביום טוב עצמו, \u0003ושאר כל ימות הפסח,\u0004 שבהם חייב להביא שלמי שמחה, \u0003אדם יוצא ידי חובתו\u0004 אפילו \u0003במעשר בהמה.\u0004 ושואלים: \u0003ביום טוב מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 יוצא ידי חובה במעשר בהמה?","\u0003אמר רב אשי:\u0004 יש לחשוש שאם יזדקק לבהמות נוספות, כיון שהדבר נחוץ לו \u0003דלמא אתי לעשורי\u0004 \u0005[שמא יבוא לעשר]\u0006 \u0003ביום טוב\u0004 עצמו, \u0003ואי אפשר לעשר ביום טוב משום סקרתא\u0004 \u0005[הצבע],\u0006 שכל היוצא עשירי היו צובעים אותו בצבע אדום, וכיון שהדבר אסור ביום טוב משום מלאכת כותב, אי אפשר להפריש מעשר.","ולבירור דברי הברייתא שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003משמע,\u0004 כיצד מובן \u0003דהאי מסת לישנא\u0004 \u0005[ש\"מסת\" זה האמור\u0006 בכתוב \u0005לשון]\u0006 של \u0003חולין הוא?\u0004 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישם המלך אחשורוש מס על הארץ\"\u0004 (אסתר י, א), ובוודאי שמדובר במס שהוא חולין.","שנינו במשנה כי \u0003ישראל יוצאין ידי חובתן\u0004 במצות שמחה \u0003בנדרים ונדבות. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הכתוב \u0003\"ושמחת בחגך\"\u0004 (דברים טז, יד) — \u0003לרבות כל מיני שמחות ל\u0004מצות \u0003שמחה,\u0004 שכיון שציוותה התורה לשמוח (באכילת בשר) בחג, וכל הראוי לאכילה מצטרף למצוה זו, \u0003מכאן אמרו חכמים: ישראל יוצאין ידי חובתן\u0004 בשמחה על ידי זה שאוכלים \u0003ב\u0004בשר \u0003נדרים ונדבות ובמעשר בהמה,\u0004","\u0003והכהנים\u0004 יוצאים ידי חובת שמחה \u0003ב\u0004אכילת \u0003חטאת ואשם ובבכור, ובחזה ושוק\u0004 של שלמים. \u0003יכול\u0004 יצאו \u0003אף ב\u0004אכילת \u0003עופות\u0004 (חטאת העוף) \u0003ובמנחות — תלמוד לומר: \"ושמחת בחגך\",\u0004"],["\u0003מי\u0004 (אותם דברים) \u0003ש\u0004קרבן \u0003חגיגה\u0004 (\"בחגך\") \u0003באה מהם,\u0004 כלומר, מן הצאן והבקר, \u0003יצאו אלו\u0004 עופות ומנחות \u0003שאין\u0004 קרבן \u0003חגיגה באה מהם.\u0004","\u0003רב אשי אמר:\u0004 שאין צורך ללמוד מ\"ושמחת בחגך\" ולהבין את המושג \"חג\" במובן קרבן חגיגה, אלא \u0003מ\u0004עצם המלה \u0003\"ושמחת\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 דבר זה, כלומר: \u0003יצאו אלו\u0004 עופות ומנחות \u0003שאין בהן שמחה,\u0004 שאין שמחת אכילה אלא בבשר בהמה.","ושואלים: \u0003ורב אשי, האי\u0004 \u0005[\u0006המלה \u0005הזאת]\u0006 \u0003\"בחגך\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בה]\u0006 לאיזה ענין הוא דורשה? ומשיבים: הכתוב \u0003ההוא,\u0004 \"בחגך\" בא ללמד \u0003לכ\u0004 דברי \u0003רב דניאל בר קטינא,\u0004 ש\u0003אמר רב דניאל בר קטינא אמר רב: מניין שאין נושאין נשים ב\u0004חול ה\u0003מועד — שנאמר \"ושמחת בחגך\"\u0004 (דברים טז, יד) ויש בו הדגשה: בחגך \u0003ולא באשתך.\u0004","\u0003מי שיש לו אוכלים מרובים\u0004 שבני ביתו מרובים במספר, \u0003ונכסים מועטים — מביא שלמים מרובים ועולות מועטות,\u0004 ומן השלמים יאכלו בני ביתו. אם יש לו \u0003נכסים מרובים ואוכלין מועטין — מביא עולות מרובות ושלמים מועטין.\u0004","היה \u0003זה וזה מועט\u0004 בביתו — \u0003על זה נאמר\u0004 שקבעו חכמים את השיעור הקטן ביותר — \u0003מעה כסף\u0004 לעולת ראייה ו\u0003שתי כסף\u0004 לשלמי חגיגה. אם היו לו \u0003זה וזה מרובים — על זה נאמר \"איש כמתנת ידו כברכת ה' אלהיך אשר נתן לך\"\u0004 (דברים טז, יז).","נאמר במשנה שמי שיש לו אוכלים מרובים ונכסים מעטים מביא \u0003שלמים מרובים.\u0004 ושואלים: \u0003מהיכא מייתי\u0004 \u0005[מהיכן\u0006 הוא \u0005מביא]\u0006 שלמים מרובים? \u0003הא לית ליה\u0004 \u0005[הרי אין לו]\u0006 נכסים! \u0003אמר רב חסדא: טופל.\u0004 כלומר, מוסיף כספים, מכספי המעשר \u0003ומביא פר גדול,\u0004 ועל ידי זה יש לו שלמים מרובים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ששת: הרי אמרו טופלין בהמה לבהמה!\u0004","דבריו אלה של רב ששת לא היו ברורים, ושואלים: \u0003מאי קאמר ליה\u0004 \u0005[מה אמר לו]\u0006 מה היתה כוונת רב ששת בדבריו אלה? \u0003אילימא הכי קאמר ליה\u0004 \u0005[אם לומר\u0006 ש\u0005כך אמר לו]:\u0006 \u0003הרי אמרו טופלין בהמה לבהמה אבל לא מעות למעות,\u0004 ולכן אינו יכול להביא פר גדול אחד, אם כן \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 בבירור מה שרצה לומר: \u0003אין טופלין מעות למעות!\u0004 ומשום מה לא אמר את דבריו במפורש אלא ברמז בלבד? \u0003אלא הכי\u0004 \u0005[כך]\u0006 \u0003אמר ליה\u0004 \u0005[לו],\u0006 כך היתה כוונתו: \u0003הרי אמרו אף טופלין בהמה לבהמה.\u0004 כלומר, אין חייבים לעשות רק בדרך זו של החלפה לפר גדול על-ידי הוספת מעות, ואפשר גם לטפול בהמה אחרת שיקדישה לשלמים.","אולם אם כן \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אמר זאת? שהרי זו שיטה חדשה בהלכה, ש\u0003לא כ\u0004שיטת \u0003חזקיה\u0004 האומר שטופלים רק בהמה לבהמה \u0003ו\u0004ש\u0003לא כ\u0004שיטת \u0003ר' יוחנן\u0004 האומר שטופלים רק מעות למעות!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אמוראי הוא דפליגי, מתנייתא לא פליגי\u0004 \u0005[האמוראים הם שחולקים, הברייתות אינן חלוקות],\u0006 שהברייתות שהבאנו לסייע לדבריהם אינן מוציאות זו מדברי זו, אלא בכל אחת יש הצעת דרך אחרת, ולכן יכול רב ששת, למרות שהיה בדור מאוחר, לחלוק על האמוראים הראשונים חזקיה ור' יוחנן. \u0003ו\u0004אולם אי אפשר לומר כן, כי \u0003הא קתני\u0004 \u0005[הרי שנה\u0006 בברייתא\u0005]:\u0006 \u0003אכילה ראשונה מן החולין,\u0004 ולכאורה משמע במפורש כאן כשיטת חזקיה שיש לחלק בין בהמה שהיא כולה חולין (אכילה ראשונה) ובין בהמה שהיא כולה מן המעשר (אכילה שניה), ודבר זה אינו ניתן להיעשות אלא כשטופלים בהמה לבהמה ולא כשטופלים מעות למעות.","ודוחים: משם אין ראיה גמורה, כי אפשר לומר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אכילה ראשונה\u0004 — שלכשיטפלו מעות למעות ויקנו בהמה מכסף חולין ומכסף מעשר גם יחד, יהיה בה \u0003שיעור דמי אכילה ראשונה מן החולין.\u0004","\u0003אמר עולא אמר ריש לקיש: הפריש עשר בהמות לחגיגתו\u0004 לצורך קרבן חגיגה, \u0003הקריב חמש\u0004 מהן \u0003ביום טוב ראשון — חוזר ומקריב חמש ביום טוב שני,\u0004 שבכל יום מימי הרגל יכול להביא קרבן חגיגתו ואין חוששים משום \"בל תוסיף\". \u0003ר' יוחנן אמר: כיון שפסק\u0004 להקריב ביום הראשון שהביא בו את החגיגה \u0003שוב אינו מקריב\u0004 בימים אחרים.","\u0003אמר ר' אבא: ולא פליגי\u0004 \u0005[ואינם חלוקים],\u0006 ששני האמוראים מדברים במקרים שונים; \u0003כאן בסתם\u0004 שאם הפריש בהמות סתם לחגיגתו היתה כוונתו שיוקרבו כולן ביום הראשון, ואם לא הקריבן — שוב אינו רשאי להקריבן. ו\u0003כאן במפרש\u0004 בשעת נדבתו שלא יקריב את כולן ביום הראשון, אלא גם בימים אחרים (ר\"ח).","ושואלים: \u0003האי סתם היכי דמי\u0004 \u0005[סתם זה\u0006 שאמרנו \u0005כיצד הוא בדיוק]?\u0006 \u0003אילימא דליכא\u0004 \u0005[אם תאמר שאין]\u0006 עוד \u0003שהות ביום לקרב\u0004 שהביא את בהמותיו כולן ביום הראשון והתברר שאין זמן להקריב את כולן והוקרב רק חלק מהן, אם כן \u0003האי\u0004 \u0005[זה]\u0006 ש\u0003לא אקרבינהו\u0004 \u0005[הקריבן]\u0006 הוא מפני \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003שהות ביום\u0004 עוד, וכשמקריבן ביום אחר אפשר לראות זאת כהשלמה של חובת היום הראשון.","\u0003ואלא\u0004 תאמר \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003אוכלין,\u0004 שהתברר שאין מספיק אנשים בביתו שיאכלו את הקרבנות הללו ולא יותירו מהם, אף כאן, \u0003האי\u0004 \u0005[זה]\u0006 ש\u0003לא אקרבינהו\u0004 \u0005[הקריבן]\u0006 — מפני \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003אוכלין\u0004 ואין זו דחיה מרצון.","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003שהות ביום ואית ליה\u0004 \u0005[ויש לו]\u0006 \u0003אוכלין, מדבקמא\u0004 \u0005[\u0006ו\u0005כיון שב\u0006יום \u0005הראשון]\u0006 \u0003לא אקרבינהו\u0004 \u0005[הקריבן],\u0006 \u0003שמע מינה שיורי שיירינהו\u0004 \u0005[משמע ששייר אותן]\u0006 בכוונה, וכיון ששיירן שוב איננו יכול להקריבן בשאר ימי החג, שיש בכך משום תוספת.","ומעירים: \u0003והכי נמי מסתברא\u0004 \u0005[וכך גם כן מסתבר\u0006 לומר\u0005]\u0006 שר' יוחנן מודה במפרש, \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: הפריש עשר בהמות לחגיגתו,\u0004 ו\u0003הקריב חמש ביום טוב ראשון — חוזר ומקריב חמש ביום טוב שני.\u0004 ולכאורה \u0003קשיין אהדדי\u0004 \u0005[קשות הן זו על זו]\u0006 השמועה שמסר רבין וזו שמסר עולא בשם ר' יוחנן,","\u0003אלא לאו שמע מינה\u0004 \u0005[\u0006האם \u0005לא תלמד מכאן]\u0006 כי \u0003כאן — בסתם,\u0004 אסור להשלים את הקרבתן ביום אחר, \u0003כאן — במפרש,\u0004 יכול להקריב את השאר אף בשאר ימי החג, וכפי שפירש. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 בשם אמורא אחר, ש\u0003אמר רב שמן בר אבא אמר ר' יוחנן:\u0004"],["\u0003לא שנו\u0004 (להלן) אותו (את יום טוב הראשון) את חוגג ואין אתה חוגג כל שבעה, \u0003אלא שלא גמר, אבל גמר — חוזר ומקריב.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"גמר\"? אילימא\u0004 \u0005[אם לומר]\u0006 שהכוונה היא ש\u0003גמר\u0004 להקריב \u0003קרבנותיו\u0004 ושוב אין בידו קרבנות — אם כן \u0003מאי\u0004 \u0005[מה]\u0006 חוזר ו\u0003מקריב? אלא\u0004 הכוונה היא \u0003שלא גמר היום,\u0004 ועדיין נשארו לו קרבנות — שאותם אינו חוזר ומקריב בשאר ימי החג, \u0003אבל\u0004 אם \u0003גמר היום\u0004 ולא הספיק להקריב — \u0003חוזר ומקריב,\u0004 משמע שאף ר' יוחנן סבור שפעמים רשאי להקריב קרבן חגיגה שלא בפעם אחת.","\u0003מי שלא חג\u0004 (לא הקריב קרבן חגיגה) \u0003ביום טוב הראשון של חג\u0004 הסוכות — \u0003חוגג\u0004 (מביא \u0003את\u0004 קרבנותיו) ב\u0003כל\u0004 שאר ימי \u0003הרגל, ו\u0004אף ב\u0003יום טוב האחרון של חג\u0004 (שמיני עצרת).","\u0003עבר הרגל ולא חג — אינו חייב באחריותו,\u0004 שאף אם הפרישו ונאבד אינו צריך להביא קרבן אחר תחתיו, אלא איבד את המצוה, ו\u0003על זה נאמר \"מעוות לא יוכל לתקן וחסרון לא יוכל להמנות\"\u0004 (קהלת א, טו).","\u0003ר' שמעון בן מנסייא אומר: איזהו מעוות שאינו יכול להתקן?\u0004 לא כדוגמת הנאמר במשנה, שהיא רק הימנעות ממצוה, אלא \u0003זה הבא על הערוה והוליד ממנה ממזר,\u0004 שאינו יכול לתקן לחלוטין את עוונו, שהרי הממזר חי. שכן \u0003אם תאמר\u0004 שמדובר \u0003בגונב וגוזל\u0004 — אמנם מעוות הוא, אבל יכול לתקון שהרי \u0003יכול הוא להחזירו\u0004 את מה שלקח, \u0003ויתקן.\u0004","\u0003ר' שמעון בן יוחי אומר: אין קורין מעוות אלא למי שהיה מתוקן בתחילה ונתעוות, ואיזה? זה תלמיד חכם הפורש מן התורה\u0004 שהיה מתוקן ונתקלקל — הוא שאינו יכול לבא לידי תיקון.","נאמר במשנה שאם לא הביא חגיגתו ביום טוב ראשון של חג הסוכות, יכול להביאה אף בשמיני עצרת, אף שהוא לכאורה חג לעצמו, ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' ישמעאל:\u0004 לומדים גזירה שווה, \u0003נאמר \"עצרת\" בשביעי של פסח\u0004 (דברים טז, ח) \u0003ונאמר \"עצרת\" בשמיני של חג\u0004 (ויקרא כג, לו), \u0003מה להלן\u0004 עצרת של פסח היא \u0003לתשלומין,\u0004 שהרי היא בוודאי חלק מן החג, ואפשר להשלים בה את חובות החג — \u0003אף כאן\u0004 שמיני עצרת של חג הסוכות הוא \u0003לתשלומין.\u0004","ומעירים: צריך לומר שבשני המקרים הללו המלה \"עצרת\" איננה נחוצה לענין אחר אלא ללימוד זה, והיא \u0003מופנה\u0004 (פנויה ומיוחדת ללימוד זה), \u0003דאי לאו\u0004 \u0005[שאם איננה]\u0006 \u0003מופנה\u0004 הרי לפי הכללים שבידינו, אם המלים המשמשות לצורך גזירה שווה אינן לגמרי מופנות (כלומר, בלתי נחוצות לענין), \u0003איכא למיפרך\u0004 \u0005[יש\u0006 אפשרות \u0005להפריך\u0006 לשבור\u0005]\u0006 את הגזירה השווה אם מוצאים הבדל בין הנושאים, וכאן גם כן יש מקום להקשות: \u0003מה לשביעי של פסח שכן אינו חלוק\u0004 בדינו \u0003מן\u0004 הימים \u0003שלפניו\u0004 לענין קרבנות החג ואיסור חמץ, \u0003תאמר בשמיני של חג\u0004 הסוכות \u0003שחלוק מן\u0004 הימים \u0003שלפניו\u0004 שהרי אין בו חיוב סוכה ולולב,","\u0003לאיי אפנויי מופנה\u0004 \u0005[על כן\u0006 ודאי \u0005מופנה].\u0006 וכיצד אנו מוכיחים זאת; \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עצרת\" — עצור\u0004 (מנוע, אסור) \u0003בעשיית מלאכה,\u0004 אולם דבר זה אינו נחוץ, \u0003הכתיב\u0004 \u0005[\u0006ש\u0005הרי נאמר]\u0006 במפורש באותו יום \u0003\"לא תעשה מלאכה\"\u0004 (דברים טז, ח), ואם כן, \u0003\"עצרת\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי? אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבא הדבר \u0003לאפנויי\u0004 \u0005[להפנות]\u0006 ועל מנת להשוות את הדינים בדרך גזירה שווה.","ומעירים: \u0003ו\u0004ה\u0003תנא\u0004 בברייתא \u0003מייתי לה מהכא\u0004 \u0005[מביא,\u0006 לומד \u0005אותה\u0006 את ההלכה הזו, \u0005מכאן]\u0006 מפסוק אחר: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר בחג הסוכות: \u0003\"וחגתם אתו חג לה' שבעת ימים\"\u0004 (ויקרא כג, מא), \u0003יכול יהא חוגג והולך\u0004 (מביא קרבנות הרגל) \u0003כל שבעה\u0004 ימים של החג — \u0003תלמוד לומר: \"אתו\",\u0004 ונדייק: \u0003אותו,\u0004 את יום הראשון של החג, \u0003אתה חוגג, ואי אתה חוגג כל שבעה. אם כן למה נאמר \"שבעה\" — לתשלומין,\u0004 ליום הראשון.","\u0003ומנין שאם לא חג יום טוב הראשון של חג\u0004 הסוכות \u0003שחוגג והולך את כל הרגל ו\u0004גם \u0003יום טוב האחרון\u0004 של סוכות — \u0003תלמוד לומר: \"בחדש השביעי תחגו אתו\"\u0004 (ויקרא כג, מא) משמע שאפשר לחוג לא רק בשבעת ימי החג, אלא גם לאחר מכן, \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"בחדש השביעי\" — יכול יהא חוגג והולך\u0004 כל \u0003החדש כולו — תלמוד לומר \"אותו\",\u0004 משמעו: \u0003\"אותו\"\u0004 את החג \u0003אתה חוגג, ואי אתה חוגג חוצה לו\u0004 בימי החול.","לעצם ההלכה הנזכרת בברייתא זו שואלים: \u0003ומאי\u0004 \u0005[ומה\u0006 המשמעות\u0005]\u0006 של \u0003תשלומין\u0004 ששנינו? ומשיבים, \u0003ר' יוחנן אמר: תשלומין לראשון,\u0004 שכל קרבנות שהיה חייב להביא ביום הראשון של הרגל ולא הביא — יכול להשלים הבאתם בימים אחרים. \u0003ור' אושעיא אמר: תשלומין זה לזה,\u0004 שכל יום הוא חיוב לעצמו — אם לא הביא קודם את קרבנו.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]?\u0006 ומשיבים, \u0003אמר ר' זירא:\u0004 לענין מי שהיה \u0003חיגר ביום\u0004 ה\u0003ראשון\u0004 של החג \u0003ונתפשט\u0004 (והבריא) \u0003ביום\u0004 ה\u0003שני איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה, לדעת \u0003ר' יוחנן\u0004 ש\u0003אמר:\u0004 הימים האחרים הם \u0003תשלומין לראשון\u0004 בלבד, ו\u0003כיון\u0004 ש\u0003לא חזי\u0004 \u0005[\u0006היה \u0005ראוי]\u0006 לחוג \u0003בראשון\u0004 שוב \u0003לא חזי\u0004 \u0005[אינו ראוי]\u0006 גם \u0003בשני,\u0004 שהרי השני אינו אלא תשלומים לראשון בלבד. \u0003ו\u0004לדעת \u0003ר' אושעיא\u0004 ש\u0003אמר\u0004 שכל הימים הם \u0003תשלומין זה לזה,\u0004 ומשום כך \u0003אף על גב דלא חזי\u0004 \u0005[אף על פי שאינו ראוי]\u0006 \u0003בראשון\u0004 מכל מקום הרי \u0003חזי\u0004 \u0005[\u0006הוא \u0005ראוי]\u0006 \u0003בשני,\u0004 שהרי הוא חיוב בפני עצמו.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 והרי במקום אחר נחלקו אמוראים בפרטי דיני הנזיר; נזיר שנטמא במת חייב להביא קרבן על טומאתו ועליו להתחיל למנות את ימי נזירותו מתחילה. אמנם הנזיר מביא קרבן אחד על טומאות רבות, אבל אם עברו שמונה ימים מאז טומאתו הראשונה וחזר ונטמא, חייב הוא להביא שני קרבנות, משום שהטומאה השניה היתה בזמן הראוי כבר למנין נזירותו המחודשת.","ובפרטי דין זה נחלקו: \u0003חזקיה אמר\u0004 שאם \u0003נטמא ביום\u0004 השמיני — \u0003מביא\u0004 קרבן נוסף, אולם אם נטמא \u0003בלילה\u0004 שלפניו — \u0003אינו מביא,\u0004 שכיון שהלילה אינו זמן ראוי להבאת קרבנות, לכן אף שכבר עברו שבעה ימים, עדיין איננו נחשב כאילו נטמא ביום שראוי לו להבאת הקרבן, היום השמיני, ואינו חייב להביא קרבן נוסף, אלא די לו בקרבן אחד.","\u0003ור' יוחנן אמר: אף\u0004 אם נטמא \u0003בלילה נמי\u0004 \u0005[גם כן]\u0006 \u0003מביא\u0004 קרבן נוסף, שאף כי הלילה אינו ראוי לקרבן, ואינו נחשב כראוי לגמרי לחובת נזירות, בכל זאת סבור ר' יוחנן שמביא קרבן נוסף, ומכאן שהוא סובר, שמי שלא יכול להביא קרבן בזמן מסויים, לא נדחה על ידי כך לחלוטין, ועדיין הוא נחשב כמחוייב בדבר הואיל ויש לו תשלומין למחר.","\u0003אמר ר' ירמיה:\u0004 יש להבדיל בין המקרים, כי \u0003שאני\u0004 \u0005[שונה]\u0006 קרבן הבא מחמת ה\u0003טומאה דיש לה תשלומין בפסח שני\u0004 שאין לראות את הדיחוי כשאינו ראוי לקרבן כדיחוי מוחלט, המבטל את עצם חובת הקרבן באותו יום, וראיה לדבר מדיני קרבן פסח, שמי שלא יכל להקריב את הפסח בזמנו מחמת טומאה, אינו נדחה לגמרי, אלא משלים את הקרבתו בארבעה עשר באייר (פסח שני), ואף דין נזיר שנטמא כן.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך],\u0006 על סברה זו \u0003רב פפא: הניחא\u0004 \u0005[זה נוח]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003פסח\u0004"],["\u0003שני תשלומין\u0004 של פסח \u0003ראשון הוא,\u0004 שאינו אלא תשלום של קרבן פסח למי שנתחייב בראשון ונאנס בטומאה או שהיה בדרך רחוקה ובשל כך לא עשאו, ורק לדעה זו ניתן להוכיח מכאן שטומאה אינה עושה דחיה גמורה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי פסח \u0003שני רגל בפני עצמו הוא\u0004 שנקבע לאותם אנשים שלא הקריבו עוד את קרבן הפסח (גם אם לא נתחייבו בו בשעתו), אם כן אין מכאן כל הוכחה לענין תשלומים למי שנטמא, ולשיטה זו \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003אלא אמר רב פפא:\u0004 יש לדחות את תירוצו של ר' ירמיה, ולומר כי \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יוחנן\u0004 כי \u0003לילה אינו מחוסר זמן,\u0004 שאף על פי שבלילה אי אפשר בפועל להקריב קרבן, אולם מי שהיה ראוי כבר להקריב באותו זמן, גם אם היה זה בלילה — איננו נחשב כמחוסר זמן. ואף לענייננו, כיון שבתחילת הלילה היה טהור, הרי זה כאילו כבר היה טהור ביום השמיני, אף שבפועל איננו יכול להקריב, ולכן טומאה חדשה בלילה זה מחייבתו להביא קרבן נוסף. ותוהים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 שלילה אינו נחשב כמחוסר זמן?","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 בדיני זב, שזב מביא קרבן אחד אף על זיבות הרבה, אולם אם חזר וראה לאחר שכבר נטהר ונתחייב קרבן — חוזר ומביא קרבן על זיבתו הנוספת. ואמר ר' יוחנן, שאם לאחר שספר הזב שבעה נקיים חזר ו\u0003ראה\u0004 זיבה \u0003אחת בלילה ושתים ביום — מביא\u0004 קרבן על הטומאה השניה, כי אף שהראייה הראשונה היתה בלילה, עיקר הזיבה היא בשתים האחרונות. ושתי הראיות שביום מצטרפות לראשונה, והרואה זוב שלוש פעמים חייב בקרבן.","אבל אם ראה \u0003שתים בלילה ואחת ביום — אינו מביא,\u0004 משום שהראייה השניה שבלילה איננה נחשבת, כיון שאין הזמן ראוי עדיין להבאת קרבן, ואם כן נמצא שלא ראה ראיות של זיבה גמורה המחייבתו קרבן נוסף בזמן טהרתו. \u0003ואי סלקא דעתך קסבר\u0004 \u0005[ואם עולה על דעתך\u0006 ש\u0005סבור]\u0006 \u0003ר' יוחנן לילה אינו מחוסר זמן,\u0004 אם כן \u0003אפילו\u0004 ראה \u0003שתים בלילה ואחת ביום מביא\u0004 עוד קרבן!","ודוחים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יוחנן\u0004 את ההלכה הזו אמר אותה \u0003לדברי האומר לילה מחוסר זמן,\u0004 אבל הוא עצמו שסבור שאף אם ראה את כל שלוש הראיות בלילה מביא קרבן נוסף\u0003.\u0004 ותוהים: אם הכוונה \u0003לדברי האומר\u0004 כך — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הוא שאינו מתחייב, ומה חידש ר' יוחנן? ומשיבים: יש בכך חידוש, כי \u0003שתים ביום ואחת בלילה אצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 לומר,","\u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 \u0003כאתקפתא\u0004 \u0005[כקושייתו]\u0006 של \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי\u0004 שהקשה במסכת כריתות על הלכה זו של ר' יוחנן באמרו שאין טעם לחלק בין זיבה אחת בלילה לשתי זיבות בלילה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003כ\u0004תירוצו של \u0003רב יוסף,\u0004 שראייה ראשונה של זוב נחשבת כקרי בלבד, ואין דנים בה בכל דיני זיבה.","שנינו במשנה: \u0003עבר הרגל ולא חג — אינו חייב באחריותו,\u0004 שאף אם הפרישו ונאבד אינו צריך להביא קרבן אחר תחתיו, אלא איבד את המצוה, \u0003ועל זה נאמר: \"מעות לא יוכל לתקון וחסרון לא יוכל להמנות\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 החכם \u0003בר הי הי להלל:\u0004 אין לשון הכתוב מתיישבת בדרשה זו, כי \u0003האי\u0004 \u0005[זה]\u0006 \u0003\"להימנות\"\u0004 אינו הביטוי המתאים, אלא \u0003\"להמלאות\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אלא\u0004 הכתוב מדבר על מי \u0003שמנוהו חביריו\u0004 להצטרף עימם \u0003לדבר מצוה והוא לא נמנה עמהם,\u0004 ומאחר שעשוהו חבריו לבדם, הרי שוב אינו יכול להימנות באותו מנין.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן\u0006 \u0005כך]:\u0006 \u0003\"מעות לא יוכל לתקן\" — זה שביטל קריאת שמע של שחרית או קריאת שמע של ערבית, או שביטל תפלה של שחרית, או תפלה של ערבית,\u0004 שהרי אינו יכול להשלים בזמן אחר, \u0003\"וחסרון לא יוכל להימנות\" — זה שנמנו חביריו לדבר מצוה והוא לא נמנה עמהן.\u0004","כיון שהוזכרו חילופי הדברים בין בר הי הי להלל מביאים עוד: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בר הי הי להלל, מאי דכתיב\u0004 \u0005[מה\u0006 פירושו של \u0005הכתוב]:\u0006 \u0003\"ושבתם וראיתם בין צדיק לרשע בין עבד אלהים לאשר לא עבדו\"\u0004 (מלאכי ג, יח), הרי לכאורה יש כאן כפילות, שהרי \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003צדיק — היינו\u0004 \u0005[זהו]\u0006 \u0003\"עובד אלהים\", היינו\u0004 \u0005[זהו]\u0006 \u0003\"רשע\" היינו\u0004 \u0005[זהו]\u0006 \u0003\"אשר לא עבדו\"! אמר ליה\u0004 \u0005[לו],\u0006 כך צריך להבין: זה ש\u0003\"עבדו\"\u0004 וזה ש\u0003\"לא עבדו\" תרוייהו צדיקי גמורי נינהו\u0004 \u0005[שניהם צדיקים גמורים הם]\u0006 ששניהם עובדים את ה', ובכל זאת יש הבדל ביניהם כי \u0003אינו דומה שונה פרקו מאה פעמים, לשונה פרקו מאה\u0004 פעמים \u0003ואחד.\u0004 שהעושה מצוה אחת יותר מאשר הורגל, הרי האיש הזה נקרא עובד ה' באמת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 בר הי הי: \u0003ומשום חד זימנא\u0004 \u0005[פעם אחת]\u0006 שלא שנה \u0003קרי ליה\u0004 \u0005[קורא לו]\u0006 הכתוב \u0003\"לא עבדו\"? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003צא ולמד משוק של חמרין\u0004 (מובילי חמורים) כיצד קובעים הם מחירים: עד מרחק \u0003עשרה פרסי\u0004 \u0005[פרסות] —\u0006 מקבלים החמרים \u0003ב\u0004שכרם \u0003זוזא\u0004 \u0005[זוז]\u0006 ואילו ממי שרוצה לשכור \u0003חד עשר פרסי\u0004 \u0005[אחת עשרה פרסות] —\u0006 \u0003בתרי זוזי\u0004 \u0005[בשני זוזים],\u0006 משמע שלתוספת מעבר לרגיל יש שינוי משמעותי בערך.","ועוד מסופר על בר הי הי, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אליהו\u0004 הנביא \u0003לבר הי הי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003לר' אלעזר: מאי דכתיב\u0004 \u0005[מה\u0006 פירוש \u0005הכתוב]:\u0006 \u0003\"הנה צרפתיך ולא בכסף בחרתיך בכור עני\"\u0004 (ישעיהו מח, י) — \u0003מלמד שחזר\u0004 (חיפש) \u0003הקדוש ברוך הוא על כל מדות טובות\u0004 כדי \u0003ליתן\u0004 מהן \u0003לישראל, ולא מצא\u0004 (\"בחרתיך\") \u0003אלא עניות\u0004 (\"כור עוני\") שהיא טובה להם מכולן, שבגללה הם נמנעים מעבירות, ומתמרקים עוונותיהם. \u0003אמר שמואל ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יוסף: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים\u0006 בפתגם עממי\u0005]:\u0006 \u0003יאה עניותא ליהודאי כי ברזא סומקא לסוסיא חיורא\u0004 \u0005[נאה עניות ליהודים כמו רסן אדום לסוס לבן].\u0006","שנינו במשנה: \u0003ר' שמעון בן מנסיא אומר: אי זה הוא \"מעות לא יוכל לתקון\"\u0004 — \u0003זה הבא על הערוה והוליד ממנה ממזר.\u0004 ומלשון המשנה מדייקים: \u0003הוליד — אין\u0004 \u0005[כן],\u0006 \u0003לא הוליד — לא,\u0004 אינו נקרא \"מעוות לא יוכל לתקון\"?","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003ר' שמעון בן מנסיא אומר: גונב\u0004 מ\u0003אדם — אפשר שיחזיר גנבו ויתקן, גוזל\u0004 מ\u0003אדם — אפשר שיחזיר גזלו ויתקן, אבל הבא על אשת איש\u0004 מרצונה \u0003ואסרה\u0004 על ידי כך \u0003לבעלה\u0004 לפי שאשת איש שנבעלה ברצון לאחר אסורה לבעלה — \u0003נטרד מן העולם והלך לו,\u0004 שאין לו תיקון ותשובה גמורה.","\u0003ר' שמעון בן יוחי אומר:\u0004 מי שבא לבדוק בהמה לקרבן שמא יש בה מום \u0003אין אומר \"בקרו גמל\"\u0004 או \u0003\"בקרו חזיר\",\u0004 שהרי הם פסולים לקרבן ולאכילה מעיקרם, \u0003אלא\u0004 אומרים \u0003\"בקרו טלה\".\u0004 וכן הלשון \"מעוות\" שייכת רק במי שהיה קודם ישר. \u0003ואי זה — זה תלמיד חכם שפירש מן התורה.\u0004","ובאותו ענין \u0003ר' יהודה בן לקיש אמר: כל תלמיד חכם שפירש מן התורה עליו הכתוב אומר: \"כצפור נודדת מן קנה כן איש נודד ממקומו\"\u0004 (משלי כז, ח), \u0003ואומר\u0004 כיוצא בו: \u0003\"מה מצאו אבותיכם בי עול כי רחקו מעלי\"\u0004 (ירמיה ב, ה), שמי שהיה קרוב לה' ונתרחק ממנו עונשו מרובה. על כל פנים יש סתירה לשיטת ר' שמעון בן מנסיא, שהרי בברייתא הוא אומר שגם הבא על הערוה בלא להוליד ממזר הוא מעוות שלא יוכל לתקון!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן\u0004 במשנתנו מדובר כגון שבא על \u0003אחותו פנויה,\u0004 שאמנם הביאה עצמה היא חטא כבד, אלא שאם לא הוליד ממזר יש לכך תיקון על ידי תשובה, \u0003כאן\u0004 כשעבר \u0003באשת איש\u0004 שהוא גורם נזק שאי אפשר לתקנו, משום שהיא נאסרת לבעלה. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ופרש: \u0003הא והא\u0004 \u0005[זו וזו]\u0006 מדברים \u0003באשת איש, ולא קשיא\u0004 \u0005[ואינו קשה]:\u0006 \u0003כאן\u0004 במשנתנו מדובר"],["\u0003באונס\u0004 שאמנם עבר האיש עבירה חמורה, אבל האשה אינה נאסרת לבעלה, \u0003כאן\u0004 כשעשתה גם היא \u0003ברצון,\u0004 ואז היא נאסרת על בעלה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003הא והא\u0004 \u0005[זו וזו]\u0006 \u0003באונס, ולא קשיא\u0004 \u0005[ואינו קשה]:\u0006 \u0003כאן\u0004 שאמרנו שעצם העבירה אין לה תקנה, זה \u0003באשת כהן,\u0004 שגם כשנבעלה באונס היא אסורה לבעלה, ונמצא שגרם נזק שאין לו תיקון, \u0003כאן באשת ישראל\u0004 שהאנוסה אינה אסורה לבעלה.","אגב המדובר בתלמיד חכם היוצא מדברי תורה מוסיפים מדרש על הכתוב: \u0003\"וליוצא ולבא אין שלום\u0004 מן הצר\u0003\"\u0004 (זכריה ח, י), \u0003אמר רב: כיון שיוצא אדם מדבר הלכה\u0004 (משנה) אפילו \u0003לדבר מקרא — שוב אין לו שלום,\u0004 שרבים מדברי המקרא סתומים ואין להורות מהם הלכה ללא פירוש המשנה לדברים הללו.","\u0003ושמואל אמר: זה הפורש מתלמוד למשנה\u0004 אין לו שלום, מפני שהתלמוד מבואר בטעמיו, ובמשנה רק פסקי הלכה שלא תמיד טעמם ברור. \u0003ור' יוחנן אמר: אפילו\u0004 היוצא \u0003מתלמוד לתלמוד\u0004 כגון מתלמוד ירושלמי לתלמוד בבלי, שיש לו קשיים בשיטת הלימוד החדשה ואיננו מוצא את מקומו.","אגב דיני חגיגה הנזכרים כאן מביאים רשימה של נושאים שונים בהלכה. \u0003היתר נדרים,\u0004 ההלכה שאפשר להתיר נדרים על ידי זה ששואלים את החכם והוא מתיר את הנדר — \u0003פורחין באויר ואין להם על מה שיסמכו,\u0004 כלומר, אין הדבר מפורש במקרא ויש לכך רק רמז קלוש, ואינו אלא מן הדינים שנמסרו לחכמים בתורה שבעל פה.","\u0003הלכות שבת,\u0004 הלכות \u0003חגיגות והמעילות — הרי הם כהררים\u0004 (הרים) גדולים \u0003התלוין בשערה\u0004 דקה, משום \u0003שהן מקרא מועט\u0004 לפי הערך \u0003והלכות מרובות.\u0004 אולם \u0003הדינין\u0004 (דיני ממונות) \u0003והעבודות\u0004 (דיני הקרבנות) \u0003הטהרות והטמאות ו\u0004ה\u0003עריות — יש להן על מה שיסמכו,\u0004 משום שיש להן בסיס נרחב הכתוב בתורה \u0003והן הן גופי תורה.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 היתרי נדרים \u0003יש להם על מה שיסמכו, שנאמר: \"כי יפליא\u0004 נדר\u0003\"\u0004 (ויקרא כז, ב), \u0003\"כי יפלא\u0004 לנדור נדר\u0003\"\u0004 (במדבר ו, ב) \u0003שתי פעמים,\u0004 וכפל לשון מיוחדת זו של \"הפלאה\", שמובנה פירוש, באה ללמד: \u0003אחת הפלאה לאיסור\u0004 שמפרש ומגלה דעתו לקבל הנדר, \u0003ואחת הפלאה להיתר\u0004 שמפרש לחכם ומוצא טעם מדוע לא יחול הנדר, הרי רמז להיתר נדרים.","\u0003ר' יהושע אומר: יש להם על מה שיסמכו, שנאמר: \"אשר נשבעתי באפי\"\u0004 (תהלים צה, יא), כלומר, \u0003באפי\u0004 (בכעסי) \u0003נשבעתי, וחזרתי בי.\u0004 והוא הבסיס העיקרי להיתר נדרים, כאשר הנודר אומר לחכם שהוא מתחרט על מה שנדר בעת כעסו.","\u0003ר' יצחק אומר: יש להם על מה שיסמכו, שנאמר: \"כל נדיב לבו\u0004 יביאה\u0003\"\u0004 (שמות לה, ה), שאדם מחוייב לקיים נדרו כל עוד הוא עומד ברצונו, אבל אם לבו איננו עוד עמו, שהוא מתחרט — יש לו היתר. \u0003חנניה בן אחי ר' יהושע אומר: יש להם על מה שיסמכו, שנאמר: \"נשבעתי ואקימה לשמר משפטי צדקך\"\u0004 (תהלים קיט, קו), ומכאן משמע שיש שבועה שאפשר שלא לקיים אותה, והיא שבועה שהותרה.","\u0003אמר רב יהודה אמר שמואל: אי הואי התם, אמרי להו\u0004 \u0005[אילו הייתי שם,\u0006 במושב חכמים אלה \u0005הייתי אומר להם]:\u0006 \u0003דידי עדיפא מדידכו\u0004 \u0005[\u0006הראייה \u0005שלי עדיפה משלכם],\u0006 ומהי — \u0003שנאמר: \"לא יחל דברו\"\u0004 (במדבר ל, ג), ונדייק מכאן: \u0003הוא\u0004 עצמו \u0003אינו מוחל\u0004 ומוותר על דברו, \u0003אבל אחרים,\u0004 החכמים, \u0003מוחלין לו,\u0004 וזהו ענין היתר נדרים. \u0003אמר רבא: לכולהו אית להו פירכא\u0004 \u0005[לכולם יש להם שבירה,\u0006 קושיה, סתירה\u0005],\u0006 \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004דברי \u0003שמואל דלית ליה פירכא\u0004 \u0005[שאין לו,\u0006 לדבריו, \u0005שבירה].\u0006","ומפרטים: \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003מ\u0004מה שאמר \u0003ר' אליעזר — דלמא\u0004 \u0005[שמא]\u0006 צריך להבין את כפל לשון \"הפלאה\" שבכתוב \u0003כ\u0004דברי \u0003ר' יהודה שאמר משום\u0004 (בשם) \u0003ר' טרפון. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר משום ר' טרפון:\u0004 אם אנשים התערבו על דבר שלא היה ברור להם, והתנו שאם לא יתקיימו דבריהם יהיו נזירים — \u0003לעולם אין אחד מהם נזיר,\u0004 משום \u0003שלא ניתנה נזירות אלא להפלאה.\u0004 שנזירות חלה רק כאשר ברור לנודר שהוא מחייב את עצמו, ולא כשעצם ההתחייבות מוטלת בספק, ו\"כי יפליא\" (במשמעות: יפריש, יבדיל) בא להדגיש נקודה זו.","וכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004דברי \u0003ר' יהושע — יש לומר דלמא הכי קאמר\u0004 \u0005[שמא כך אמר\u0006 הכתוב\u0005]:\u0006 \u0003באפי נשבעתי — ולא הדרנא בי\u0004 \u0005[ואינני חוזר בי]\u0006 למרות שהיה זה בשעת כעס. \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 \u0003מ\u0004דברי \u0003ר' יצחק\u0004 שלמד מלשון \"נדיב לבו\" — \u0003דלמא\u0004 \u0005[שמא]\u0006 בא הפסוק \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003שמואל\u0004 האחרים, ש\u0003אמר שמואל:\u0004 מי ש\u0003גמר בלבו\u0004 לאסור על עצמו דבר בנדר, אין די בכך ו\u0003צריך\u0004 בכל זאת \u0003שיוציא\u0004 הנדר \u0003בשפתיו\u0004 בדיבור, \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו\u0006 הכתוב\u0005]:\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לא הוציא בשפתיו,\u0004 כיון שנדב בליבו — נתחייב לקיים הנדר.","\u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004דברי \u0003חנניה בן אחי ר' יהושע — דלמא\u0004 \u0005[שמא]\u0006 יש לפרשם \u0003כרב גידל אמר רב.\u0004 ש\u0003אמר רב גידל אמר רב: מנין שנשבעין לקיים את המצוה\u0004 ואין אומרים שהיא שבועת שוא, שהרי הוא מחוייב בה בין כה וכה — \u0003שנאמר: \"נשבעתי ואקימה לשמור משפטי צדקך\",\u0004","\u0003אלא\u0004 רק ל\u0003שמואל לית ליה פירכא\u0004 \u0005[אין לו,\u0006 לראייתו, \u0005שבירה].\u0006 \u0003אמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב נחמן בר יצחק: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים\u0006 בפתגם מקובל\u0005]:\u0006 \u0003טבא חדא פלפלתא חריפתא ממלי צנא דקרי\u0004 \u0005[טוב פלפל חריף אחד ממלוא הסל דלעות],\u0006 שיש בו טעם יותר מבכולן.","נאמר במשנה ש\u0003הלכות שבת\u0004 הן כהררים התלוים בשערה. ותוהים: הלא עיקרי הלכות שבת \u0003מיכתב כתיבן\u0004 \u0005[כתובות הן],\u0006 שאיסור מלאכה ברור ומפורש בתורה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 המשנה אלא \u0003לכ\u0004 דברי \u0003ר' אבא,\u0004 ש\u0003אמר ר' אבא: החופר גומא בשבת ואין צריך אלא לעפרה\u0004 ולא לגומה עצמה — \u0003פטור עליה\u0004 ואינו מתחייב משום מלאכת החפירה, כיון שלא התכוון לעשיית מלאכה זו. ולחידוש זה וכיוצא בו רמזו כאן, שאף שנעשתה מלאכה גמורה בשבת — אין חייבים עליה.","לעצם הענין שואלים: הלכה זו שאמר ר' אבא \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי] —\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון,\u0004 ש\u0003אמר: מלאכה שאינה צריכה לגופה — פטור עליה,\u0004 שמלאכה שעושה אדם כאשר איננו מעוניין בתוצאתה של אותה מלאכה האסורה, וכוונתו לדבר אחר הנובע ממנה — פטור עליה, לפי שלא היתה זו מלאכה הנעשית מתוך מחשבה וכוונה מליאה.","ודוחים: אין הכרח לומר כך, אלא \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שסבור ר' אבא כ\u0003ר' יהודה\u0004 שלדעתו מלאכה שאינה צריכה לגופה חייב עליה, אבל \u0003התם\u0004 \u0005[שם]\u0006 בהלכה הכללית של ר' יהודה מדובר כאשר אדם עושה מלאכה שבה הוא \u0003מתקן,\u0004 אולם \u0003הכא\u0004 \u0005[כאן]\u0006 בחפירת הגומא \u0003מקלקל הוא\u0004 שהרי חפירת הגומה עצמה איננה מלאכת תיקון אלא קילקול האדמה בלבד, ובמלאכה בלתי שלימה כזו גם ר' יהודה מודה שפטור.","ולענייננו שואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 הרמז בדברי התורה להלכה זו, שכן מתוך שנוקטת המשנה בלשון \u0003\"כהררין התלויין בשערה\",\u0004 משמע שאינם מפורשים במקרא אלא ברמז בלבד."],["\u0003מלאכת מחשבת\u0004 בלבד \u0003אסרה תורה\u0004 ומלאכה שאין אדם חושב לעשותה אינה בכלל זה, \u0003ו\u0004אולם \u0003מלאכת מחשבת לא כתיבא\u0004 \u0005[איננה כתובה]\u0006 בתורה בין דיני שבת אלא במעשה המשכן, ואף על פי שיש קשר בין הדברים מכל מקום איננו מפורש.","שנינו במשנה כי \u0003חגיגות\u0004 גם הן כהררים התלויים בשערה. ושואלים: הלא \u0003מיכתב כתיבן\u0004 \u0005[כתובות\u0006 הן\u0005]!\u0006 ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003לכדאמר ליה\u0004 \u0005[לכמו\u0006 מה \u0005שאמר לו]\u0006 \u0003רב פפא לאביי: ממאי דהאי\u0004 \u0005[מניין שזה]\u0006 הכתוב \u0003\"וחגתם אתו חג לה'\"\u0004 (ויקרא כג, מא) יש לפרשו במשמעות \u0003זביחה,\u0004 ופירוש \"חג\" הוא קרבן החג? \u0003דלמא חוגו חגא קאמר רחמנא\u0004 \u0005[שמא חוגו חג אמרה התורה]\u0006 בלי קרבן!","וענה לו אביי: \u0003אלא מעתה,\u0004 מה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"\u0004שלח את עמי \u0003ויחגו לי במדבר\"\u0004 (שמות ה, א), \u0003הכי נמי דחוגו חגא\u0004 \u0005[כך גם כן שחוגו חג]\u0006 \u0003הוא\u0004 משמעות הכתוב? \u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר\u0006 ש\u0005כן\u0006 הוא \u0005גם כן]\u0006 שאכן הכוונה לחוג חג ולא לזביחה; \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויאמר משה גם אתה תתן בידנו זבחים ועלת\u0004 ועשינו לה' אלהינו\u0003\"\u0004 (שמות י, כה), הרי שהכוונה ודאי לזביחה!","ועדיין מקשים: \u0003דלמא הכי קאמר רחמנא\u0004 \u0005[שמא כך אמרה התורה]:\u0006 \u0003אכלו ושתו וחוגו חגא קמאי\u0004 \u0005[וחוגו חג לפני]?\u0006 ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[\u0006יכול \u0005לעלות על דעתך]\u0006 לומר כן, \u0003דכתיב\u0004 \u0005[\u0006משום \u0005שנאמר]:\u0006 \u0003\"ולא ילין חלב חגי עד בקר\"\u0004 (שמות כג, יח), \u0003ואי סלקא דעתך דחוגא\u0004 \u0005[ואם עולה על דעתך\u0006 לומר \u0005שחג]\u0006 ממש \u0003הוא,\u0004 וכי \u0003תרבא לחגא אית ליה\u0004 \u0005[חלב לחג יש]?!\u0006","ומקשים: \u0003ודלמא הכי קאמר רחמנא\u0004 \u0005[ושמא כך אמרה התורה]\u0006 \u0003חלב\u0004 של נדרים \u0003הבא בזמן חג לא ילין\u0004 ו\"חג\" אינו שם הקרבן אלא זמן המאורע?","ומשיבים: \u0003אלא מעתה,\u0004 נדייק: חלב \u0003הבא בזמן חג — הוא\u0004 ש\u0003לא ילין, הא\u0004 \u0005[הרי]\u0006 חלב של \u0003כל השנה כולה ילין?!\u0004 הלא בעולה \u0003\"\u0004על מוקדה על המזבח \u0003כל הלילה עד הבקר\"\u0004 (ויקרא ו, ב) \u0003כתיב\u0004 \u0005[נאמר]\u0006 ולא יותר מכן!","ואומרים: \u0003דלמא אי\u0004 \u0005[שמא אם]\u0006 \u0003מ\u0004הפסוק \u0003ההוא, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי הפסוק \u0003ההוא ל\u0004מצות \u0003עשה\u0004 הוא שבא, ולכן \u0003כתב רחמנא האי ללאו\u0004 \u0005[כתבה התורה\u0006 את \u0005זה\u0006 \"לא ילין\" \u0005ל\u0006מצות \u0005\"לא\u0006 תעשה\u0005\"]!\u0006","ומשיבים: \u0003ל\u0004ענין \u0003לאו\u0004 שיש בדבר בחג כבר \u0003כתב קרא אחרינא\u0004 \u0005[כתוב,\u0006 פסוק, \u0005אחר]\u0006 \u0003\"ולא ילין מן הבשר אשר תזבח בערב ביום הראשון לבקר\"\u0004 (דברים טז, ד). ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 בא הכתוב \"לא ילין\" כדי ללמד \u0003לעבור עליו בשני לאוין ועשה!\u0004","\u0003אלא\u0004 יש לדחות מה שאמרנו, ולומר בדרך אחרת: \u0003אתיא\u0004 \u0005[בא\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה \u0003\"מדבר\" \"מדבר\"; כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ויחגו לי במדבר\"\u0004 (שמות ב, א), \u0003וכתיב התם:\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"הזבחים ומנחה הגשתם לי במדבר\"\u0004 (עמוס ה, כה), \u0003מה להלן\u0004 הכוונה היא ל\u0003זבחים\u0004 של קרבנות — \u0003אף כאן\u0004 החג במדבר הוא הקרבת \u0003זבחים.\u0004","ושואלים: כיון שהבאנו גזירה שווה, הרי לימוד שלם הוא, \u0003ומאי\u0004 \u0005[ומה]\u0006 ענין של \u0003כהררין התלויין בשערה\u0004 יש כאן? ומשיבים: אין זו ראייה גמורה, כי \u0003דברי תורה מדברי קבלה\u0004 (דברי נבואה) \u0003לא ילפינן\u0004 \u0005[אין אנחנו למדים]\u0006 כרגיל, ואין זו ראייה שלימה.","שנינו במשנה ש\u0003מעילות\u0004 הן כהררים התלוים בשערה! ושואלים: הלא \u0003מיכתב כתיבן\u0004 \u0005[כתובות\u0006 הן\u0005]\u0006 בתורה (ויקרא ה, יד-טז)? \u0003אמר רמי בר חמא: לא נצרכא\u0004 \u0005[נצרכה]\u0006 אימרה זו של \"הררים התלויים בשערה\" \u0003אלא לכדתנן\u0004 \u0005[לכמו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003השליח שעשה שליחותו,\u0004 כגון ששלחו בעל הבית לקנות חפץ במעות של הקדש ועשה השליח כהוראת המשלח — \u0003בעל הבית מעל\u0004 וחייב קרבן בשל מעשה השליח, ואם \u0003לא עשה\u0004 השליח \u0003שליחותו\u0004 אלא שינה בה — ה\u0003שליח מעל\u0004 והוא חייב להביא קרבן כפרה.","ויש לשאול: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003עשה שליחותו אמאי\u0004 \u0005[מדוע]\u0006 \u0003מעל\u0004 בעל הבית? \u0003וכי זה חוטא וזה מתחייב?\u0004 ואם כן, \u0003היינו\u0004 \u0005[זה הוא]\u0006 הדבר בהלכות מעילה שאומרים שהן \u0003כהררין התלויין בשערה.\u0004","\u0003אמר רבא: ומאי קושיא\u0004 \u0005[ומה הקושיה\u0006 שבכך\u0005]?\u0006 \u0003דלמא שאני\u0004 \u0005[שמא שונה]\u0006 \u0003מעילה דילפא\u0004 \u0005[ש\u0006היא \u0005נלמדת]\u0006 בגזירה שווה של המילים \u0003\"חטא\" \"חטא\" מתרומה, מה התם\u0004 \u0005[מה שם]\u0006 בתרומה \u0003שלוחו של אדם כמותו\u0004 והשליח יכול להפריש תרומה עבור בעל התבואה \u0003אף כאן\u0004 במעילה \u0003שלוחו של אדם כמותו,\u0004 וכשעשה שליחותו הריהו מחייב אותו?","\u0003אלא אמר רבא: לא נצרכא\u0004 \u0005[נצרכה]\u0006 המשנה \u0003אלא לכדתניא:\u0004 \u0005[לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 אם לאחר ששלח בעל הבית את השליח להשתמש בדבר של קודש \u0003נזכר בעל הבית\u0004 שהיה זה חפץ מוקדש \u0003ולא נזכר שליח,\u0004 הרי גם כאשר עשה שליחותו — \u0003שליח מעל\u0004 ולא משלחו, שאין מעילה אלא בשוגג, ובעל הבית שוב אינו שוגג, אלא השליח בלבד שוגג הוא. ובמקרה זה \u0003שליח עניא מאי קא עביד\u0004 \u0005[השליח העני,\u0006 המסכן, \u0005מה עשה],\u0006 שהרי הוא התכוון רק לעשות שליחותו של בעל הבית, ומפני שבעל הבית נזכר מתחייב השליח בדבר? \u0003היינו\u0004 \u0005[זה הוא]\u0006 שאמרו שהלכות מעילה הן \u0003כהררין התלויין בשערה.\u0004","\u0003אמר רב אשי: מאי קושיא\u0004 \u0005[מה הקושי\u0006 שבכך\u0005].\u0006 \u0003דלמא מידי דהוה\u0004 \u0005[שמא כמו שהוא]\u0006 בהלכה הכללית של מעילה, שאם \u0003מוציא מעות הקדש לחולין\u0004 הרי מתחייב בקרבן על המעשה גם אם לא ידע כלל שהוא הקדש,","\u0003אלא אמר רב אשי: לא נצרכא\u0004 \u0005[נצרכה]\u0006 משנתנו \u0003אלא לכדתנן\u0004 \u0005[לכפי ששנינו\u0006 בענין זה במשנה\u0005]:\u0006 \u0003נטל\u0004 אדם \u0003אבן או קורה של הקדש — הרי זה לא מעל\u0004 בעצם הנטילה, אבל אם \u0003נתנה לחבירו,\u0004 הרי \u0003הוא\u0004 הנותן \u0003מעל, וחבירו לא מעל.\u0004 ויש לשאול: \u0003מכדי מישקל שקלה\u0004 \u0005[הלא לקח אותה],\u0006 ואם כן \u0003מה לי\u0004 אם מחזיק בה \u0003הוא ומה לי\u0004 אם מחזיק בה \u0003חבירו? היינו\u0004 \u0005[זה הוא]\u0006 שאמרנו שהלכות אלה הן \u0003כהררין התלויין בשערה.\u0004","ומקשים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושי\u0006 שבכך\u0005]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 יש לפרש את הדבר \u0003כ\u0004דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: הכא\u0004 \u0005[כאן]\u0006 במשנה זו בענין נטילת האבן אין מדובר בסתם אדם הנוטל לעצמו אבן של הקדש,"],["אלא \u0003בגזבר\u0004 של המקדש \u0003המסורות לו אבני בנין\u0004 של הקדש לשמירה \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003דכל היכא דמנחה\u0004 \u0005[שבכל מקום שהיא,\u0006 האבן, \u0005מונחת] —\u0006 \u0003ברשותא דידיה מנחה\u0004 \u0005[ברשותו שלו\u0006 היא \u0005מונחת]\u0006 ולכן בעצם לקיחת האבן או הקורה לא נתחייב כלל, שהרי הוא רשאי לטלטלה, אבל אין לו רשות למסור את האבן לאחר, ולכן כשמסרה לחבירו עבר עבירה של מעילה. ואם כן, אף הלכה זו יש לה בסיס.","\u0003אלא מסיפא\u0004 \u0005[מסופה]\u0006 של אותה משנה: \u0003בנאה\u0004 לאותה אבן \u0003בתוך ביתו — הרי זה לא מעל, עד שידור תחתיה\u0004 מגורים \u0003בשוה פרוטה.\u0004 ויש לשאול: \u0003מכדי שנויי שנייה\u0004 \u0005[הלא שינה\u0006 את האבן\u0005]\u0006 על ידי שבנה אותה בתוך ביתו, ואם כן \u0003מה לי דר ומה לי לא דר,\u0004 ואולי \u0003היינו\u0004 \u0005[זוהי]\u0006 ההלכה המוגדרת \u0003\"כהררין התלויין בשערה\"?\u0004","ודוחים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושי\u0006 שבכך\u0005]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 זה נאמר \u0003לכ\u0004 דברי \u0003רב.\u0004 ש\u0003אמר רב:\u0004 במשנה זו מדובר \u0003כגון שהניחה על פי ארובה\u0004 ולא עשה עדיין כל שינוי בגוף האבן על ידי כך, ולכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003דר ביה\u0004 \u0005[בו],\u0006 בבית — \u0003אין\u0004 \u0005[כן]\u0006 מעל, כיון שנהנה ממנה, ואם \u0003לא דר ביה\u0004 \u0005[בו] —\u0006 \u0003לא\u0004 מעל.","\u0003אלא, לעולם\u0004 תפרש \u0003כ\u0004דברי \u0003רבא,\u0004 שהחידוש בהלכה זו הוא במקרה שכאשר נזכר בעל הבית מעל השליח. \u0003ודקא קשיא לך\u0004 \u0005[ו\u0006מה \u0005שהיה קשה לך]:\u0006 \u0003מידי דהוה\u0004 \u0005[הלא הוא\u0006 בדומה\u0005]\u0006 למקרה של \u0003מוציא מעות הקדש לחולין,\u0004 אין הדברים זהים, כי \u0003התם מידע ידע דאיכא זוזי\u0004 \u0005[שם\u0006 האיש \u0005יודע שיש\u0006 לו גם \u0005זוזים,\u0006 כספים\u0005]\u0006 של \u0003הקדש\u0004 ואם כן \u0003איבעי ליה לעיוני\u0004 \u0005[היה לו לעיין]\u0006 ולבדוק אם הכסף הזה כסף הקדש הוא, \u0003הכא מי ידע\u0004 \u0005[כאן האם ידע]\u0006 השליח שיש פה חשש כספי הקדש! ו\u0003היינו כהררין התלויין בשערה\u0004 האמורים במשנה.","עתה חוזרים אנו לנאמר במשנה ביחס לדברים שהם \"כהררין התלויין בשערה\", שכן הם \u0003מקרא מועט והלכות מרובות.\u0004 ובענין זה \u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005],\u0006 ש\u0003נגעים,\u0004 דיני נגעי הצרעת, \u0003ואהלות,\u0004 דיני טומאת אוהל המת, הם \u0003מקרא מועט והלכות מרובות.\u0004 ותוהים: וכי \u0003נגעים מקרא מועט\u0004 הוא? הלא \u0003נגעים מקרא מרובה הוא! אמר רב פפא: הכי קאמר\u0004 \u0005[כך אמר]\u0006 במשנה, כך יש לתקן את הגירסה: \u0003נגעים\u0004 יש בהם \u0003מקרא מרובה והלכות מועטות\u0004 יחסית, \u0003אהלות — מקרא מועט והלכות מרובות.\u0004","ושואלים: \u0003ומאי נפקא מינה\u0004 \u0005[ומה יוצא מזה],\u0006 מה ההבדל אם כך הוא או כך? ומשיבים: \u0003אי מסתפקא לך מילתא\u0004 \u0005[אם מסופק לך דבר]\u0006 \u0003ב\u0004הלכות \u0003נגעים — עיין בקראי\u0004 \u0005[במקראות],\u0006 משום שהמקרא מרובה שם, \u0003ואי מסתפקא לך מילתא\u0004 \u0005[ואם מסופק לך דבר]\u0006 \u0003ב\u0004הלכות \u0003אהלות — עיין במתניתין\u0004 \u0005[במשנתנו]\u0006 משום שבמקרא אין ההלכה מפורשת דיה.","שנינו במשנה ש\u0003דינין\u0004 הם מהדברים שיש להם על מה שיסמכו במקרא. ושואלים: הלא \u0003מיכתב כתיבן\u0004 \u0005[\u0006כל הדינים \u0005כתובים\u0006 הם\u0005]\u0006 ומה לשון \"יש להם על מה שיסמוכו\"? שאם הדבר מפורש אין לומר רק לשון סמיכה בלבד! ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא לכ\u0004 דברי","\u0003רבי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 מה שנאמר \u0003\"\u0004ואם אסון יהיה ונתתה \u0003נפש תחת נפש\"\u0004 (שמות כא, כג), כוונתו תשלום \u0003ממון. אתה אומר ממון, או אינו אלא נפש\u0004 תחת נפש \u0003ממש?\u0004 אפשר ללמוד בגזירה שווה: \u0003נאמרה נתינה למטה\u0004 (\"ונתתה נפש תחת נפש\". שמות כא, כג) \u0003ונאמרה נתינה למעלה\u0004 (\"ונתן בפלילים\". שמות כא, כב) \u0003מה להלן\u0004 \"ונתן בפלילים\" הכוונה היא ודאי ל\u0003ממון, אף כאן\u0004 הכוונה היא ל\u0003ממון.\u0004 ודבר זה אינו מפורש בכתוב, אבל נסמך עליו.","שנינו במשנה כי \u0003עבודות\u0004 אף הן יש להן על מה שיסמוכו. ושואלים: הלא \u0003מיכתב כתיבן\u0004 \u0005[כתובות\u0006 הן\u0005]\u0006 ואם הדבר מפורש אין לומר רק לשון סמיכה בלבד! ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא ל\u0004ענין העבודה של \u0003הולכת הדם. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"והקריבו\u0004 בני אהרן הכהנים את הדם\u0003\"\u0004 (ויקרא א, ה), \u0003זו קבלת הדם\u0004 שהיא קודמת להולכת הדם למזבח.","\u0003ואפקה רחמנא\u0004 \u0005[והוציאה אותה התורה]\u0006 \u0003בלשון הולכה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והקריב הכהן את הכל והקטיר המזבחה\"\u0004 (ויקרא א, יג), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 לשון \"הקרבה\" זו אינה הקרבה על המזבח אלא \u0003זו\u0004 היא \u0003הולכת אברים לכבש\u0004 שליד המזבח, שמשם מעלים אותם למזבח עצמו ואף הקרבה הכתובה אצל הדם פירושה הולכה.","ומדוע יש חילוף לשונות בין עבודת ההולכה ועבודת הקבלה — \u0003למימרא\u0004 \u0005[לומר]\u0006 ש\u0003הולכה לא תפקה\u0004 \u0005[תוציא אותה]\u0006 \u0003מכלל\u0004 עבודת ה\u0003קבלה,\u0004 וכל הדינים הנוהגים בקבלה (הנעשית על ידי הכהן, ובימין, ועוד) כולם נוהגים גם בהולכה.","שנינו במשנה כי \u0003טהרות\u0004 יש להן על מה שיסמוכו. ושואלים: הלא \u0003מיכתב כתיבן\u0004 \u0005[כתובות\u0006 הן\u0005]\u0006 במפורש! ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא לשיעור מקוה דלא כתיבא\u0004 \u0005[שאיננו כתוב]\u0006 בתורה במפורש, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"ורחץ את בשרו במים\"\u0004 (ויקרא יד, ט), ולשון \"במים\" משמע במים הידועים — \u0003במי\u0004 ה\u0003מקוה.\u0004 ונאמר: \u0003\"\u0004ורחץ במים \u0003את כל בשרו\"\u0004 (ויקרא טו, טז), משמע שצריכים להיות \u0003מים שכל גופו עולה\u0004 (נכנס) \u0003בהן, וכמה הן\u0004 מים אלה — \u0003אמה על אמה ברום שלש אמות. ושיערו חכמים\u0004 לפי זה שנפח \u0003מי מקוה\u0004 הוא \u0003ארבעים סאה.\u0004","שנינו במשנה כי אף \u0003טמאות\u0004 יש להן על מי שיסמוכו. ושואלים: הלא \u0003מיכתב כתיבן\u0004 \u0005[כתובות\u0006 הן\u0005]\u0006 ואינם צריכות סמיכה! ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא ל\u0004למדנו על \u0003כעדשה מן השרץ\u0004 שהיא השיעור המצומצם לטומאת שרץ, \u0003דלא כתיבא\u0004 \u0005[שאינה כתובה].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר בשרצים: \"כל הנוגע \u0003בהם\u0004 במותם יטמא\" (ויקרא יא, לא),","\u0003יכול בכולן\u0004 שרק שרץ שלם מטמא, \u0003תלמוד לומר:\u0004 \"וכל אשר יפול עליו \u0003מהם\u0004 במותם יטמא\" (ויקרא יא, לב), \"מהם\" משמע — אפילו חלק מהם, אולם אם מהם, \u0003יכול\u0004 אפילו \u0003במקצתן\u0004 בכל שהוא — \u0003תלמוד לומר: \"בהם\"\u0004 שכוונתו בהם, בשלימותם.","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 אתה מיישב את הסתירה? \u0003עד שיגיע\u0004 (שיגע) \u0003במקצתו שהוא ככולו.\u0004 כלומר, בשיעור חשוב. ו\u0003שיערו חכמים\u0004 שיעור זה \u0003בכעדשה, שכן חומט\u0004 שהוא הקטן בין השרצים הללו \u0003תחלתו\u0004 (תחילת בריאתו) הוא \u0003בכ\u0004 גודל \u0003עדשה. ר' יוסי בר' יהודה אומר:\u0004 השיעור לענין זה הוא \u0003כזנב הלטאה,\u0004 שהוא מקצתו הנחשב ככולו. שהוא חלק מן הלטאה, ומפרכס אף לאחר שנקטע, ומתוך שיש לו חיות מסויימת בפני עצמו שייך להגדירו כ\"מקצתו שהוא ככולו\".","שנינו במשנה כי \u0003עריות\u0004 יש להן על מה שיסמוכו. ושואלים: הלא \u0003מיכתב כתיבן\u0004 \u0005[כתובות\u0006 הן\u0005]\u0006 במפורש! ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006"],["אלא \u0003לבתו מאנוסתו\u0004 שאסורה עליו, אף שאיננה בת אשתו (שהרי לא נשא את אמה) \u0003דלא כתיבא\u0004 \u0005[שאיננה כתובה]\u0006 במפורש בתורה. ש\u0003אמר רבא: אמר לי ר' יצחק בר אבדימי: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה \u0003\"הנה\" \"הנה\",\u0004 שנאמר: \"ערות אשה ובתה... לא תקח... שארה הנה זימה היא\" (ויקרא יח, יז), ונאמר: \"ערות בת בנך או בת בתך לא תגלה ערותן כי ערותך הנה\" (ויקרא יח, י), וכשם שעם האיסור לשאת אשה ובתה, נאסרו הן הבת והן בת הבת, כך לענין הפסוק השני האוסר בת בתו בכל מקרה (אף מאנוסתו) — אף בתו אסורה. \u0003ואתיא\u0004 \u0005[ובא,\u0006 נלמד\u0005]\u0006 לענין העונש על עבירה זו \u0003\"זימה\" \"זימה\",\u0004 שנאמר לענין אשה ובתה: \"זימה היא\", ונאמר: \"ואיש אשר יקח את אשה ואת אמה זימה היא באש ישרפו אותו ואתהן\" (ויקרא כ, יד).","","","שנינו במשנה: \u0003הן הן גופי תורה.\u0004 ותוהים: \u0003הני\u0004 \u0005[אלה]\u0006 — \u0003אין\u0004 \u0005[כן]\u0006 בכלל גופי תורה, \u0003הנך\u0004 \u0005[\u0006ודברי תורה \u0005האחרים]\u0006 \u0003לא,\u0004 אינם גופי תורה? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 בנוסח זה: \u0003הן והן גופי תורה,\u0004 בין אלה שנתפרשו בכתוב ובין אלה שלא נתפרשו — כולם גופי תורה.","","\u0003אין דורשין בעריות בשלשה\u0004 שהחכם הדורש בדיני עריות החמורים לא יעשה זאת בפני קהל, אלא בפני פחות משני תלמידים, שהוא והם ביחד שלושה, \u0003ולא\u0004 דורשים \u0003במעשה בראשית\u0004 ובסודות הבריאה \u0003בשנים,\u0004 הוא ותלמיד, \u0003ולא\u0004 דורשים \u0003ב\u0004מעשה \u0003מרכבה\u0004 שהם ענייני הסוד הקשורים בדרך הנהגתו של העולם \u0003ביחיד, אלא אם כן היה\u0004 אותו יחיד \u0003חכם ומבין מדעתו\u0004 את רובם של דברים.","ובאותו נושא: \u0003כל המסתכל בארבעה דברים רתוי\u0004 (ראוי) \u0003לו כאילו לא בא לעולם;\u0004 כל המתבונן ב\u0003מה\u0004 שהוא \u0003למעלה\u0004 מן הרקיע מעל ראשי החיות, \u0003מה למטה\u0004 מהן, \u0003מה לפנים\u0004 מה היה קודם שנברא העולם, \u0003ומה לאחור\u0004 מה יהיה אחר שיכלה העולם (תוספות). \u0003וכל שלא חס על כבוד קונו\u0004 ושואל ועוסק בדברים שאין רשאים לעסוק בהם \u0003רתוי\u0004 (ראוי) \u0003לו שלא בא לעולם.\u0004","ושואלים: \u0003אמרת\u0004 (שנית) \u0003ברישא\u0004 \u0005[בתחילת\u0006 המשנה\u0005]:\u0006 \u0003\"ולא במרכבה ביחיד\"\u0004 משמע שאין דורשים כלל במעשה מרכבה אפילו ביחידות, \u0003והדר\u0004 \u0005[וחזרת]\u0006 ו\u0003אמרת: אלא אם כן היה חכם ומבין מדעתו,\u0004 משמע שיחיד בכל זאת לומד מעשה מרכבה!","ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין: \u0003אין דורשין בעריות לשלשה\u0004 תלמידים, \u0003ולא במעשה בראשית לשנים, ולא\u0004 מלמדים \u0003במרכבה ליחיד אלא אם כן היה\u0004 התלמיד \u0003חכם ומבין מדעתו.\u0004 בהסברת פרטי הדברים, שנינו: \u0003אין דורשין בעריות בשלשה.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהוא \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"איש איש אל כל שאר בשרו\u0004 לא תקרבו לגלות ערוה\u0003\"\u0004 (ויקרא יח, ו), ונאמר כי יש כאן רמז למספר התלמידים. כיצד — \u0003\"איש איש\" — תרי\u0004 \u0005[שנים],\u0006 \u0003\"שאר בשרו\" — חד\u0004 \u0005[אחד],\u0006 \u0003ואמר רחמנא\u0004 \u0005[ואמרה התורה]:\u0006 \u0003\"לא תקרבו לגלות ערוה\",\u0004 שאם מצויים שלושה אנשים שוב אין דורשים (\"לא תקרבו לגלות\") בדיני עריות.","","ושואלים: \u0003אלא מעתה\u0004 לפי אותה שיטה, מה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"איש איש כי יקלל אלהיו\"\u0004 (ויקרא כד, טו), או \u0003\"איש איש אשר יתן מזרעו למלך\"\u0004 (ויקרא כ, ב), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 שאסור לדרוש אותם בפני שנים?","ומשיבים: \u0003אלא הנהו\u0004 \u0005[אותם]\u0006 לשונות כפל של \"איש איש\" \u0003מיבעי ליה\u0004 \u0005[צריך לו,\u0006 לתנא\u0005]\u0006 כדי \u0003לרבות את הגוים, שמוזהרין\u0004 גם \u0003על ברכת\u0004 (כלומר, קללת) \u0003השם, ו\u0004גם \u0003על עבודה זרה כישראל.\u0004","אולם \u0003האי\u0004 \u0005[\u0006ריבוי \u0005זה]\u0006 \"איש איש\" בדיני עריות \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מיבעי ליה\u0004 \u0005[צריך לו]\u0006 \u0003לרבות את הגוים שמוזהרין על העריות כישראל.\u0004","\u0003אלא\u0004 יש לדחות מה שאמרנו קודם, ולומר שיש רמז לאיסור דרשה בפני שלושה \u0003מדכתיב\u0004 \u0005[מ\u0006מה \u0005שנאמר]\u0006 בעריות: \u0003\"ושמרתם את משמרתי\"\u0004 (ויקרא יח, ל), ונפרש: \u0003\"ושמרתם\"\u0004 הרי כאן \u0003תרי\u0004 \u0005[שנים],\u0006 שמיעוט רבים שנים, \u0003\"משמרתי\" — חד\u0004 \u0005[אחד],\u0006 \u0003ואמר רחמנא\u0004 \u0005[ואמרה התורה]\u0006 בסופו של פסוק זה: \u0003\"לבלתי עשות מחקות התועבת\"\u0004 (ויקרא יח, ל), ומכאן נלמד שאין דורשים בשלושה.","ושואלים: \u0003אלא מעתה\u0004 מה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושמרתם את השבת\"\u0004 (שמות לא, יד), או \u0003\"ושמרתם את המצות\"\u0004 (שמות יב, יז), או \u0003\"ושמרתם את משמרת הקדש\"\u0004 (במדבר יח, ה), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שאין לומדים אותם בשלושה?","\u0003אלא אמר רב אשי:\u0004 יש לדחות רמזים אלה, ולהסביר \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003אין דורשין בעריות בשלשה — אין דורשין בסתרי עריות בשלשה.\u0004 שכל אותם דיני עריות שאינם מפורשים בתורה, ואינם נלמדים אלא מדרשות הכתובים או מהשוואתם — אין דורשים אותם בשלושה. \u0003מאי טעמא\u0004 \u0005[מה הטעם] —\u0006 אין זה מפני רמז במקרא, אלא \u0003סברא הוא.\u0004 וזהו הטעם: \u0003בי תרי כי יתבי קמי רבייהו\u0004 \u0005[שנים שיושבים לפני רבם],\u0006 \u0003חד שקיל וטרי בהדי רביה, ואידך מצלי אודניה לגמרא\u0004 \u0005[אחד\u0006 מהם \u0005נושא ונותן עם רבו\u0006 בהלכה, \u0005והאחר,\u0006 השני, \u0005מטה אוזנו לתלמוד]\u0006 שהוא שומע. אבל אם יש \u0003תלתא\u0004 \u0005[שלושה\u0006 תלמידים\u0005],\u0006 הרי \u0003חד שקיל וטרי בהדי רביה\u0004 \u0005[אחד\u0006 מהם \u0005נושא ונותן עם רבו]\u0006 \u0003והנך תרי שקלו וטרו בהדי הדדי ולא ידעי מאי קאמר רבייהו\u0004 \u0005[ואותם השניים\u0006 האחרים \u0005נושאים ונותנים זה עם זה ואינם יודעים מה אמר רבם]\u0006 \u0003ואתו למישרי איסורא\u0004 \u0005[ויבואו להתיר איסור]\u0006 \u0003בעריות,\u0004 שכן לא הקשיבו לדברי רבם, ומסברתם יבואו להתיר.","","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003כל התורה נמי\u0004 \u0005[גם כן]\u0006 לא ילמדו אלא לשניים, שהרי מפני אותו טעם יכולים לבוא בכל מקרה לידי טעות!","ומשיבים: דין \u0003עריות שאני\u0004 \u0005[שונה]\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003גזל ועריות נפשו\u0004 של אדם \u0003מחמדתן ומתאוה להם,\u0004 ולכן יש לחשוש שאדם שלא למד הלכותיהם כראוי מפי רבו ימצא היתר לעצמו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003גזל נמי\u0004 \u0005[גם כן]\u0006 לא ידרוש אלא בשנים מטעם זה? ומשיבים: יש הבדל בין התאווה לגזל לזו של עריות; \u0003עריות — בין\u0004 כשהן \u0003בפניו בין שלא בפניו נפיש יצריה\u0004 \u0005[מרובה יצרו]\u0006 לכך, ויש לחשוש יותר. \u0003גזל, בפניו,\u0004 כשהדבר עומד בפניו כפיתוי — \u0003נפיש יצריה\u0004 \u0005[מרובה יצרו],\u0006 \u0003שלא בפניו — לא נפיש יצריה\u0004 \u0005[אין יצרו מרובה],\u0006 ולכן אין חוששים כל כך.","שנינו במשנה: \u0003\"ולא במעשה בראשית בשנים\".\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 ומסבירים, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 נאמר: \u0003\"כי שאל נא לימים ראשנים\u0004 אשר היו לפניך\u0003\"\u0004 (דברים ד, לב), וכיון שנאמר הדבר בלשון יחיד, הרי זה ללמדנו כי \u0003יחיד שואל\u0004 בענין מעשה בראשית (\"לימים ראשונים\") \u0003ואין שנים שואלין,\u0004 ומכאן שהרב מלמד לתלמיד אחד בלבד.","\u0003יכול ישאל אדם\u0004 על מה שהיה \u0003קודם שנברא העולם — תלמוד לומר\u0004 מה שנאמר בהמשך: \u0003\"למן היום אשר ברא אלהים אדם על הארץ\"\u0004 (דברים ד, לב), ולא קודם לכן.","\u0003יכול לא ישאל אדם\u0004 על מה שהיה \u0003מששת ימי בראשית — תלמוד לומר: \"\u0004שאל נא \u0003לימים ראשנים אשר היו לפניך\"\u0004 (דברים ד, לב), כלומר, גם לימים שהיו לפני היות האדם.","\u0003יכול ישאל אדם מה למעלה ומה למטה מה לפנים ומה לאחור\u0004 מן העולם — \u0003תלמוד לומר: \"ולמקצה השמים ועד קצה השמים\"\u0004 (דברים ד, לב), כלומר, \u0003מלמקצה השמים ועד קצה השמים\u0004 בתוך תחומו של העולם — \u0003אתה שואל, ואין אתה שואל מה למעלה מה למטה, מה לפנים מה לאחור.\u0004"],["\u0003השתא דנפקא ליה\u0004 \u0005[עכשיו שיצא לו,\u0006 שלמד\u0005]\u0006 דבר זה \u0003מ\u0004ממה שנאמר \u0003\"למקצה השמים ועד קצה השמים\",\u0004 אם כן הכתוב \u0003\"למן היום אשר ברא אלהים אדם על הארץ\" למה לי?\u0004","ומשיבים: כתוב זה בא ללמד ענין אחר, \u0003כ\u0004פי שאמר \u0003ר' אלעזר.\u0004 ש\u0003אמר ר' אלעזר: אדם הראשון\u0004 היתה קומתו \u0003מן הארץ עד לרקיע, שנאמר: \"למן היום אשר ברא אלהים אדם על הארץ\u0004 ולמקצה השמים\u0003\"\u0004 (דברים ד, לב). \u0003וכיון שסרח\u0004 (חטא) — \u0003הניח הקדוש ברוך הוא ידיו עליו — ומיעטו, שנאמר: \"אחור וקדם צרתני ותשת עלי כפכה\"\u0004 (תהלים קלט, ה).","\u0003אמר רב יהודה אמר רב: אדם הראשון,\u0004 גודלו \u0003מסוף העולם ועד סופו היה, שנאמר: \"למן היום אשר ברא אלהים אדם על הארץ ולמקצה השמים ועד קצה השמים\",\u0004 כלומר, מקצה העולם עד קצהו, \u0003כיון שסרח — הניח הקדוש ברוך הוא ידו עליו ומיעטו, שנאמר \"ותשת עלי כפכה\".\u0004","ושואלים: \u0003אי הכי, קשו קראי אהדדי\u0004 \u0005[אם כך, קשים המקראות זה על זה],\u0006 באחד נאמר שקומתו עד השמים, ובשני נאמר עד קצה הארץ! ומשיבים: \u0003אידי ואידי חד שיעורא\u0004 \u0005[זה וזה שיעור אחד]\u0006 \u0003הוא.\u0004","\u0003ועוד בענייני הבריאה, אמר רב יהודה אמר רב: עשרה דברים נבראו ביום ראשון\u0004 של בריאת העולם, \u0003ואלו הן: שמים וארץ, תהו ובהו, אור וחשך, רוח ומים, מדת יום ומדת לילה\u0004 (שיעור אורך היום והלילה).","וראיות לאלה מן המקרא: \u0003שמים וארץ — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בראשית ברא אלהים את השמים ואת הארץ\"\u0004 (בראשית א, א), \u0003תהו ובהו — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והארץ היתה תהו ובהו\"\u0004 (בראשית א, ב), \u0003אור וחשך, חשך — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וחשך על פני תהום\"\u0004 (בראשית א, ב), \u0003אור — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר אלהים יהי אור\"\u0004 (בראשית א, ג), \u0003רוח ומים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ורוח אלהים מרחפת על פני המים\"\u0004 (בראשית א, ב), \u0003מדת יום ומדת לילה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי ערב ויהי בקר יום אחד\"\u0004 (בראשית א, ה).","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003תהו\u0004 — הוא \u0003קו ירוק שמקיף את כל העולם כולו, שממנו יצא חשך, שנאמר: \"ישת חשך סתרו סביבותיו\"\u0004 (תהלים יח, יב), הרי שקו של חושך מקיף את העולם. \u0003בהו — אלו אבנים המפולמות\u0004 (הלחות) \u0003המשוקעות בתהום, שמהן יוצאין מים, שנאמר: \"ונטה עליה קו תהו ואבני בהו\"\u0004 (ישעיהו לד, יא), ומכאן שתוהו הוא קו, ובוהו הוא אבנים.","ושואלים: \u0003ואור\u0004 האם \u0003ביום ראשון איברי\u0004 \u0005[נברא]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויתן אתם אלהים ברקיע השמים\"\u0004 (בראשית א, יז), \u0003וכתיב \"ויהי ערב ויהי בקר יום רביעי\"\u0004 (בראשית א, יט), הרי שנברא האור ביום הרביעי לבריאה!","ומשיבים: יש לפרש \u0003כ\u0004דברי \u0003ר' אלעזר.\u0004 ש\u0003אמר ר' אלעזר: אור שברא הקדוש ברוך הוא ביום ראשון\u0004 לא היה אור החמה אלא אור מסוג אחר, והיה \u0003אדם צופה בו מסוף העולם ועד סופו. כיון שנסתכל הקדוש ברוך הוא בדור המבול ובדור הפלגה וראה שמעשיהם מקולקלים\u0004 ועלולים להשתמש באור זה לרעה — \u0003עמד וגנזו מהן, שנאמר: \"וימנע מרשעים אורם\"\u0004 (איוב לח, טו).","\u0003ולמי גנזו — לצדיקים לעתיד לבא, שנאמר: \"וירא אלהים את האור כי טוב\"\u0004 (בראשית א, ד), \u0003ואין טוב אלא צדיק, שנאמר: \"אמרו צדיק כי טוב\u0004 כי פרי מעלליהם יאכלו\u0003\"\u0004 (ישעיהו ג, י).","ו\u0003כיון שראה\u0004 הקדוש ברוך הוא את ה\u0003אור שגנזו לצדיקים — שמח, שנאמר: \"אור צדיקים ישמח\"\u0004 (משלי יג, ט).","ומעירים: \u0003כתנאי\u0004 \u0005[כ\u0006דברי \u0005תנאים]\u0006 שחלקו בנושא זה, ששנינו: \u0003אור שברא הקדוש ברוך הוא ביום ראשון אדם צופה ומביט בו מסוף העולם ועד סופו,\u0004 אלו \u0003דברי ר' יעקב. וחכמים אומרים:\u0004 אור זה \u0003הן הן מאורות שנבראו ביום ראשון, ולא נתלו\u0004 במקומם הקבוע ברקיע \u0003עד יום רביעי.\u0004","\u0003אמר רב זוטרא בר טוביא אמר רב: בעשרה דברים נברא העולם: בחכמה, ובתבונה, ובדעת, ובכח, ובגערה, ובגבורה, בצדק, ובמשפט, בחסד, וברחמים.\u0004","וראיה לדבר: \u0003בחכמה ובתבונה\u0004 נברא — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ה' בחכמה יסד ארץ כונן שמים בתבונה\"\u0004 (משלי ג, יט). \u0003בדעת — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בדעתו תהומות נבקעו\"\u0004 (משלי ג, כ). \u0003בכח וגבורה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מכין הרים בכחו נאזר בגבורה\"\u0004 (תהלים סה, ז). \u0003בגערה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"עמודי שמים ירופפו ויתמהו מגערתו\"\u0004 (איוב כו, יא). \u0003בצדק ומשפט — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"צדק ומשפט מכון כסאך\"\u0004 (תהלים פט, טו). \u0003בחסד ורחמים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זכר רחמיך ה' וחסדיך כי מעולם המה\"\u0004 (תהלים כה, ו).","\u0003ו\u0004עוד, \u0003אמר רב יהודה אמר רב\u0004 באותם נושאים: \u0003בשעה שברא הקדוש ברוך הוא את העולם, היה מרחיב והולך כשתי פקעיות של שתי,\u0004 שכאשר הן מתגלגלות החוט היוצא מהן גדל והולך, \u0003עד שגער בו הקדוש ברוך הוא והעמידו, שנאמר: \"עמודי שמים ירופפו ויתמהו מגערתו\"\u0004 (איוב כו, יא) \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"אני אל שדי\"\u0004 (בראשית יז, א) — \u0003אני הוא שאמרתי לעולם די,\u0004 שלא ילך ויגדל. וכעין זה \u0003אמר ריש לקיש: בשעה שברא הקדוש ברוך הוא את הים היה מרחיב והולך, עד שגער בו הקדוש ברוך הוא, ויבשו, שנאמר: \"גוער בים ויבשהו וכל הנהרות החריב\"\u0004 (נחום א, ד).","בסוד הבריאה נחלקו בית שמאי ובית הלל, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003בית שמאי אומרים: שמים נבראו תחלה ואחר כך נבראת הארץ, שנאמר: \"בראשית ברא אלהים את השמים ואת הארץ\"\u0004 (בראשית א, א), משמע שמים קודם לארץ. \u0003ובית הלל אומרים: ארץ נבראת תחלה ואחר כך שמים, שנאמר: \"ביום עשות ה' אלהים ארץ ושמים\"\u0004 (בראשית ב, ד).","\u0003אמר להם בית הלל לבית שמאי: לדבריכם, אדם בונה עלייה\u0004 (קומה שניה) \u0003ואחר כך בונה בית?! ש\u0004כן \u0003נאמר: \"הבונה בשמים מעלותיו ואגדתו על ארץ יסדה\"\u0004 (עמוס ט, ו), שקודם נבראה הארץ, ועליה השמים. \u0003אמר להם בית שמאי לבית הלל: לדבריכם אדם עושה שרפרף\u0004 להניח עליו רגליו, \u0003ואחר כך עושה כסא?! שנאמר \"כה אמר ה' השמים כסאי והארץ הדם רגלי\"\u0004 (ישעיהו סו, א). \u0003וחכמים אומרים: זה וזה כאחת נבראו, שנאמר: \"אף ידי יסדה ארץ וימיני טפחה שמים קרא אני אליהם יעמדו יחדו\"\u0004 (ישעיהו מח, יג), משמע שנבראו יחד.","ושואלים: \u0003ואידך\u0004 \u0005[והאחרים]\u0006 בית שמאי ובית הלל, לדעתם \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יחדו\"?\u0004 ומשיבים: \u0003דלא משתלפי מהדדי\u0004 \u0005[שאינם נפרדים זה מזה]\u0006 והביטוי \"יחדיו\" איננו מתאר את זמן בריאתם, אלא את האופן שבו הם עומדים. ומעירים: מכל מקום \u0003קשו קראי אהדדי\u0004 \u0005[קשים המקראות זה לזה],\u0006 שפעם מקדים שמים ופעם ארץ! \u0003אמר ריש לקיש: כשנבראו, ברא\u0004 תחילה את ה\u0003שמים ואחר כך ברא\u0004 את \u0003הארץ\u0004 וזה סדר בריאה ראשונה, \u0003וכשנטה\u0004 (פרס, קבעם במקומם) \u0003נטה הארץ ואחר כך נטה שמים.\u0004","אגב כך מסבירים, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 מה מקור המלה \u0003\"שמים\"? אמר ר' יוסי בר חנינא:\u0004 זהו נוטריקון \u0003ששם מים. במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \"שמים\" פירושו — \u0003אש ומים, מלמד שהביאן הקדוש ברוך הוא וטרפן\u0004 (עירבבן) \u0003זה בזה, ועשה מהן רקיע.\u0004","מסופר: \u0003שאל ר' ישמעאל את ר' עקיבא כשהיו מהלכין בדרך, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אתה ששימשת את נחום איש גם זו עשרים ושתים שנה, שהיה\u0004 נחום איש גם זו \u0003דורש כל \"אתין\" שבתורה,\u0004 שכל מילת \"את\" במקרא היה דורש שהיא באה לרבות ולהוסיף דבר מה, \u0003\"את השמים ואת הארץ\"\u0004 (בראשית א, א) \u0003מה היה דורש בהן? אמר ליה\u0004 \u0005[לו]:\u0006 כך היה צריך לדרוש: \u0003אילו נאמר \"\u0004בראשית ברא אלהים \u0003שמים וארץ\", הייתי אומר: שמים — שמו של הקדוש ברוך הוא,\u0004 וכן ארץ. שאף אלה שמותיו הם, \u0003עכשיו שנאמר: \"את השמים ואת הארץ\"\u0004 משמע שאלה הם הנבראים, וברור ש\u0003\"שמים\"\u0004 הם \u0003שמים ממש, \"ארץ\" — ארץ ממש\u0004 ולכך יש כאן צורך במילות \"את\"."],["\u0003\"את הארץ\" למה לי — להקדים שמים לארץ,\u0004 לומר שהשמים נבראו תחילה. נאמר: \u0003\"והארץ היתה תהו ובהו\"\u0004 (בראשית א, ב) ושואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003בשמים אתחיל ברישא\u0004 \u0005[התחיל בתחילה],\u0006 ואם כן \u0003מאי שנא דקא חשיב\u0004 \u0005[מה שונה,\u0006 מדוע, \u0005מונה\u0006 את\u0005]\u0006 \u0003מעשה ארץ\u0004 קודם? \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: משל למלך בשר ודם שאמר לעבדיו: השכימו לפתחי. השכים ומצא נשים ואנשים\u0004 ממתינים לו. \u0003למי משבח — למי שאין דרכו להשכים והשכים,\u0004 לנשים. כן בבריאת הארץ, כיון שהיא דבר גשמי ותחתון, ונבראה יחד עם השמים, ראוי לדבר בה יותר.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי אומר: אוי להם לבריות שרואות ואינן יודעות מה רואות, עומדות ואין יודעות על מה הן עומדות.\u0004 והוא מפרט: \u0003הארץ על מה עומדת — על העמודים, שנאמר: \"המרגיז ארץ ממקומה ועמודיה יתפלצון\"\u0004 (איוב ט, ו). ה\u0003עמודים\u0004 האלה עומדים \u0003על המים\u0004 — \u0003שנאמר: \"לרקע הארץ על המים\"\u0004 (תהלים קלו, ו). \u0003מים\u0004 אלה עומדים \u0003על ההרים\u0004 — \u0003שנאמר: \"על הרים יעמדו מים\"\u0004 (תהלים קד, ו). \u0003הרים\u0004 עומדים על ה\u0003רוח\u0004 — \u0003שנאמר: \"כי הנה יוצר הרים וברא רוח\"\u0004 (עמוס ד, יג). \u0003רוח\u0004 עומד \u0003בסערה\u0004 — \u0003שנאמר: \"רוח סערה עשה דברו\"\u0004 (תהלים קמח, ח). \u0003סערה תלויה בזרועו של הקדוש ברוך הוא\u0004 — \u0003שנאמר: \"ומתחת זרעת עולם\"\u0004 (דברים לג, כז), לומר שהעולם כולו נתון על זרועותיו של הקדוש ברוך הוא.","\u0003וחכמים אומרים: על שנים עשר עמודים עומדת\u0004 הארץ, \u0003שנאמר: \"יצב גבלת עמים למספר בני ישראל\"\u0004 (דברים לב, ח). וכשם שמספר בני ישראל (יעקב) שנים עשר, כך עמודי העולם הם שנים עשר. \u0003ויש אומרים: שבעה עמודים\u0004 הם, \u0003שנאמר: \"חצבה עמודיה שבעה\"\u0004 (משלי ט, א). \u0003ר' אלעזר בן שמוע אומר:\u0004 הארץ עומדת \u0003על עמוד אחד, וצדיק שמו, שנאמר: \"וצדיק יסוד עולם\"\u0004 (משלי י, כה).","\u0003אמר ר' יהודה: שני רקיעים הן, שנאמר: \"הן לה' אלהיך השמים ושמי השמים\"\u0004 (דברים י, יד), משמע: שמים, ושמים מעל השמים.","\u0003ריש לקיש אמר: שבעה\u0004 רקיעים הם, \u0003ואלו הן: וילון, רקיע, שחקים, זבול, מעון, מכון, ערבות.\u0004 ומפרשים מה תפקידו של כל אחד מהם: \u0003וילון\u0004 הוא רקיע ש\u0003אינו משמש כלום,\u0004 ואין בתוכו דבר, \u0003אלא נכנס שחרית ויוצא ערבית, ומחדש בכל יום מעשה בראשית\u0004 שיהיה שינוי בעולם, \u0003שנאמר: \"הנוטה כדק שמים וימתחם כאהל לשבת\"\u0004 (ישעיה מ, כב). \u0003רקיע\u0004 הוא זה \u0003שבו חמה ולבנה כוכבים ומזלות קבועין, שנאמר: \"ויתן אתם אלהים ברקיע השמים\"\u0004 (בראשית א, יז). \u0003שחקים — שבו רחיים עומדות וטוחנות מן לצדיקים, שנאמר: \"ויצו שחקים ממעל ודלתי שמים פתח. וימטר עליהם מן לאכל\u0004 ודגן שמים נתן למו\u0003\"\u0004 (תהלים עח, כג-כד).","\u0003זבול — שבו ירושלים\u0004 של מעלה, \u0003ובית המקדש\u0004 של מעלה, \u0003ומזבח\u0004 של מעלה \u0003בנוי, ו\u0004המלאך \u0003מיכאל, השר הגדול, עומד ומקריב עליו קרבן, שנאמר: \"בנה בניתי בית זבל לך מכון לשבתך עולמים\"\u0004 (מלכים א' ח, יג). \u0003ומנלן דאיקרי\u0004 \u0005[ומנין לנו ש\u0006זבול \u0005נקרא]\u0006 \u0003\"שמים\" — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הבט משמים וראה מזבל קדשך ותפארתך\"\u0004 (ישעיהו סג, טו).","\u0003מעון — שבו כיתות של מלאכי השרת, שאומרות שירה בלילה וחשות\u0004 (שותקות) \u0003ביום, מפני כבודן של ישראל\u0004 שלא להתחרות עימם באמירת השירה שלהם, \u0003שנאמר: \"יומם יצוה ה' חסדו ובלילה שירה עמי\"\u0004 (תהלים מב, ט) ששירת המלאכים עם ה' היא רק בלילה.","על אותו כתוב \u0003אמר ריש לקיש: כל העוסק בתורה בלילה — הקדוש ברוך הוא מושך עליו חוט של חסד ביום, שנאמר: \"יומם יצוה ה' חסדו\", ומה טעם \"יומם יצוה ה' חסדו\"\u0004 — \u0003משום \"ובלילה שירה עמי\",\u0004 שירת התורה. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ש\u0003אמר ריש לקיש: כל העוסק בתורה בעולם הזה, שהוא דומה ללילה, הקדוש ברוך הוא מושך עליו חוט של חסד לעולם הבא, שהוא דומה ליום, שנאמר: \"יומם יצוה ה' חסדו ובלילה שירה עמי\".\u0004","ובאותו ענין \u0003אמר ר' לוי: כל הפוסק מדברי תורה ועוסק בדברי שיחה — מאכילין אותו גחלי רתמים, שנאמר: \"הקטפים מלוח עלי שיח ושרש רתמים לחמם\"\u0004 (איוב ל, ד). שאלו המפסיקים (\"קוטפים\") דברי תורה שנתנו מן הלוחות (\"מלוח\") לשם שיחה סתם (\"עלי שיח\") — נענשים באכילת גחלים הנעשים מ\"שורש רתמים\". \u0003ומנלן דאיקרי\u0004 \u0005[ומנין לנו שנקרא]\u0006 מעון זה \u0003\"שמים\" — שנאמר: \"השקיפה ממעון קדשך מן השמים\"\u0004 (דברים כו, טו).","\u0003מכון — שבו אוצרות שלג ואוצרות ברד, ועליית טללים רעים, ועליית אגלים\u0004 (טיפות), \u0003וחדרה של סופה וסערה, ומערה של קיטור. ודלתותיהן\u0004 של כל אלה הן \u0003אש,\u0004 ומנין שיש לו אוצרות לדברים רעים? \u0003שנאמר: \"יפתח ה' לך את אוצרו הטוב\u0004 את השמים\u0003\"\u0004 (דברים כח, יב), ומכאן שיש לו גם אוצר אחר, שאינו טוב.","ושואלים: \u0003הני\u0004 \u0005[אותם]\u0006 דברים שמנינו, \u0003ברקיעא איתנהו\u0004 \u0005[\u0006וכי \u0005בשמים\u0006 הם \u0005מצויים]\u0006 \u0003הני בארעא איתנהו\u0004 \u0005[\u0006הלא \u0005אלה בארץ\u0006 הם \u0005מצויים]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הללו את ה' מן הארץ תנינים וכל תהמות אש וברד שלג וקיטור רוח סערה עשה דברו\"\u0004 (תהלים קמח, ז), משמע שכל אלה מן הארץ הם! \u0003אמר רב יהודה אמר רב: דוד ביקש עליהם רחמים\u0004 שלא ישארו בשמים, \u0003והורידן לארץ. אמר לפניו: רבונו של עולם, \"לא אל חפץ רשע אתה לא יגרך (במגורך) רע\"\u0004 (תהלים ה, ה), כלומר, הלא \u0003צדיק אתה ה', לא יגור במגורך,\u0004 בסמוך לך, דבר שיש בו \u0003רע,\u0004 מוטב שיהיו סמוכים אלינו. \u0003ומנלן דאיקרי\u0004 \u0005[ומניין לנו שנקרא]\u0006 מקום זה \u0003\"שמים\"\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"רעב כי יהיה... דבר כי יהיה... כל נגע כל מחלה\" (מלכים א' ח, לז), ובהמשך נאמר: \u0003\"ואתה תשמע השמים מכון שבתך\"\u0004 (מלכים א' ח, לט).","\u0003ערבות\u0004 הוא רקיע \u0003שבו צדק משפט וצדקה, גנזי חיים וגנזי שלום וגנזי ברכה, ונשמתן של צדיקים, ורוחות ונשמות שעתיד להיבראות, וטל שעתיד הקדוש ברוך הוא להחיות בו מתים.\u0004 וראיה לדברים: \u0003צדק ומשפט\u0004 מצויים בשמים \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"צדק ומשפט מכון כסאך\"\u0004 (תהלים פט, טו). \u0003צדקה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וילבש צדקה כשרין\"\u0004 (ישעיה נט, יז). \u0003גנזי חיים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי עמך מקור חיים\"\u0004 (תהלים לו, י). \u0003וגנזי שלום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויקרא לו ה' שלום\"\u0004 (שופטים ו, כד), משמע ש\"שלום\" הוא שמו של הקדוש ברוך הוא, וסמוך אליו. \u0003וגנזי ברכה — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ישא ברכה מאת ה'\"\u0004 (תהלים כד, ה).","\u0003נשמתן של צדיקים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיתה נפש אדני צרורה בצרור החיים את ה' אלהיך\"\u0004 (שמואל א' כה, כט). \u0003רוחות ונשמות שעתיד להיבראות — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי רוח מלפני יעטוף ונשמות אני עשיתי\"\u0004 (ישעיה נז, טז), משמע, הרוח שעתידה לצאת לעולם, לעטוף גוף, נמצאת לפני ה'. \u0003וטל שעתיד הקדוש ברוך הוא להחיות בו מתים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"גשם נדבות תניף אלהים נחלתך ונלאה אתה כוננתה\"\u0004 (תהלים סח, י).","\u0003שם\u0004 ברקיעים \u0003אופנים ושרפים וחיות הקדש, ומלאכי השרת, וכסא הכבוד, מלך אל חי רם ונשא שוכן עליהם בערבות,\u0004 ומביאים ראיה \u0003שנאמר: \"סלו לרכב בערבות ביה שמו\"\u0004 (תהלים סח, ה) \u0003ומנלן דאיקרי\u0004 \u0005[מניין לנו ש\u0006ערבות \u0005נקראו]\u0006 \u0003\"שמים\"? אתיא\u0004 \u0005[בא\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה של המילים \u0003\"רכיבה\" \"רכיבה\", כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"סלו לרכב בערבות\" וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"רכב שמים בעזרך\"\u0004 (דברים לג, כו).","\u0003וחשך וענן וערפל מקיפין אותו\u0004 — \u0003שנאמר: \"ישת חשך סתרו סביבותיו סכתו חשכת מים עבי שחקים\"\u0004 (תהלים יח, יב). ושואלים: \u0003ומי איכא חשוכא קמי שמיא\u0004 \u0005[והאם יש חושך לפני השמים,\u0006 לפני הקדוש ברוך הוא\u0005]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"הוא גלא עמיקתא ומסתרתא ידע מה בחשוכא ונהורא עמיה שרי\"\u0004 \u0005[הוא מגלה עמוקות ונסתרות יודע מה בחושך, והאור עמו מצוי]\u0006 (דניאל ב, כב), משמע שליד הקדוש ברוך הוא מצוי אור ולא חושך! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שיש עמו רק אור, מדובר"],["\u0003בבתי גואי\u0004 \u0005[בבתים פנימיים],\u0006 שם יש רק אור, \u0003הא\u0004 \u0005[זה]\u0006 שיש חושך סביבו, מדובר \u0003בבתי בראי\u0004 \u0005[בבתים חיצוניים].\u0006 \u0003ואמר רב אחא בר יעקב: עוד רקיע אחד יש\u0004 מעל לאלה, שהוא \u0003למעלה מראשי החיות, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ודמות על ראשי החיה רקיע כעין הקרח הנורא\"\u0004 (יחזקאל א, כב).","ומעירים: \u0003עד כאן יש לך רשות לדבר, מכאן ואילך — אין לך רשות לדבר. שכן כתוב בספר בן סירא: במופלא ממך אל תדרוש, ובמכוסה ממך אל תחקור, במה שהורשית התבונן, אין לך עסק בנסתרות. תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר רבן יוחנן בן זכאי: מה תשובה השיבתו בת קול לאותו רשע\u0004 נבוכדנאצר \u0003בשעה שאמר \"אעלה על במתי עב אדמה לעליון\"\u0004 (ישעיה יד, יד), שאמר בלבו לעלות לשמים — \u0003יצתה בת קול ואמרה לו: רשע בן רשע, בן בנו,\u0004 כלומר, מצאצאיו והולך בדרכיו \u0003של נמרוד הרשע, שהמריד\u0004 את \u0003כל העולם כולו עליו\u0004 (כלומר, על הקדוש ברוך הוא) \u0003ב\u0004זמן \u0003מלכותו;\u0004","\u0003כמה שנותיו של אדם — שבעים שנה, שנאמר: \"ימי שנותינו בהם שבעים שנה ואם בגבורת שמונים שנה\"\u0004 (תהלים צ, י), \u0003והלא מן הארץ עד לרקיע מהלך חמש מאות שנה, ועוביו של רקיע\u0004 עצמו \u0003מהלך חמש מאות שנה, וכן בין כל רקיע ורקיע.\u0004","ו\u0003למעלה מהן\u0004 מכל הרקיעים נמצאות \u0003חיות הקדש; רגלי החיות כנגד\u0004 כל הרקיעים \u0003כולם, קרסולי החיות כנגד כולן, שוקי החיות כנגד כולן, רכובי\u0004 (ברכי) \u0003החיות כנגד כולן, ירכי החיות כנגד כולן, גופי החיות כנגד כולן, צוארי החיות כנגד כולן, ראשי החיות כנגד כולן, קרני החיות כנגד כולן.\u0004 ו\u0003למעלה מהן כסא\u0004 ה\u0003כבוד; רגלי כסא הכבוד כנגד כולן, כסא הכבוד כנגד כולן,\u0004 ו\u0003מלך אל חי וקים רם ונשא שוכן עליהם. ואתה אמרת \"אעלה על במתי עב אדמה לעליון\"\u0004 — \u0003\"אך אל שאול תורד אל ירכתי בור\"\u0004 (ישעיהו יד, יד – טו).","שנינו במשנה: \u0003ולא דורשים במרכבה ביחיד. תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: אבל מוסרין לו\u0004 ליחיד \u0003ראשי פרקים\u0004 בענין זה, והוא מבין מדעתו. \u0003אמר ר' זירא: אין מוסרין ראשי פרקים\u0004 של מעשה מרכבה \u0003אלא לאב בית דין\u0004 שבשל חכמתו ומעשיו הוא צריך לדעת, \u0003ולכל מי שלבו דואג בקרבו,\u0004 שדואג על חטאיו ומשתדל לעשות תשובה שלימה. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאין מדובר בשני אישים, אלא באב בית דין \u0003והוא שלבו דואג בקרבו.\u0004","\u0003אמר ר' אמי: אין מוסרין סתרי תורה אלא למי שיש בו חמשה דברים: \"שר חמשים, ונשוא פנים, ויועץ, וחכם חרשים, ונבון לחש\"\u0004 (ישעיהו ג, ג). \u0003ו\u0004עוד \u0003אמר ר' אמי: אין מוסרין דברי תורה לגוי, שנאמר: \"לא עשה כן לכל גוי ומשפטים בל ידעום\"\u0004 (תהלים קמז, כ).","מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לר' אלעזר: תא ואגמרך\u0004 \u0005[בוא ואלמדך]\u0006 \u0003במעשה המרכבה, אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר: עדיין \u0003לא קשאי\u0004 \u0005[זקנתי]\u0006 דיי, וללימוד זה צריך שיהא אדם מיושב בדעתו מאוד. \u0003כי קש\u0004 \u0005[כאשר הזדקן] —\u0006 \u0003נח נפשיה\u0004 \u0005[נחה נפשו,\u0006 כבר נפטר\u0005]\u0006 \u0003ר' יוחנן, אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אסי: תא ואגמרך\u0004 \u0005[בוא ואלמדך]\u0006 \u0003במעשה מרכבה. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי זכאי גמירתא\u0004 \u0005[אילו זכיתי הייתי לומד]\u0006 זאת \u0003מר' יוחנן רבך,\u0004 ואם כן נראה שאין אני ראוי לכך.","מסופר: \u0003רב יוסף הוה גמיר\u0004 \u0005[היה לומד,\u0006 יודע\u0005]\u0006 ב\u0003מעשה המרכבה,\u0004 ואילו \u0003סבי\u0004 \u0005[זקני]\u0006 \u0003פומבדיתא הוו תנו\u0004 \u0005[היו שונים]\u0006 \u0003במעשה בראשית. אמרו ליה\u0004 \u0005[לו]\u0006 לרב יוסף: \u0003ליגמור לן מר\u0004 \u0005[שילמד אותנו אדוני]\u0006 \u0003מעשה מרכבה. אמר להו\u0004 \u0005[להם]:\u0006 \u0003אגמרון לי\u0004 \u0005[למדו\u0006 אתם \u0005אותי]\u0006 \u0003מעשה בראשית. בתר דאגמרון\u0004 \u0005[אחרי שלימדוהו]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ליגמרון מר\u0004 \u0005[שילמדנו אדוני]\u0006 \u0003במעשה מרכבה! אמר להו\u0004 \u0005[להם]:\u0006 \u0003תנינא בהו\u0004 \u0005[שנינו בהם]\u0006 על סודות התורה: \u0003\"דבש וחלב תחת לשונך\"\u0004 (שיר השירים ד, יא), והכוונה בזה היא — \u0003דברים המתוקין מדבש וחלב יהו תחת לשונך.\u0004 כלומר, דברים אלה אין לומר אותם, ומי שיודע אותם אסור לו לגלותם.","\u0003ר' אבהו אמר\u0004 ראיה אחרת לאותו רעיון \u0003מהכא\u0004 \u0005[מכאן],\u0006 ממה שנאמר: \u0003\"כבשים ללבושך\"\u0004 (משלי כז, כו), שהוא דורש כאילו היה כתוב (ב־\"ש\") כבשים — \u0003דברים שהן כבשונו של עולם\u0004 (כבושים ונסתרים) \u0003יהו תחת לבושך\u0004 ואל תגלה אותם. כיון שראו שאינו עומד ללמד אותם \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003תנינן בהו\u0004 \u0005[שנינו בהם]\u0006 במעשה מרכבה האמור בספר יחזקאל \u0003עד\u0004 לפסוק \u0003\"ויאמר אלי בן אדם\"\u0004 (יחזקאל ב, א). \u0003אמר להו\u0004 \u0005[להם]:\u0006 אם כן — \u0003הן הן מעשה המרכבה,\u0004 שאלה הם עיקרי הדברים בנושא זה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: \u0003עד היכן מעשה המרכבה? רבי אומר: עד \"וארא\" בתרא\u0004 \u0005[האחרון]\u0006 (יחזקאל א, כז) ואין פסוק זה בכלל, \u0003ר' יצחק אומר: עד\u0004 המלה \u0003\"החשמל\"\u0004 (יחזקאל א, כז), שלא כדעת רב יוסף שמעשה מרכבה נמשך עד סוף הפרק? ומתרצים: \u0003עד \"וארא\" מגמרינן\u0004 \u0005[מלמדים אנו]\u0006 למי שראוי לכך, \u0003מכאן ואילך — מסרינן\u0004 \u0005[מוסרים\u0006 אנו\u0005]\u0006 רק \u0003ראשי פרקים. איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003עד \"וארא\" מסרינן\u0004 \u0005[מוסרים]\u0006 \u0003ראשי פרקים, מכאן ואילך, אם הוא חכם\u0004 ו\u0003מבין מדעתו — אין\u0004 \u0005[כן],\u0006 מוסרים לו, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא — לא\u0004 ימסרו לו אף ראשי פרקים.","ושואלים: \u0003ומי דרשינן\u0004 \u0005[והאם\u0006 בכלל \u0005דורשים אנו]\u0006 ועוסקים \u0003בחשמל\u0004 שבמעשה מרכבה? \u0003והא ההוא ינוקא\u0004 \u0005[והרי\u0006 אותו \u0005תינוק,\u0006 צעיר אחד\u0005],\u0006 ש\u0003דרש בחשמל ונפקא נורא ואכלתיה\u0004 \u0005[ויצאה אש ואכלתו],\u0006 משמע שיש סכנה גדולה בדבר! ומשיבים: \u0003שאני ינוקא, דלאו מטי זמניה\u0004 \u0005[שונה התינוק,\u0006 הילד, \u0005שלא הגיע\u0006 עדיין \u0005זמנו]\u0006 לעסוק בזה, ולכן קרה לו מה שקרה.","\u0003אמר רב יהודה: ברם\u0004 (אכן) \u0003זכור אותו האיש לטוב, וחנניה בן חזקיה שמו,\u0004 ש\u0003אלמלא הוא נגנז ספר יחזקאל.\u0004 ומדוע רצו לגונזו — מפני שמצאו \u0003שהיו דבריו סותרין דברי תורה,\u0004 כי בפרקיו האחרונים ישנם דינים שאינם כדיני התורה. \u0003מה עשה? העלו לו שלוש מאות גרבי\u0004 (כדי) \u0003שמן\u0004 למאור ולמזון, \u0003וישב בעלייה ודרשו\u0004 לישבו עם דברי תורה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בתינוק אחד שהיה קורא בבית רבו בספר יחזקאל והיה מבין בחשמל, ויצאה אש מחשמל ושרפתו, וביקשו לגנוז\u0004 את \u0003ספר יחזקאל\u0004 מפני הסכנה שבו. \u0003אמר להם חנניה בן חזקיה: אם זה חכם\u0004 כלומר, אם ילד זה הוא במקרה חכם — האם \u0003הכל חכמים הן\u0004 שמסוגלים להבין בספר יחזקאל?","ושואלים: \u0003מאי\u0004 \u0005[מהו\u0006 עניינו\u0005]\u0006 של ה\u0003חשמל? אמר רב יהודה:\u0004"],["\u0003חיות אש ממללות\u0004 (מדברות) וחשמל הוא כעין קיצור של מילים אלה (חיות אש ממללות). \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 התנא על כך: \u0003עתים חשות, עתים ממללות. בשעה שהדיבור יוצא מפי הקדוש ברוך הוא — חשות\u0004 (שותקות) \u0003ובשעה שאין הדיבור יוצא מפי הקדוש ברוך הוא — ממללות.\u0004","נאמר שם: \u0003\"והחיות רצוא ושוב כמראה הבזק\"\u0004 (יחזקאל א, יד) ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"רצוא ושוב\"? אמר רב יהודה: כאור היוצא מפי הכבשן,\u0004 שהלהבה פורצת החוצה וחוזרת מדי רגע. \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כמראה הבזק\"? אמר ר' יוסי בר חנינא: כאור\u0004 (אש) \u0003היוצא מבין החרסים\u0004 כשצורפים את הזהב והאש יוצאת מביניהם (ומפרש \"בזק\" לשון חרסים, שברי חרס).","נאמר: \u0003\"וארא והנה רוח סערה באה מן הצפון ענן גדול ואש מתלקחת ונגה לו סביב ומתוכה כעין החשמל מתוך האש\"\u0004 (יחזקאל א, ד), ושואלים: \u0003להיכן אזל\u0004 \u0005[הלך]\u0006 אותו רוח? \u0003אמר רב יהודה אמר רב: שהלך לכבוש את כל העולם כולו\u0004 שיהיה \u0003תחת\u0004 ממשלתו של \u0003נבוכדנצר הרשע. וכל כך למה\u0004 היה צריך לכבוש את העולם בשבילו? \u0003שלא יאמרו אומות העולם: ביד אומה שפלה מסר הקדוש ברוך הוא את בניו,\u0004 שכיון שנגזר שתיפול מלכות ישראל בידו, עשאו הקדוש ברוך הוא כובש־עולם גדול, שלא תהיה בושה לישראל במפלתם על ידו. \u0003אמר הקדוש ברוך הוא\u0004 על כך: \u0003מי גרם לי שאהיה שמש לעובדי פסילים\u0004 ואצטרך לעשות את מלחמותיהם — \u0003עונותיהן של ישראל הן\u0004 ש\u0003גרמו לי\u0004 לכך.","נאמר שם: \u0003\"וארא החיות והנה אופן אחד בארץ אצל החיות\"\u0004 (יחזקאל א, טו), \u0003אמר ר' אלעזר:\u0004 \"אופן\" זה הוא \u0003מלאך אחד שהוא עומד בארץ, וראשו מגיע אצל החיות. במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 התנא: מלאך זה \u0003סנדלפון שמו, הגבוה מחברו מהלך חמש מאות שנה. ו\u0004הוא \u0003עומד אחורי המרכבה וקושר כתרים לקונו\u0004 (הקדוש ברוך הוא). ושואלים: \u0003איני\u0004 \u0005[ו\u0006כי \u0005כן הוא]\u0006 שאפשר שיקשור כתרים לקונו? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ברוך כבוד ה' ממקומו\"\u0004 (יחזקאל ג, יב), \u0003מכלל\u0004 הדברים אתה למד ש\u0003מקומו ליכא דידע ליה\u0004 \u0005[אין מי שיודע אותו]\u0006 וכיצד יכול לקשור לו כתרים? אלא כך נעשה הדבר, \u0003דאמר שם אתגא ואזל ויתיב ברישיה\u0004 \u0005[שאומר שם על הכתר, ו\u0006הכתר \u0005הולך\u0006 מאליו \u0005ויושב בראשו\u0006 של ה'\u0005].\u0006","\u0003אמר רבא: כל\u0004 הדברים \u0003שראה יחזקאל ראה\u0004 גם \u0003ישעיה\u0004 הנביא, אלא שהנביא ישעיה לא מצא לנחוץ לתאר כל זה. ומשל לדבר: \u0003למה יחזקאל דומה — לבן כפר שראה את המלך,\u0004 שכיון שאינו רגיל בכך, הוא מתרגש ומתפעל מכל הדברים והקישוטים שנמצאים בארמונו של המלך ומדבר אודותיו, \u0003ולמה ישעיה דומה — לבן כרך שראה את המלך\u0004 שהוא שם לב לעצם הפגישה עם המלך ולא לדברים שמסביבו. \u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"אשירה לה' כי גאה גאה\"\u0004 (שמות טו, א), למה נכפלה המלה \"גאה\"? — נאה \u0003שירה למי שמתגאה על הגאים,\u0004 שהוא נעלה על העליונים. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מלך שבחיות — ארי, מלך שבבהמות — שור, מלך שבעופות — נשר, ואדם מתגאה\u0004 ומשתלט \u0003עליהן, והקדוש ברוך הוא מתגאה על כולן ועל כל העולם כולו\u0004 שהרי חיות המרכבה הן שור, ארי, נשר ואדם.","בענין החיות שבמרכבה שואלים: \u0003כתוב אחד אומר: \"ודמות פניהם פני אדם ופני אריה אל הימין לארבעתם ופני שור מהשמאל לארבעתן\"\u0004 (יחזקאל א, י), \u0003וכתיב\u0004 \u0005[ונאמר\u0006 גם\u0005]:\u0006 \u0003\"וארבעה פנים לאחד פני האחד פני הכרוב ופני השני פני אדם והשלישי פני אריה והרביעי פני נשר\"\u0004 (יחזקאל י, יד), \u0003ואילו\u0004 פני \u0003שור לא קא חשיב\u0004 \u0005[אינו מונה\u0006 שם\u0005]!\u0006 \u0003אמר ריש לקיש: יחזקאל ביקש עליו רחמים\u0004 על פני השור, \u0003והפכו לכרוב.\u0004 וכך \u0003אמר לפניו: רבונו של עולם!\u0004 וכי \u0003קטיגור יעשה סניגור?\u0004 שכן פני שור מזכירים את חטא העגל של ישראל ומוטב שיהיו פנים אחרות במרכבה.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כרוב\"? אמר ר' אבהו: כרביא\u0004 \u0005[כתינוק],\u0006 \u0003שכן בבבל קורין לינוקא\u0004 \u0005[לתינוק]\u0006 \u0003רביא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אלא מעתה\u0004 לפי פירוש זה, מה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"פני האחד פני הכרוב ופני השני פני אדם והשלישי פני אריה והרביעי פני נשר\"\u0004 (יחזקאל י, יד), הרי לכאורה \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003פני כרוב היינו\u0004 \u0005[זהו]\u0006 \u0003פני אדם,\u0004 ומה ההבדל ביניהם? השיב לו: ההבדל הוא שפני אדם הם \u0003אפי רברבי\u0004 \u0005[פנים גדולות]\u0006 ופני כרוב הם \u0003ואפי זוטרי\u0004 \u0005[ופנים קטנות]\u0006 של תינוק.","ועוד שואלים: \u0003כתוב אחד אומר: \"שש כנפים שש כנפים לאחד\u0004 בשתים יכסה פניו ובשתים יכסה רגליו ובשתים יעופף\u0003\"\u0004 (ישעיהו ו, ב), \u0003וכתוב אחד אומר: \"וארבעה פנים לאחת וארבע כנפים לאחת להם\"\u0004 (יחזקאל א, ו)? ומשיבים: \u0003לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003כאן — בזמן שבית המקדש קיים\u0004 היו שש כנפים, \u0003כאן — בזמן שאין בית המקדש קיים, כביכול\u0004 (כאילו), \u0003שנתמעטו כנפי החיות\u0004 ואינן אלא ארבע.","ושואלים: \u0003הי מינייהו אימעוט\u0004 \u0005[אלו מהן,\u0006 איזה כנפים \u0005התמעטו]?\u0006 \u0003אמר רב חננאל אמר רב: אותן שאומרות שירה בהן.\u0004 וראיה שאומרות שירה בכנפיהן: \u0003כתיב הכא \"ובשתים יעופף וקרא זה אל זה ואמר\"\u0004 (ישעיהו ו, ב-ג), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"התעיף עיניך בו ואיננו\"\u0004 (משלי כג, ה) שמעוף זה בטל ואיננו עוד.","\u0003ורבנן אמרי\u0004 \u0005[חכמים אומרים]:\u0006 הכנפים שנתמעטו הן \u0003אותן\u0004 כנפים \u0003שמכסות בהן רגליהם, שנאמר: \"ורגליהם רגל ישרה\"\u0004 (יחזקאל א, ז), \u0003ואי לאו דאימעוט\u0004 \u0005[ואם לא שהתמעטו]\u0006 כנפים אלה — \u0003מנא הוה ידע\u0004 \u0005[מניין היה יודע]\u0006 איך נראות רגליהם? אלא ודאי כבר לא היו מכוסות. ודוחים: מכאן אין ראיה, \u0003דלמא דאיגלאי וחזיא ליה\u0004 \u0005[שמא שנתגלו\u0006 לפי שעה \u0005וראה אותם].\u0006 \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך]\u0006 שרק לפי שעה נגלו, מה שנאמר \u0003\"ודמות פניהם פני אדם\"\u0004 (יחזקאל א, י), \u0003הכי נמי דאימעוט\u0004 \u0005[כך גם כן שהתמעטו]\u0006 כנפים המכסות את פניהם?! \u0003אלא\u0004 אתה חייב לומר \u0003דאיגלאי וחזיא ליה\u0004 \u0005[שנתגלו וראה אותם],\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן] —\u0006 \u0003דאיגלאי וחזיא ליה\u0004 \u0005[שנתגלו וראה אותם].\u0006","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003בשלמא אפיה\u0004 \u0005[נניח פניו] —\u0006 \u0003אורח ארעא לגלויי קמיה רביה\u0004 \u0005[דרך ארץ לגלות\u0006 פניו \u0005לפני רבו],\u0006 ולכן יתכן שמגלות פניהן לפרקים. אבל \u0003כרעיה לאו אורח ארעא לגלויי קמיה רביה\u0004 \u0005[רגליו אין זה דרך ארץ לגלות לפני רבו],\u0006 אלא ודאי שלא היו להם כנפים לכסות רגליהם.","ועוד בביאור סתירות בנושאים אלה: \u0003כתוב אחד אומר: \"אלף אלפין ישמשונה ורבו רבבן קדמוהי יקומון\"\u0004 \u0005[אלף אלפים ישרתוהו ורבוא רבבות לפניו יעמודו]\u0006 (דניאל ז, י), \u0003וכתוב אחד אומר: \"היש מספר לגדודיו\"\u0004 (איוב כה, ג), משמע שאין להם מספר, אפילו לא אלף אלפים! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן — בזמן שבית המקדש קיים\u0004 אין מספר, \u0003כאן בזמן שאין בית המקדש קיים, כביכול שנתמעטה פמליא של מעלה.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003רבי אומר משום אבא יוסי בן דוסאי: \"אלף אלפין ישמשונה\"\u0004 הוא \u0003מספר\u0004 המלאכים ב\u0003גדוד אחד,\u0004 אבל \u0003\"ולגדודיו — אין מספר\". ור' ירמיה בר אבא אמר:\u0004 אין כאן סתירה מעיקרה, משום ש\u0003\"אלף אלפין ישמשונה\"\u0004 אין משמעו שבהם משרתים את הקדוש ברוך הוא, אלא \u0003לנהר דינור\u0004 הם משמשים, \u0003שנאמר: \"נהר דינור נגד ונפק מן קדמוהי אלף אלפין ישמשונה ורבו רבבן קדמוהי יקומון\"\u0004 \u0005[נהר של אש נובע ויוצא מלפניו, אלף אלפים ישרתוהו וריבוא רבבות לפניו יעמדו]\u0006 (דניאל ז, י), ואילו לגדודי משרתי ה' אכן אין כל מספר.","ושואלים: \u0003מהיכן נפיק\u0004 \u0005[מהיכן יוצא]\u0006 נהר זה? ומשיבים: \u0003מזיעתן של חיות. ולהיכן שפיך\u0004 \u0005[\u0006הוא \u0005נשפך]?\u0006 \u0003אמר רב זוטרא בר טוביה אמר רב: על ראש רשעים בגיהנם, שנאמר: \"הנה סערת ה' חמה יצאה וסער מתחולל על ראש רשעים יחול\"\u0004 (ירמיה כג, יט). \u0003ורב אחא בר יעקב אמר:\u0004 הנהר זורם \u0003על אשר קומטו,\u0004 על אותם דורות שלא נבראו, \u0003שנאמר: \"אשר קמטו ולא עת נהר יוצק יסודם\"\u0004 (איוב כב, טז), וכאן הרמז שנהר דינור נשפך עליהם. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' שמעון החסיד\u0004 בפירוש פסוק זה: \u0003אלו\u0004 \"אשר קומטו\" הם \u0003תשע מאות ושבעים וארבע דורות שקומטו\u0004 (שהיו צריכים) \u0003להיבראות\u0004"]]};
